INSERT INTO `lists_lang` (`id`, `main_id`, `lang`, `title`, `anons`, `body`, `anonsImage`, `bodyImage`, `views`, `enabled`, `creator_id`, `modifier_id`, `created_at`, `updated_at`, `pdf`) VALUES
(570, 382, 'oz', 'БУЮК АЖДОДЛАРИМИЗ МЕРОСИ - БУТУН ИНСОНИЯТНИНГ МАЪНАВИЙ БОЙЛИГИ', 'БУЮК АЖДОДЛАРИМИЗ МЕРОСИ - БУТУН ИНСОНИЯТНИНГ МАЪНАВИЙ БОЙЛИГИ', '<p style=\"text-align: center;\"><strong><big>БУЮК АЖДОДЛАРИМИЗ МЕРОСИ - БУТУН ИНСОНИЯТНИНГ МАЪНАВИЙ БОЙЛИГИ</big></strong></p>\r\n\r\n<p style=\"text-align: justify;\"><big>Бугун &laquo;Андижон ҳудудий электр тармоқлари корхонаси&raquo; акциядорлик жамиятида буюк мутафаккир шоир, қомусий олим, улуғ давлат арбоби Заҳириддин Муҳаммад Бобур таваллудининг 537 йиллиги муносабати билан &ldquo;Буюк боболаримизни ёд этиб&rdquo; мавзуида корхона ишчи-ходимлари иштирокида маънавий-маърифий тадбир ташкил қилинди.&nbsp;</big></p>\r\n\r\n<p style=\"text-align: justify;\"><big><img alt=\"\" src=\"http://het.uz/uploads/2ee950d4-8b8c-b08e-90fe-b8625fcc009f_media_.jpg\" /></big></p>\r\n\r\n<p style=\"text-align: justify;\"><big>Тадбирни кириш сўзи билан очган жамият бош директори Аҳаджон Жўраев буюк бобомиз ижоди ва бизга қолдирган улкан меъросининг инсоният тарихида ва келажак авлодлар ҳаётидаги аҳамияти ҳақида гапириб ўтди. </big></p>\r\n\r\n<p style=\"text-align: justify;\"><big><img alt=\"\" src=\"http://het.uz/uploads/d836e049-334f-ed13-842a-3bee11ae9096_media_.jpg\" /></big></p>\r\n\r\n<p style=\"text-align: justify;\"><big><img alt=\"\" src=\"http://het.uz/uploads/c547d9db-9dcb-9674-ab82-31973da41d33_media_.jpg\" /></big></p>\r\n\r\n<p style=\"text-align: justify;\"><big>Тадбирнинг бадиий қисмида жамият фаол ходимларининг &ldquo;Буюк аждодларимиз мероси - бутун инсониятнинг маънавий бойлиги&rdquo; мавзуидаги маърузалари тингланди.</big></p>\r\n\r\n<p style=\"text-align: justify;\"><big>Шу билан бирга корхонада ишлаётган ёшлар ўзлари ёд олган&nbsp; ғазал, рубойи ва туюқлардан парчаларни шеърий мунозара (пародия) шаклида айтиб, шу орқали тадбирнинг юқори савияда ўтишига ҳиссаларини қўшишди. Бобур ижодидан келтирилган шеърий парчалар тадбир иштирокчилари қалбидан чуқур жой эгаллаганини алоҳида таъкидлаб ўтиш жоиз.</big></p>\r\n\r\n<p style=\"text-align: justify;\"><big><img alt=\"\" src=\"http://het.uz/uploads/43066cb2-7b05-223a-b7aa-472897dcabd4_media_.jpg\" style=\"width: 720px; height: 480px;\" /></big></p>\r\n\r\n<p style=\"text-align: justify;\"><big>Тадбир сўнгида иштирокчилар томонидан Бобурнинг адабиётимизда, қолаверса миллий маънавиятимизда қолдириб кетган олтин мероси ҳақида алоҳида тўхталиб ўтилди. Таъкидланганидек, бизнинг олдимизда турган асосий вазифа келажак авлодга ушбу меросни асраб-авайлаб етказишдир.</big></p>\r\n\r\n<p style=\"text-align: right;\"><strong><big>&ldquo;Андижон ҲЭТК&rdquo; АЖ матбуот хизмати.</big></strong></p>\r\n', '2babe441-23f5-1778-e46f-1006cf9e3169_lists_.jpg', '0eb46a73-3b56-fdad-0928-e7a9726ec956_lists_.jpg', 3367, 1, 5, NULL, 1581512037, 1760969283, ''),
