INSERT INTO `lists_lang` (`id`, `main_id`, `lang`, `title`, `anons`, `body`, `anonsImage`, `bodyImage`, `views`, `enabled`, `creator_id`, `modifier_id`, `created_at`, `updated_at`, `pdf`) VALUES
(1297, 890, 'oz', 'ИСТЕЪМОЛЧИ МАНФААТИ ДОИМО УСТУН', '«Tошкент шаҳар ЭТК» AЖ тасарруфидаги 11 та туман электр таъминоти корхонаcи ишчи-ходимлари томонидан айни қиш мавсумидаги совуқ об-ҳаво шароитига қарамасдан аҳолига етказиб берилаётган электр энергияси таъминотида узилишларга йўл қўймаслик мақсадида тизимли ишлар олиб борилмоқда.', '<p style=\"text-align: center;\"><strong><big>ИСТЕЪМОЛЧИ МАНФААТИ ДОИМО УСТУН</big></strong></p>\r\n\r\n<p><big>&laquo;Tошкент шаҳар ЭТК&raquo; AЖ тасарруфидаги 11 та туман электр таъминоти корхонаcи ишчи-ходимлари томонидан айни қиш мавсумидаги совуқ об-ҳаво шароитига қарамасдан аҳолига етказиб берилаётган электр энергияси таъминотида узилишларга йўл қўймаслик мақсадида тизимли ишлар олиб борилмоқда.</big></p>\r\n\r\n<p><big><img alt=\"\" src=\"http://het.uz/uploads/de76ea47-efd1-60d1-45f6-2849293d972d_media_.jpg\" /></big></p>\r\n\r\n<p style=\"text-align: justify;\"><big>Шу билан бир қаторда айни совуқ иқлим шароитида пойтахт туман электр таъминоти корхоналарида электр энергияси таъминоти бўйича келиб тушаётган ҳар бир мурожаатни зудлик билан кўриб чиқиш ва юзага келган муаммоларни тезкорлик билан бартараф этиш чоралари кўрилмоқда. Айниқса, паст ва юқори кучланишли кабель тармоқларидаги юзага келган авария ҳолати, қолаверса, аҳолига бир меъёрда узлуксиз ва сифатли электр энергиясини етказиб бериш учун жойлардаги мавжуд электр энергиясини тақсимлаш пунктларида олиб борилаётган мукаммал ва жорий таъмирлаш ишлари каби муҳим вазифаларга алоҳида эътибор қаратилмоқда.&nbsp;</big></p>\r\n\r\n<p style=\"text-align: justify;\"><big><img alt=\"\" src=\"http://het.uz/uploads/0f154566-407f-8151-6816-7ea17b970149_media_.jpg\" /></big></p>\r\n\r\n<p style=\"text-align: justify;\"><big>Хусусан, белгиланган режа асосида жойлардаги мавжуд ҳар бир электр энергиясини &nbsp;тақсимлаш пункт (ТП)ларида истеъмолчиларга сифатли электр энергиясини етказиб бериш учун мукаммал таъмирлаш ишлари олиб борилмоқда. Мисол учун, белгиланган иш-режаси асосида Учтепа тумани &laquo;Тақачи&raquo; МФЙ ҳудудидаги аҳоли яшаш хонадонларини &nbsp;электр энергияси билан таъминлаб берувчи &laquo;Кўркам-1,2&raquo; фидеридан чиқувчи қуввати &nbsp;0,4 кВ бўлган паст кучланишли 373-сонли трансформатор пунктида мукаммал таъмирлаш ишлари олиб борилди. &nbsp;</big></p>\r\n\r\n<p style=\"text-align: justify;\"><big><img alt=\"\" src=\"http://het.uz/uploads/7376c27b-d534-4c3d-6d42-6ea40e37bd94_media_.jpg\" /></big></p>\r\n\r\n<p style=\"text-align: justify;\"><big>Бундан ташқари, тумандаги &laquo;Кўркамобод&raquo; МФЙ Фидер &laquo;Мотор-1&raquo; узатмасидан таъминланувчи РП Саид ва 4677-сонли трансформатор нимстанцияси оралиғидаги&nbsp;қуввати 10 кВ бўлган юқори кучланишли ер остидан ўтган кабель тармоқларидаги аниқланган носозликларни ўз вақтида бартараф этиш чоралари кўрилмоқда. &nbsp;</big></p>\r\n\r\n<p style=\"text-align: justify;\"><big><img alt=\"\" src=\"http://het.uz/uploads/2ce12afd-b0df-de37-b787-301ddf779118_media_.jpg\" /></big></p>\r\n\r\n<p style=\"text-align: justify;\"><big>Пойтахтимизнинг барча туман электр таъминоти корхоналари томонидан олиб борилаётган бундай амалий ишларнинг барчаси истеъмолчиларни сифатли ҳамда ишончли электр энергияси билан таъминлашга қаратилган.</big></p>\r\n\r\n<p style=\"text-align: right;\"><strong><big>&quot;Toshkent shahar ETK&raquo; AJ матбуот хизмати.</big></strong></p>\r\n', '4871a20f-c9b2-2c62-348f-f74fad197eca_lists_.jpg', 'acf0cbcc-ab64-fa8d-5bcd-62ea9e677c64_lists_.jpg', 3454, 1, 5, NULL, 1610685837, 1760923608, ''),
(1298, 891, 'oz', 'ЯШНОБОД ТУМАНИНИНГ АЙРИМ ҲУДУДЛАРИДА ЭЛЕКТР ЭНЕРГИЯСИ ТАЪМИНОТИДА УЗИЛИШЛАР КУЗАТИЛМОҚДА', '«Toshkent shahar ЕТК» AJ пойтахтимизнинг Яшнобод туманида юқори кучланишли кабель тармоқларида носозликлар юзага келганлиги сабабли таъмирлаш ишлари бошланганини маълум қилади.', '<p style=\"text-align: center;\"><strong><big>ЯШНОБОД ТУМАНИНИНГ АЙРИМ ҲУДУДЛАРИДА ЭЛЕКТР ЭНЕРГИЯСИ ТАЪМИНОТИДА УЗИЛИШЛАР КУЗАТИЛМОҚДА</big></strong></p>\r\n\r\n<p style=\"text-align: justify;\"><big>&laquo;Toshkent shahar ЕТК&raquo; AJ пойтахтимизнинг Яшнобод туманида юқори кучланишли кабель тармоқларида носозликлар юзага келганлиги сабабли таъмирлаш ишлари бошланганини маълум қилади.</big></p>\r\n\r\n<p style=\"text-align: justify;\"><big>Аниқланишича, туман ҳудудидаги фидер &laquo;Тин&raquo; ҳамда &laquo;Альфа&raquo; узатмаларидан таъминланувчи юқори кучланишли қуввати 6 кВ бўлган ер остидан ўтган кабель тармоқларидаги шикастланган қисмида таъмирлаш ишлари олиб борилиши сабабли электр энергия етказиб беришда режадан ташқари ўчишлар кузитилмоқда. </big></p>\r\n\r\n<p style=\"text-align: justify;\"><big>Хусусан, 27 январь куни &laquo;Бойсун&raquo;, &laquo;Заркент&raquo; ҳамда &laquo;Жўрабек&raquo; МФЙларнинг&nbsp; Алимкент-1, 2, 3, 4, 5, Сув бўйи, Тўрткўл, Авиасозлар 1-тор, Зангори,&nbsp; Ҳовос, Ғиждувон, Бойсун,&nbsp; М. Ашрафий, Хатирчи, Ош, Обишер, Олот кўчаларидаги аҳоли хонадонлари, Фарғона йўли, 95 а кўчасидаги кўп қаватли уйларда электр энергияси соат 10:00 дан 17:00 қадар вақтинчалик ўчирилди.</big></p>\r\n\r\n<p style=\"text-align: justify;\"><big>Айни вақтда, &laquo;Toshkent shahar ЕТК&raquo; AJнинг юқори кучланишли аварияларни тиклаш тезкор ишчи-бригада ходимлари томонидан носозликларни бартараф этиш бўйича таъмирлаш ишлари олиб борилмоқда.</big></p>\r\n\r\n<p style=\"text-align: justify;\"><big>Мазкур таъмирлаш ишлари туфайли электр энергияси таъминотидаги вақтинча узилишлар сабабли етказилаётган ноқулайликлар учун истеъмолчилардан узр сўраймиз.</big></p>\r\n\r\n<p style=\"text-align: right;\"><strong><big>&laquo;Toshkent shahar ЕТК&raquo; AJ матбуот хизмати.</big></strong></p>\r\n', '4d9ab0d8-fa12-649d-a5e1-c85350efecb2_lists_.jpg', 'af91a760-dc3c-0568-1401-b5abc52a9dae_lists_.jpg', 2269, 1, 5, NULL, 1611729749, 1760896304, ''),
(1299, 892, 'oz', 'КОРРУПЦИЯ – ТАРАҚҚИЁТ КУШАНДАСИ', 'Куни кеча “Сурхондарё ҳудудий электр тармоқлари корхонаси” АЖда тизимда яширин иқтисодиёт, коррупцияга қарши курашиш ва унинг олдини олиш мавзусида семинар бўлиб ўтди. ', '<p style=\"text-align: center;\"><strong><big>КОРРУПЦИЯ &ndash; ТАРАҚҚИЁТ КУШАНДАСИ</big></strong></p>\r\n\r\n<p style=\"text-align: justify;\"><big>Куни кеча &ldquo;Сурхондарё ҳудудий электр тармоқлари корхонаси&rdquo; АЖда тизимда яширин иқтисодиёт, коррупцияга қарши курашиш ва унинг олдини олиш мавзусида семинар бўлиб ўтди. Унда вилоят ИИБ катта терговчиси Шохжаҳон Дусмуродзода, вилоят прокуратураси катта ёрдамчиси Алишер Бобомуродов, &ldquo;Ҳудудий электр тармоқлари&rdquo; АЖ Коррупцияга қарши курашиш ва комплаенс назорат хизмати бошлиғи Хусниддин Алламуродов ҳамда &ldquo;Сурхондарё ҲЭТК&rdquo; АЖ раҳбарияти ва ишчи-ходимлари иштирок этдилар.</big></p>\r\n\r\n<p style=\"text-align: justify;\"><big>Тадбирда таъкидланганидек, ҳар қандай давлатнинг ривожланиши давлат хизматчиларининг ватанпарварлиги, зиммасидаги масъулиятни тўлақонли англаши, садоқати ва фидойилигига боғлиқдир. Ушбу хислатларга эга бўлмаган давлат хизматчиси коррупциядан холи бўла олмаслиги, натижада порахўрликка, мансабини суиистеъмол қилишга, пировардида ўзи ишлаб турган ташкилотнинг обрўсизланишига сабаб бўлади. Мамлакатнинг сиёсий, иқтисодий, ҳуқуқий тизимига путур етади. Коррупция муроса қилиб бўлмас глобал таҳдид ҳисобланиши, шу сабабли дунё миқёсида барча давлатларда бу иллатга қарши курашиб келинаётганлиги алоҳида эътироф этилди.</big></p>\r\n\r\n<p style=\"text-align: justify;\"><big><img alt=\"\" src=\"http://het.uz/uploads/d0761ea7-568f-fba9-a203-66ff46b3f44f_media_.jpg\" /></big></p>\r\n\r\n<p style=\"text-align: justify;\"><big>Айтиш мумкинки, &ldquo;Сурхондарё ҲЭТК&rdquo; АЖ ва унинг таркибидаги электр таъминоти корхоналарида ҳам коррупцияга қарши курашиш борасида ички назорат тизими фаолияти такомиллаштирилган. Яширин иқтисодиёт ва коррупцияга қарши курашиш ҳамда унинг олдини олиш юзасидан 2020-2021-йилларга мўлжалланган &ldquo;Йўл харитаси&rdquo; ишлаб чиқилиб, Жамият ва унинг таркибидаги туман, шаҳар электр таъминоти корхоналарининг маъмурий биноларида жисмоний ва юридик шахслар, уларнинг вакилларини қабул қилишда шаффофликни таъминлашга кенг эътибор қаратилмоқда. Бундан ташқари истеъмолчилар билан ўзаро ҳисоб-китоб қилиш, яъни &nbsp;электр энергияси сарфини ҳисобга олишнинг автоматлаштирилган тизими жорий этилаётгани қатор қулайликлар яратиш билан бир қаторда, коррупция ҳолатларини келтириб чиқариши мумкин бўлган айрим омилларнинг олдини олишга хизмат қилади.</big></p>\r\n\r\n<p style=\"text-align: justify;\"><big><img alt=\"\" src=\"http://het.uz/uploads/5cfe0bad-895f-339d-53fa-ff35fbf4e4b8_media_.jpg\" /></big></p>\r\n\r\n<p style=\"text-align: justify;\"><big>Шунингдек, тадбирда аҳоли ҳуқуқий саводхонлигини ошириш коррупцияга қарши курашда муҳим аҳамиятга эга эканлигига эътибор қаратилиб, кўп ҳолларда бу борада етарли маълумотга эга бўлмаслик нохуш ҳолатларга сабаб бўлаётганлиги таъкидланди. Сўзга чиққанлар ушбу йўналишда нодавлат нотижорат ташкилотлари фаоллигини ошириш юзасидан қатор таклиф ва тавсиялар билдириб ўтдилар.</big></p>\r\n\r\n<p style=\"text-align: right;\"><strong><big>&quot;Сурхондарё ҲЭТК&quot; АЖ матбуот хизмати.</big></strong></p>\r\n\r\n<p style=\"text-align: justify;\">&nbsp;</p>\r\n\r\n<p style=\"margin:0cm 0cm 8pt\">&nbsp;</p>\r\n', '7d902047-92ff-2d97-ebe1-29486fe49797_lists_.jpg', 'eedecc9a-d7a0-09e7-6ec4-6ff65360398c_lists_.jpg', 1733, 1, 5, NULL, 1611746320, 1760828434, ''),
(1300, 893, 'oz', 'ҚАШҚАДАРЁДА ҲЭТК ХОДИМЛАРИ ИШТИРОКИДА КОРРУПЦИЯГА ҚАРШИ КУРАШ МАВЗУСИДА ДАВРА СУҲБАТИ ЎТКАЗИЛДИ', '«Қашқадарё ҳудудий электр тармоқлари корхонаси» АЖда ташкил этилган давра суҳбатида коррупция иллатларининг хавф-хатарлари таҳлил қилиниб, аҳолининг бу борада ҳуқуқий онгини ошириш, ОАВ орқали ташвиқот ишларини кучайтириш, жамиятда бундай жиноятлар келиб чиқишининг олдини олиш бўйича назорат ўрнатилиши зарурлиги таъкидлаб ўтилди.', '<p style=\"text-align: center;\"><strong><big>ҚАШҚАДАРЁДА ҲЭТК ХОДИМЛАРИ ИШТИРОКИДА КОРРУПЦИЯГА ҚАРШИ КУРАШ МАВЗУСИДА ДАВРА СУҲБАТИ ЎТКАЗИЛДИ</big></strong></p>\r\n\r\n<p><big>&laquo;Қашқадарё ҳудудий электр тармоқлари корхонаси&raquo; АЖда ташкил этилган давра суҳбатида коррупция иллатининг хавф-хатарлари таҳлил қилиниб, аҳолининг бу борада ҳуқуқий онгини ошириш, ОАВ орқали ташвиқот ишларини кучайтириш, жамиятда бундай жиноятлар келиб чиқишининг олдини олиш бўйича назорат ўрнатилиши зарурлиги таъкидлаб ўтилди.</big></p>\r\n\r\n<p><big><img alt=\"\" src=\"http://het.uz/uploads/f7afa32a-3ac8-960f-55f8-19761624fe6f_media_.jpg\" /></big></p>\r\n\r\n<p><big><img alt=\"\" src=\"http://het.uz/uploads/d9057f2f-9e2d-a10f-9dcc-5b1b1c638c76_media_.jpg\" /></big></p>\r\n\r\n<p><big>Ўзбекистон Республикасининг &laquo;Коррупцияга қарши курашиш тўғрисида&raquo;ги Қонуни, Ўзбекистон Республикаси Президентининг &laquo;Ўзбекистон Республикасида коррупцияга қарши курашиш тизимини янада такомиллаштириш чора-тадбирлари тўғрисида&raquo;ги фармони ҳамда &laquo;Коррупцияга қарши курашиш тўғрисида&raquo;ги Ўзбекистон Республикаси қонунининг қоидаларини амалга ошириш чора-тадбирлари тўғрисида&raquo;ги ПҚ&ndash;2752-сонли қарори ижроси юзасидан жойларда амалга оширилаётган ишлар бўйича маълумотлар бериб ўтилди.</big></p>\r\n\r\n<p><img alt=\"\" src=\"http://het.uz/uploads/0bcd5752-031d-a64c-495f-8d22167402a4_media_.jpg\" /></p>\r\n\r\n<p><big>Тадбирда &laquo;Қашқадарё&nbsp;ҲЭТК&raquo; АЖ раҳбари сўзга чиқиб, давлат ва жамият ташкилотларида коррупция каби иллатнинг олдини олиш ва унга қарши курашда биргаликда ҳаракат қилинсагина самарали натижаларга эришиш мумкинлигини таъкидлаб ўтди.</big></p>\r\n\r\n<p><big><img alt=\"\" src=\"http://het.uz/uploads/7a5d407a-e1cf-7c15-0737-40ca0e6583a8_media_.jpg\" /></big></p>\r\n\r\n<p><big>Тадбир давомида маърузачилар томонидан жамият ходимларини қизиқтирган саволларга жавоб қайтарилди.</big></p>\r\n\r\n<p style=\"text-align: right;\"><strong><big>&laquo;Қашқадарё&nbsp;ҲЭТК&raquo; АЖ матбуот хизмати.</big></strong></p>\r\n', 'b22cb30e-7fe3-438f-70c7-aee6713530a9_lists_.jpg', '6d5d5a2e-3a6e-b420-a13d-f087351f8fe2_lists_.jpg', 1692, 1, 5, NULL, 1611926614, 1760845298, ''),
(1301, 894, 'oz', '\"ҲУДУДИЙ ЭЛЕКТР ТАРМОҚЛАРИ” АЖДА ТАРҒИБОТ ТАДБИРИ ЎТКАЗИЛДИ', 'Бугун, 1 февралда “Ҳудудий электр тармоқлари” АЖда Ўзбекистон Республикаси Президенти Шавкат Мирзиёевнинг 2020 йил  29  декабрдаги Олий Мажлисга Мурожаатномаси мазмун- моҳиятини ўрганиш бўйича тарғибот тадбири ўтказилди. ', '<p style=\"text-align: center;\"><strong><big>&ldquo;ҲУДУДИЙ ЭЛЕКТР ТАРМОҚЛАРИ&rdquo; АЖДА ТАРҒИБОТ ТАДБИРИ ЎТКАЗИЛДИ</big></strong></p>\r\n\r\n<p><big>Бугун, 1 февралда &ldquo;Ҳудудий электр тармоқлари&rdquo; АЖда Ўзбекистон Республикаси Президенти Шавкат Мирзиёевнинг 2020 йил&nbsp; 29&nbsp; декабрдаги Олий Мажлисга Мурожаатномаси мазмун- моҳиятини ўрганиш бўйича тарғибот тадбири ўтказилди. Унда Жамият ижро аппарати, таркибий корхоналар раҳбарлари ва мутахассислари, ҳудуддаги корхоналар меҳнат жамоалари вакиллари (онлайн) ҳамда оммавий ахборот воситалари ходимлари қатнашди.</big></p>\r\n\r\n<p><big><img alt=\"\" src=\"http://het.uz/uploads/4115514d-c40d-7b42-d2fb-dfe0b77615cf_media_.jpg\" /><br />\r\nТадбирни &ldquo;Ҳудудий электр тармоқлари&rdquo; АЖ бошқарув раисининг биринчи ўринбосари Рўзиқул Райимов кириш сўзи билан очар экан, давлатимиз раҳбари мамлакат Парламентига йўллаган Мурожаатнома Ўзбекистоннинг жорий йил ва яқин истиқболдаги тараққиётини белгилаб берувчи стратегик ҳужжат бўлиб, унда биронта соҳа четлаб ўтилмагани, хусусан электр энергетикаси тизими иқтисодиётимиз ривожида муҳим аҳамият касб этиши, соҳада амалга оширилиши кутилаётган кенг кўламли ислоҳотларга алоҳида тўхталиб ўтди. &nbsp;</big></p>\r\n\r\n<p><big><img alt=\"\" src=\"http://het.uz/uploads/76eb4a64-03a1-b47a-a318-d418b4c1c87f_media_.jpg\" /><br />\r\nТошкент давлат юридик университети Меҳнат ҳуқуқи кафедраси ўқитувчиси Муҳаммадамин Каримжонов йиғилишда маъруза билан қатнашиб, Мурожаатномада давлат ва жамият қурилиши тизимини такомиллаштириш, қонун устуворлигини таъминлаш ва суд-ҳуқуқ тизимини янада ислоҳ қилиш, иқтисодиётни ривожлантириш ва либераллаштириш, ижтимоий соҳани ривожлантиришга доир илгари сурилган ғоялар, шунингдек, хавфсизлик, миллатлараро тотувлик ва диний бағрикенгликни таъминлаш, ташқи сиёсатдаги устувор йўналишлар, ёшлар масаласи каби муҳим ва долзарб масалалар акс этганига йиғилганлар эътиборини қаратди.</big></p>\r\n\r\n<p><big><img alt=\"\" src=\"http://het.uz/uploads/0c10ac7d-1c64-06d2-746e-a7a9cbb57d9b_media_.jpg\" /><br />\r\nТадбирда таъкидлаганидек, Президентимизнинг Мурожаатномасида белгилаб берилган вазифалар, истиқболли лойиҳалар халқимизни ҳар томонлама қўллаб-қувватлаш, қолаверса ҳар бир соҳани ривожантириш, айниқса келажагимиз бўлган ёшлар ва уларнинг таълим-тарбия олишлари йўлидаги муҳим йўналишлар, аҳоли саломатлигини мустаҳамлашга қаратилганлиги билан жуда аҳамиятлидир.</big></p>\r\n\r\n<p><big><img alt=\"\" src=\"http://het.uz/uploads/19a1469a-ccfc-2ed3-fc24-a58e2f4022d7_media_.jpg\" /></big><br />\r\n<big>Жонли ва очиқ мулоқот тарзида бўлиб ўтган ушбу тадбир иштирокчиларда катта қизиқиш уйғотди. &nbsp;Хусусан, Жамият ходимларининг ҳуқуқий саводхонлиги ва меҳнат қонунчилигига оид билимлари асосида ўтказилган савол-жавобларда муваффақиятли қатнашган иштирокчилар эсдалик совғалар билан тақдирландилар. &nbsp;</big></p>\r\n\r\n<p><big><img alt=\"\" src=\"http://het.uz/uploads/7cff7588-febf-005d-cb77-e59f8186c4e0_media_.jpg\" /></big></p>\r\n\r\n<p><big>Таъкидлаш лозимки, Мурожаатноманинг мазмун-моҳиятини чуқур ўрганиш, унда белгилаб берилган устувор вазифалар ижросини таъминлаш ҳар биримизнинг бурчимиздир. Зеро, мамлакатимизни равнақ топтиришда ўз ғоя ва ташаббусларимиз билан турли соҳалардаги ислоҳотларда фаол иштирок этишимиз керак. Бу борада барча зарур шароит ва имкониятлар яратиб берилмоқда.</big></p>\r\n\r\n<p><big><img alt=\"\" src=\"http://het.uz/uploads/4fd70409-f167-683d-4321-3a5db8e7a32c_media_.jpg\" /></big></p>\r\n\r\n<p style=\"text-align: right;\"><strong><big>&ldquo;Ҳудудий электр тармоқлари&rdquo; АЖ Матбуот хизмати.</big></strong></p>\r\n', 'db2628c8-6dd7-32f1-465b-a96a06adbcc9_lists_.jpg', '62791a15-fd61-2222-c1d2-c570d48c5e8a_lists_.jpg', 1802, 1, 5, NULL, 1612167703, 1760962544, ''),
(1302, 895, 'oz', 'ИНТИЗОМ ВА ТАРТИБ - УНУМЛИ МЕҲНАТГА ЕТАКЛАЙДИ', '“Хоразм ҲЭТК” АЖда туман ва шаҳар электр таъминоти корхоналарида меҳнатни муҳофаза қилиш, хавфсизлик техникаси ҳамда ходимлар билан ишлаш ҳолати бўйича ўқув-семинар ташкил этилди. ', '<p style=\"text-align: center;\"><span style=\"font-size:11pt\"><span style=\"line-height:107%\"><span style=\"font-family:Calibri,sans-serif\"><strong><span style=\"font-size:13.5pt\"><span style=\"line-height:107%\"><span style=\"font-family:&quot;Calibri&quot;,sans-serif\">ИНТИЗОМ ВА ТАРТИБ - УНУМЛИ МЕҲНАТГА ЕТАКЛАЙДИ</span></span></span></strong></span></span></span></p>\r\n\r\n<p style=\"text-align: justify;\"><br />\r\n<big>&ldquo;Хоразм ҲЭТК&rdquo; АЖда туман ва шаҳар электр таъминоти корхоналарида меҳнатни муҳофаза қилиш, хавфсизлик техникаси ҳамда ходимлар билан ишлаш ҳолати бўйича ўқув-семинар ташкил этилди.&nbsp;</big></p>\r\n\r\n<p style=\"text-align: justify;\"><img alt=\"\" src=\"http://het.uz/uploads/e776663f-b36a-9bbe-41dc-705f58fd2e51_media_.jpg\" /><br />\r\n<big>&quot;Ҳудудий электр тармоқлари&quot; АЖнинг мустаҳкамлик ва хавфсизлик техникаси хизмати бошлиғи, Хоразм вилояти касаба уюшмалари ташкилотлари кенгаши ходимлари, &quot;Ўзэнергоинспекция&quot;нинг Хоразм ҳудудий бўлими мутахассислари ҳамда &nbsp;&quot;Хоразм ҲЭТК&quot; АЖ нинг барча туман ва шаҳар электр таъминоти корхоналари бош муҳандислари ва корхоналарда фаолият олиб бораётган хавфсизлик техникаси муҳандислари иштирок этган тадбирда &nbsp;иш фаолияти давомида юзага келаётган хавфсизлик техникаси борасидаги камчиликлар, таклифларни мутасаддиларга тўғридан-тўғри етказиш имкониятига эга бўлдилар. &nbsp;<br />\r\nШунингдек, тадбир давомида &nbsp;иш юзасидан мавжуд камчиликларни бартараф қилиш, лавозим йўриқномаси доирасида ҳар ким ўзига юклатилган вазифа ва топшириқларни бажариш чораларини кўриш ҳамда меҳнат интизоми ҳақида ходимларга &nbsp;тушунтириш ишлари олиб борилди.<br />\r\nЎқув-семинари давомида ходимлар ўзларини қизиқтираётган саволларига жавоб олдилар ва ўз таклифларини билдирдилар.</big></p>\r\n\r\n<p><img alt=\"\" src=\"http://het.uz/uploads/fa2abc69-ed0b-18c6-66f6-b361c96fb513_media_.jpg\" /></p>\r\n\r\n<p style=\"text-align: right;\"><strong>&nbsp; &nbsp; &nbsp; &nbsp; <big>&nbsp; &nbsp; &nbsp;&quot;Хоразм ҳудудий электр тармоқлари&quot; АЖ Матбуот хизмати</big></strong></p>\r\n', 'c5390457-250f-ee43-f929-d65d4e0968e4_lists_.jpg', '615d1ebd-fe3a-0178-7d42-aab3a9416419_lists_.jpg', 1524, 1, 4, NULL, 1612418764, 1760794005, ''),
(1303, 896, 'oz', '“САМАРҚАНД ҲЭТК” АЖДА “БИЗ КОРРУПЦИЯГА ҚАРШИМИЗ” МАВЗУСИДА ТАРҒИБОТ ТАДБИРИ ЎТКАЗИЛДИ', '“Самарқанд ҲЭТК” АЖда коррупцияни олдини олиш, қонунбузилиш ҳолатлари, уларнинг сабабларини бартараф этиш мақсадида “Биз коррупцияга қаршимиз” мавзусида корхона тасарруфидаги туман электр таъминоти корхоналарининг барча мутасаддилари ҳамда ишчи-ходимлари иштирокида ҳуқуқий тарғибот тадбири ўтказилди.', '<p style=\"text-align: center;\"><big><strong>&ldquo;САМАРҚАНД ҲЭТК&rdquo; АЖДА &ldquo;БИЗ КОРРУПЦИЯГА ҚАРШИМИЗ&rdquo; МАВЗУСИДА ТАРҒИБОТ ТАДБИРИ ЎТКАЗИЛДИ</strong></big></p>\r\n\r\n<p style=\"text-align: justify;\"><big>&ldquo;Самарқанд ҲЭТК&rdquo; АЖда коррупция ва қонунбузилиш ҳолатларига йўл қўймаслик, унга етакловчи сабабларни &nbsp;олдини олиш ва бартараф этишга бағишланган &ldquo;Биз коррупцияга қаршимиз&rdquo; мавзусида корхона тасарруфидаги туман электр таъминоти корхоналари&nbsp;мутасаддилари ҳамда ишчи-ходимлари иштирокида ҳуқуқий тарғибот тадбири бўлиб ўтди.</big></p>\r\n\r\n<p style=\"text-align: justify;\"><big>Самарқанд вилояти адлия бошқармаси бўлим бошлиғи О. Мухаммадиев тадбирда маъруза билан қатнашиб, ходимларга хизмат вазифаларини бажариш вақтида ҳамиша огоҳ бўлишликка, қолаверса коррупцияга йўл қўймаслик асосий мақсадлардан бири эканини алоҳида таъкидлаб ўтди. Жумладан, ҳозирги кунда вилоят &nbsp;туманлари барча аҳоли хонадонларига &laquo;ақлли&raquo; замонавий электр ҳисоблагичлари ўрнатиш давомида ишларни тўғри ташкиллаштириш, хонадонларда техник назоратни тўғри ўтказиш ва белгиланган тариф бўйича тўловларини қабул қилиш, ҳужжатларни мувофиқлаштириш жараёнида хатоларга йўл қўймаслик ва нотўғри маълумотларни киритмаслик, мободо шундай вазият содир бўлса, ўша ходимга нисбатан қаттиқ чоралар қўлланилиши ҳақида ҳам тўхталиб ўтди.</big></p>\r\n\r\n<p style=\"text-align: justify;\"><big><img alt=\"\" src=\"http://het.uz/uploads/cec7d293-076f-9c2b-714c-a28c7c9f6b01_media_.jpg\" /></big></p>\r\n\r\n<p style=\"text-align: justify;\"><big>Тадбир давомида Юридик бўлими бошлиғи Х. Бўриев томонидан иштирокчиларга коррупцияни ўз вақтида олдини олиш, яъни ноқонуний электр тармоғига улаш, ўз хизмат вазифасига совуққонлик билан ёндашиб, лавозим йўриқномасига зид равишда ишлаш, ишончдан фойдаланиб, таъмагирлик ёки фирибгарлик&nbsp;ҳолатлари содир қилинганда, Ўзбекистон Республикаси Жиноят кодексининг тегишли моддалари билан жиноий жавобгарликка тортилиши тўғрисида огоҳлантириб ўтилди.</big></p>\r\n\r\n<p style=\"text-align: justify;\"><big>Маълумки, айни пайтда жамият томонидан истеъмолчилар билан ўзаро ҳисоб-китоб қилишда автоматлаштирилган тизим&nbsp;жорий этилмоқдаки, бу ўз навбатида, истеъмолчиларга электр энергияси сарфини ҳисобга олишда қатор қулайликлар яратиш билан бир қаторда, коррупцияни келтириб чиқариш мумкин бўлган айрим омилларнинг олди олинишига хизмат қилади.</big></p>\r\n\r\n<p style=\"text-align: justify;\"><big><img alt=\"\" src=\"http://het.uz/uploads/df1e7e69-c2a9-888a-f98a-e4adb291f5c7_media_.jpg\" /></big></p>\r\n\r\n<p style=\"text-align: justify;\"><big>Тадбирда&nbsp;аҳоли ҳуқуқий саводхонлигини ошириш коррупцияга қарши курашда муҳим аҳамиятга эга эканлигига йиғилганлар эътибори қаратилиб, кўп ҳолларда бу борадаги&nbsp;билимнинг етишмаслиги коррупциянинг келиб чиқишига сабаб бўлаётгани таъкидланди.&nbsp;</big></p>\r\n\r\n<p style=\"text-align: justify;\"><big>Шулардан келиб чиқилиб, ушбу йўналишда нодавлат нотижорат ташкилотлари фаоллигини ошириш юзасидан қатор таклиф ва тавсиялар билдирилди.</big></p>\r\n\r\n<p style=\"text-align: right;\"><strong><big>&quot;Самарқанд ҲЭТК&quot; АЖ матбуот хизмати.</big></strong></p>\r\n', '8ccd2f34-0b1a-3a8b-ca78-d37b89500684_lists_.jpg', 'f1d2584e-1e50-240e-55a9-27e9efffee9f_lists_.jpg', 1507, 1, 5, NULL, 1612532300, 1760845290, ''),
(1304, 897, 'oz', '“ҲУДУДИЙ ЭЛЕКТР ТАРМОҚЛАРИ” АЖ: ТРАНСФОРМАЦИЯ ЖАРАЁНЛАРИ УЧУН ХАЛҚАРО КОНСАЛТИНГ КОМПАНИЯСИ ВАКИЛЛАРИ ЖАЛБ ЭТИЛДИ', '2021 йил 8 февраль куни “Ҳудудий электр тармоқлари” АЖ бошқаруви раиси Улуғбек Мустафоев ҳамда “McKinsey&Company” халқаро консалтинг компанияси вакиллари ўртасида музокара ўтказилди.', '<p style=\"text-align: center;\"><strong><big>&ldquo;ҲУДУДИЙ ЭЛЕКТР ТАРМОҚЛАРИ&rdquo; АЖ: ТРАНСФОРМАЦИЯ ЖАРАЁНЛАРИ УЧУН ХАЛҚАРО КОНСАЛТИНГ КОМПАНИЯСИ ВАКИЛЛАРИ ЖАЛБ ЭТИЛДИ</big></strong></p>\r\n\r\n<p style=\"text-align: justify;\"><big>2021 йил 8 февраль куни &ldquo;Ҳудудий электр тармоқлари&rdquo; АЖ бошқаруви раиси Улуғбек Мустафоев ҳамда &ldquo;McKinsey&amp;Company&rdquo; халқаро консалтинг компанияси вакиллари ўртасида музокара ўтказилди.</big></p>\r\n\r\n<p style=\"text-align: justify;\"><big><img alt=\"\" src=\"http://het.uz/uploads/62ad6bd1-0405-065f-a9ce-3fe66a5f0736_media_.jpg\" /></big></p>\r\n\r\n<p style=\"text-align: justify;\"><big>Маълумки, Ўзбекистон Республикаси Президенти Шавкат Мирзиёевнинг Олий Мажлисга Мурожаатномасида иқтисодиётда таркибий ўзгаришларни амалга оширишда давлат компанияларини трансформация қилишни жадаллаштириш зарурлиги, айниқса электр энергетикаси, нефть-газ ва кимё саноати, машинасозликдаги йирик корхоналарни ислоҳ қилишга халқаро тан олинган компаниялар жалб этилиши муҳимлиги алоҳида таъкидлаб ўтилган эди.</big></p>\r\n\r\n<p style=\"text-align: justify;\"><big><img alt=\"\" src=\"http://het.uz/uploads/efd86273-c7e3-a6f1-3855-5c371f7b9a50_media_.jpg\" /></big></p>\r\n\r\n<p style=\"text-align: justify;\"><big>&ldquo;Ҳудудий электр тармоқлари&rdquo; АЖ томонидан Мурожаатномада белгиланган вазифалар, хусусан, электр энергетикаси тизимини янада ислоҳ қилиш орқали аҳоли, ижтимоий соҳа объектлари ва иқтисодиёт тармоқларини барқарор электр энергияси билан таъминлаш, шунингдек, Жамият ва унинг таркибидаги корхоналарда бошқарув ва ишлаб чиқариш жараёнларини автоматлаштириш (ERP) тизимини жорий этиш, электр энергиясини тақсимлаш ва сотиш жараёнларини тўлиқ автоматлаштириш ҳамда SMART GRID &ndash; ақлли тармоқ тизимини яратиш, молиявий ҳисоботларни ҳалқаро стандартлар асосида шакллантириш ҳамда босқичма-босқич амалиётга жорий этиш мақсадида &ldquo;McKinsey&amp;Company&rdquo; халқаро консалтинг компанияси вакиллари иштирокида таҳлил ишлари бошлаб юборилди.</big></p>\r\n\r\n<p style=\"text-align: justify;\"><big><img alt=\"\" src=\"http://het.uz/uploads/3928b457-5728-df34-3bab-f23b05915e0f_media_.jpg\" /></big><br />\r\n<big>Музакоралар давомида У. Мустафоев Жамият томонидан олиб борилаётган кенг кўламли ислоҳотларни янада юқори поғонага кўтариш учун тизимни чуқур таҳлилдан ўтказиш ва тизимли камчиликларни аниқлаш орқали харажатларни қисқартириш бўйича ўз таклифларини билдириб ўтди.</big></p>\r\n\r\n<p style=\"text-align: justify;\"><big><img alt=\"\" src=\"http://het.uz/uploads/55e34fe0-5a59-1e0f-9ca7-51e976c5bac4_media_.jpg\" /></big></p>\r\n\r\n<p style=\"text-align: justify;\"><big>Ўз навбатида, халқаро компания вакиллари &ldquo;Ҳудудий электр тармоқлари&rdquo; АЖ раҳбариятига &nbsp;ҳамкорлик ҳамда таҳлилий жараёнларда яратиб берилган шарт-шароитлар учун самимий миннадорлик билдириб, &nbsp;&ldquo;McKinsey&amp;Company&rdquo; томонидан таклиф, тавсия ва якуний ҳисоботлар асосида тегишли хулосалар ишлаб чиқилишига келишиб олдилар. </big></p>\r\n\r\n<p style=\"text-align: right;\"><strong><big>&ldquo;Ҳудудий электр тармоқлари&rdquo; АЖ Матбуот хизмати.</big></strong></p>\r\n', '15e03250-af2d-5a1d-82b7-0ffeb0248bde_lists_.jpg', '29cd618f-308f-8014-1b4c-363c8043de17_lists_.jpg', 1650, 1, 5, NULL, 1612794473, 1760845294, ''),
(1305, 898, 'oz', '\"ХОРАЗМ ҲЭТК\" АЖДА \"КОРРУПЦИЯ – КЕЛАЖАК ЗАВОЛИ\" МАВЗУИДА СЕМИНАР БЎЛИБ ЎТДИ', 'Коррупция ва порахўрлик – ҳокимият ва бошқарув асосларини емирадиган, унинг аҳоли олдидаги обрўсига путур етказадиган, фуқароларнинг қонуний ҳуқуқ ва манфаатларига дахл қиладиган хавфли жиноий ҳодисалардан биридир.', '<p style=\"text-align: center;\"><strong><big>&quot;ХОРАЗМ ҲЭТК&quot; АЖДА &quot;КОРРУПЦИЯ &ndash; КЕЛАЖАК ЗАВОЛИ&quot; МАВЗУИДА СЕМИНАР БЎЛИБ ЎТДИ</big></strong></p>\r\n\r\n<p style=\"text-align: justify;\"><big>Коррупция ва порахўрлик &ndash; ҳокимият ва бошқарув асосларини емирадиган, унинг аҳоли олдидаги обрўсига путур етказадиган, фуқароларнинг қонуний ҳуқуқ ва манфаатларига дахл қиладиган хавфли жиноий ҳодисалардан биридир.</big></p>\r\n\r\n<p style=\"text-align: justify;\"><big>Бугунги кунда мамлакатимизда бу иллатга қарши қатъий кураш чоралари олиб борилмоқда.&nbsp; Хусусан, барча идора ва ташкилотларда коррупцияга қарши курашишда фаол бўлишга ундовчи тадбирлар, тушунтириш ишлари олиб борилиши, пировардида фуқароларни ҳуқуқий билимларини янада оширишга хизмат қилади. </big></p>\r\n\r\n<p style=\"text-align: justify;\"><big><img alt=\"\" src=\"http://het.uz/uploads/f6474d64-bc07-6aed-090d-e08f792ddfaf_media_.jpg\" /></big></p>\r\n\r\n<p style=\"text-align: justify;\"><big>Шундай тадбирлардан бири &quot;Хоразм ҲЭТК&quot; АЖда ҳам бўлиб ўтди. &quot;Коррупция &ndash; келажак заволи&quot; мавзуида ташкил этилган семинар вилоят прокуратураси билан ҳамкорликда ўтказилди.</big></p>\r\n\r\n<p style=\"text-align: justify;\"><big><img alt=\"\" src=\"http://het.uz/uploads/963a57b9-53b2-9b72-a5a1-e903caa54ebb_media_.jpg\" /></big></p>\r\n\r\n<p style=\"text-align: justify;\"><big>Жамият таркибий корхоналари юридик бўлим бошлиқлари, мажбурий ижро билан ишлаш муҳандис юристконсультлари, давлат хизматлари бўлимида фаолият олиб борувчи ходимлар ҳамда барча бўлим бошлиқлари иштирокидаги ушбу семинарда соҳада йўл қўйилаётган мавжуд камчилик ва хатолар таҳлил қилиниб, коррупция ҳолатларини олдини олиш учун биргаликда курашиш лозимлиги тушунтирилди.&nbsp; </big></p>\r\n\r\n<p style=\"text-align: justify;\"><big><img alt=\"\" src=\"http://het.uz/uploads/4ae9b6cc-7f44-d7a9-d1d5-1be97bd3d1ee_media_.jpg\" /></big></p>\r\n\r\n<p style=\"text-align: justify;\"><big>Хоразм вилоят прокуратураси уюшган жиноятчилик ва коррупцияга қарши курашиш бўлими терговчиси Р. Исматов йиғилганларга Президентимиз томонидан қабул қилинган ҳуқуқий ҳужжатлар ва уларнинг ижроси юзасидан тушунтириш бериб ўтди.</big></p>\r\n\r\n<p style=\"text-align: justify;\"><big>Шундан сўнг жамият коррупцияга қарши курашиш бўлими бошлиғи сифатида фаолият бошлаган А. Каримов сўзга чиқиб, семинар қатнашчиларига фаолиятлари давомида юзага келиши мумкин бўлган муаммолар борасида ҳуқуқий кўникмалар берилиши ҳақида тўхталди.</big></p>\r\n\r\n<p style=\"text-align: justify;\"><big><img alt=\"\" src=\"http://het.uz/uploads/b491a63e-cb94-00bb-77fc-dfb6a46655be_media_.jpg\" /></big></p>\r\n\r\n<p style=\"text-align: justify;\"><big>Семинар якунида сўзга чиққан &quot;Хоразм ҲЭТК&quot; АЖ бош директори С. Берегин жамиятда коррупция иллатлари юзага келмаслиги учун барчани биргаликда ва ҳамжиҳатликда фаолият олиб боришга чорлади.</big></p>\r\n\r\n<p style=\"text-align: right;\"><strong><big>&quot;Хоразм ҲЭТК&quot; АЖ матбуот хизмати.</big></strong></p>\r\n', '6dc6a692-10f7-2cee-1010-f1e8fe12364e_lists_.jpg', 'c389cf6c-03d6-5156-009a-1a6aec1cb604_lists_.jpg', 1601, 1, 5, NULL, 1612851279, 1760845295, ''),
(1307, 899, 'ru', 'ЭКОЛОГИЧЕСКИЙ ОТЧЁТ АБР \"ПРОЕКТ МОДЕРНИЗАЦИИ РАСПРЕДЕЛИТЕЛЬНОЙ СЕТИ ТА-9708 УЗБ\"', 'Подготовка устойчивых инвестиционных проектов в энергетике', '<div style=\"background:#eeeeee;border:1px solid #cccccc;padding:5px 10px;\"><big><strong><a href=\"http://het.uz/uploads/4ad71d0b-6c3f-d87c-ee9d-2d75daab75fa_media_.pdf\">ЭКОЛОГИЧЕСКИЙ ОТЧЁТ АБР</a>&nbsp;</strong></big></div>\r\n\r\n<h2 style=\"font-style:italic;\">&nbsp;</h2>\r\n\r\n<div style=\"background:#eeeeee;border:1px solid #cccccc;padding:5px 10px;\"><strong><big>&nbsp;&nbsp;<a href=\"http://het.uz/uploads/65c11e33-aee8-6f08-4870-cbfdffe7dadf_media_.pdf\">ЭКОЛОГИЧЕСКИЙ ОТЧЕТ АБР на английском языке</a></big></strong></div>\r\n', 'b6d93a17-5d2b-83db-e854-c4d10944ba87_lists_1307.jpg', '980f0f3b-c66c-e8de-085f-443518724bab_lists_1307.jpg', 686, 0, 5, 4, 1612861858, 1677152028, ''),
(1308, 900, 'ru', '№6 от 09.02.2021', '№6 от 09.02.2021', '<p><a href=\"http://het.uz/uploads/0677ee75-a75a-edaf-7bd8-daa500b95ac0_media_.pdf\">№6 от 09.02.2021</a></p>\r\n', NULL, NULL, 1414, 1, 5, NULL, 1612940809, 1760934349, '0677ee75-a75a-edaf-7bd8-daa500b95ac0_media_.pdf'),
(1309, 901, 'oz', 'ДАВЛАТ ВА ШАРТНОМАВИЙ ХИЗМАТЛАР КЎРСАТИШ ЯНАДА ТАКОМИЛЛАШТИРИЛАДИ ', '“Андижон ҲЭТК”АЖда 2021 йилда давлат ва шартномавий хизматлар кўрсатиш фаолиятини янада такомиллаштириш бўйича амалга ошириладиган ишлар юзасидан йиғилиш бўлиб ўтди. ', '<p style=\"text-align: center;\"><strong><big>ДАВЛАТ ВА ШАРТНОМАВИЙ ХИЗМАТЛАР КЎРСАТИШ ЯНАДА ТАКОМИЛЛАШТИРИЛАДИ </big></strong></p>\r\n\r\n<p style=\"text-align: justify;\"><big>&ldquo;Андижон ҲЭТК&rdquo;АЖда 2021 йилда давлат ва шартномавий хизматлар кўрсатиш фаолиятини янада такомиллаштириш бўйича амалга ошириладиган ишлар юзасидан йиғилиш бўлиб ўтди. Тадбирда &ldquo;Ҳудудий электр тармоқлари&rdquo; акциядорлик жамиятининг тегишли бошқарма бошлиғи Н. Мейлиев, етакчи мутахассис С. Юлдашев ҳамда &ldquo;Андижон ҲЭТК&rdquo;АЖ, шаҳар ва туман электр таъминоти корхоналари раҳбарлари, мутасадди ходимлари иштирок этишди. </big></p>\r\n\r\n<p style=\"text-align: justify;\"><big><img alt=\"\" src=\"http://het.uz/uploads/c32e1d7f-7eb7-b291-a0f0-86d6d351eb5f_media_.jpg\" /></big></p>\r\n\r\n<p style=\"text-align: justify;\"><big>Йиғилишда давлат ва шартномавий хизматлар кўрсатишда электр тармоғига уланиш бўйича келиб тушадиган мурожаатларни тўлиқ қамраб олиш, истеъмолчилар тасарруфида бўлган электр қурилмаларга техник хизматлар кўрсатиш, уларни кўрикдан ўтказиш, лаборатория синов ишларини ташкил этиш орқали дебитор қарздорликни камайтириш мумкинлиги слайдларда бир қанча мисоллар орқали тушунтириб ўтилди. </big></p>\r\n\r\n<p style=\"text-align: justify;\"><big><img alt=\"\" src=\"http://het.uz/uploads/67444093-98c6-c81f-d851-3b003dbea9e7_media_.jpg\" /></big></p>\r\n\r\n<p style=\"text-align: justify;\"><big>Таъкидланганидек, жойларда электр таъминоти соҳасида давлат ва шартномавий хизматлар кўрсатиш янада такомиллаштирилса, келиб тушган маблағлар корхона моддий-техник базасини мустаҳкамлаш, ишчи-ходимлар меҳнат шароитларини яхшилаш, уларни моддий рағбатлантиришга йўналтирилиши мумкин. </big></p>\r\n\r\n<p style=\"text-align: right;\"><strong><big>&laquo;Андижон ҲЭТК&raquo; АЖ матбуот хизмати.</big></strong></p>\r\n', '1e2bb35b-462f-4a1a-f865-030e2dd74729_lists_.jpg', 'a8168b54-36ee-895d-ffce-22796e8fc265_lists_.jpg', 1721, 1, 5, NULL, 1612951648, 1760751888, ''),
(1310, 902, 'oz', 'НИМСТАНЦИЯЛАР – ЭЛЕКТР ЭНЕРГИЯСИНИ ЕТКАЗИБ БЕРИШДА АСОСИЙ БЎҒИН ҲИСОБЛАНАДИ', 'Бугунги кунда “Фарғона ҳудудий электр тармоқлари корхонаси” АЖ вилоятдаги мавжуд 155 дона нимстанцияларга хизмат кўрсатиб келмоқда. ', '<p style=\"text-align: center;\"><strong><big>НИМСТАНЦИЯЛАР &ndash; ЭЛЕКТР ЭНЕРГИЯСИНИ ЕТКАЗИБ БЕРИШДА АСОСИЙ БЎҒИН ҲИСОБЛАНАДИ</big></strong></p>\r\n\r\n<p style=\"text-align: justify;\"><big>Бугунги кунда &ldquo;Фарғона ҳудудий электр тармоқлари корхонаси&rdquo; АЖ вилоятдаги мавжуд 155 дона нимстанцияларга хизмат кўрсатиб келмоқда. </big></p>\r\n\r\n<p style=\"text-align: justify;\"><big>Маълумки, истеъмолчиларни сифатли электр энергияси билан таъминлашда юқори кучланишли ҳаво узатмалари, трансформатор пунктлари, электр узатиш ҳаво ва кабель тармоқлари билан бир қаторда нимстанциялар хизмати жуда катта аҳамиятга эгадир.</big></p>\r\n\r\n<p style=\"text-align: justify;\"><big><img alt=\"\" src=\"http://het.uz/uploads/12eb97bd-0c6e-ad3b-b591-26284031dd47_media_.jpg\" /></big></p>\r\n\r\n<p style=\"text-align: justify;\"><big>Нимстацияларда жойлашган куч трансформаторлари ҳамда мавжуд электр қурилмаларининг соз ҳолатда узлуксиз, узоқ йиллар хизмат қилиши учун уларнинг техник ҳолатини босқичма-босқич яхшилашга қаратилган чора-тадбирлар ишлаб чиқилган.</big></p>\r\n\r\n<p style=\"text-align: justify;\"><big>Хусусан, йил бошидан вилоятдаги барча нимстанцияларда жорий ва мукаммал таъмирлаш ишлари режалаштирилган бўлиб, шу кунга қадар 15 дан ортиқ нимстанцияда бу борадаги ишлар амалга оширилди. &nbsp;Айни пайтда жойларда белгиланган эксплуатация бўйича чора-тадбирлар босқичма-босқич давом этмоқда. Хусусан, мутахассислар томонидан нимстанциялардаги куч трансформаторларда аниқланган камчиликлар бартараф этилиб, нормал режимда ишлаши таъминланмоқда.</big></p>\r\n\r\n<p style=\"text-align: justify;\"><big><img alt=\"\" src=\"http://het.uz/uploads/c8bdb285-23d7-ab9b-4adf-0922c44d595d_media_.jpg\" /></big></p>\r\n\r\n<p style=\"text-align: justify;\"><big>Бундан ташқари мавжуд электр қурилмалар тўлиқ назоратдан ўтказилиб, автоматик тарзда ишловчи ҳимоя воситаларини сифатли хизмат кўрсатишига эришилмоқда.&nbsp; Бу, ўз навбатида, истеъмолчиларга сифатли ва барқарор электр энергиясини етказиб беришга асос бўлади.</big></p>\r\n\r\n<p style=\"text-align: right;\"><strong><big>&nbsp;&ldquo;Фарғона ҲЭТК&rdquo; АЖ матбуот хизмати.</big></strong></p>\r\n', '29ee5df5-18bf-3ee9-57f2-e2f7e0136e4c_lists_.jpg', 'dfcbb901-dd69-565d-f86a-f7ac74a4fb48_lists_.jpg', 1672, 1, 5, NULL, 1613105878, 1760845312, ''),
(1311, 903, 'oz', '“ҲУДУДИЙ ЭЛЕКТР ТАРМОҚЛАРИ” АЖДА ДАВЛАТ ДАСТУРИ ИЖРОСИНИ САМАРАЛИ ТАШКИЛ ЭТИШГА БАҒИШЛАНГАН ТАДБИР ЎТКАЗИЛДИ', 'Бугун, 12 февралда “Ҳудудий электр тармоқлари” АЖда  Ўзбекистон Республикаси Президенти Шавкат Мирзиёевнинг 2021 йил  3 февралдаги “Ёшларни қўллаб-қувватлаш ва аҳоли саломатлигини мустаҳкамлаш йили” Давлат дастури ижросини самарали ташкил қилиш чора-тадбирларига бағишланган кенгайтирилган видеоселектор йиғилиши бўлиб ўтди. ', '<p style=\"text-align: center;\"><strong><big>&ldquo;ҲУДУДИЙ ЭЛЕКТР ТАРМОҚЛАРИ&rdquo; АЖДА ДАВЛАТ ДАСТУРИ ИЖРОСИНИ САМАРАЛИ ТАШКИЛ ЭТИШГА БАҒИШЛАНГАН ТАДБИР ЎТКАЗИЛДИ</big></strong></p>\r\n\r\n<p style=\"text-align: justify;\"><big>Бугун, 12 февралда &ldquo;Ҳудудий электр тармоқлари&rdquo; АЖда&nbsp; Ўзбекистон Республикаси Президенти Шавкат Мирзиёевнинг 2021 йил&nbsp; 3 февралдаги &ldquo;Ёшларни қўллаб-қувватлаш ва аҳоли саломатлигини мустаҳкамлаш йили&rdquo; Давлат дастури ижросини самарали ташкил қилиш чора-тадбирларига бағишланган кенгайтирилган видеоселектор йиғилиши бўлиб ўтди.</big></p>\r\n\r\n<p style=\"text-align: justify;\"><big><img alt=\"\" src=\"http://het.uz/uploads/6e86ab7b-fe36-0675-c6a0-83898365ad02_media_.jpg\" /><br />\r\nЎзбекистон Республикаси Вазирлар Маҳкамасининг Саноат ва унинг базавий тармоқларини ҳамда кооперация алоқаларини ривожлантириш масалалари Департаменти масъул ходими Ш. Шамсиддинов иштирокида ўтказилган тадбирда ҳудудий электр тармоқлари корхоналари, туман (шаҳар) электр таъминоти ва тизим корхоналари раҳбарлари, шунингдек, тегишли бошқармалар бошлиқлари ўз ҳисоботлари билан қатнашдилар. </big></p>\r\n\r\n<p style=\"text-align: justify;\"><big>Маълумки, 2017-2021 йилларда Ўзбекистон Республикасини ривожлантиришнинг бешта устувор йўналиши бўйича Харакатлар стратегияси доирасида ҳар йили махсус Давлат дастурлари қабул қилиниб, ҳаётга жорий этиб келинмоқда. Халқ билан бамаслаҳат, уларнинг таклифлари асосида қабул қилинган бу йилги &ldquo;Ёшларни қўллаб-қувватлаш ва аҳоли саломатлигини мустаҳкамлаш йили&rdquo; Давлат дастури 273 банддан иборат бўлиб, унда давлат бошқаруви, суд-ҳуқуқ, иқтисодиёт, ижтимоий соҳа, ташқи сиёсат ва ҳавфсизлик йўналишлари бўйича муҳим вазифалар белгиланган.</big></p>\r\n\r\n<p style=\"text-align: justify;\"><big><img alt=\"\" src=\"http://het.uz/uploads/23e04eec-519b-daad-54cc-5f5186bb5c52_media_.jpg\" /></big></p>\r\n\r\n<p style=\"text-align: justify;\"><big>Бошқарув раисининг биринчи ўринбосари Ж. Обиджонов йиғилишни кириш сўзи билан очар экан, Давлат дастурини амалга ошириш учун қарийб 30 трлн. сўм, 2,6 млрд. АҚШ доллари ва 57 млн.дан зиёд евро йўналтирилиши назарда тутилганига тўхталиб ўтди. </big></p>\r\n\r\n<blockquote>\r\n<p style=\"text-align: justify;\"><small><big>Таъкидлаш жоизки, мазкур ҳужжат билан 2021 йилда ижтимоий-иқтисодий ривожлантиришнинг энг устувор йўналишлари, олдимизга қўйилган стратегик мақсадлар, яъни мамлакатимизни замонавий ривожланган демократик давлатлар қаторига қўшиш, иқтисодиётимизнинг барқарор ўсишини таъминлаш, халқимиз турмуш фаровонлигини бундан ҳам юксалтириш борасидаги вазифалар белгилаб берилган экан, бу, ўз навбатида, биз &ndash; электр энергетикаси тизимида фаолият юритаётган соҳа ходимларига ҳам катта масъулият юклайди, &ndash; деди у. &ndash; Президентимиз Парламентга йўллаган Мурожаатномасида республикамиз барча ҳудудларида 130 минг километр узунликдаги паст кучланишли электр тармоқлари ва 40 мингдан ортиқ трансформатор пунктларини босқичма-босқич янгилаш бўйича дастур тасдиқланиши ҳақида алоҳида тўхталиб ўтилгани электр энергетикаси тизими иқтисодиётимиз ривожида муҳим аҳамият касб этиши, соҳада амалга оширилиши кутилаётган кенг кўламли ислоҳотлардан далолат бермоқда.</big></small></p>\r\n</blockquote>\r\n\r\n<p style=\"text-align: justify;\"><big>Жумладан, <strong>2021 йилда 15 минг км</strong> паст кучланишли электр тармоқлари ҳамда <strong>4 минг дона</strong> трансформатор пунктини реконструкция ва модернизация қилиш ишлари режалаштирилган бўлиб, шундан электр таъминоти оғир бўлган <strong>4 767</strong> <strong>та</strong> маҳалла ҳудудларида истеъмолчиларнинг электр энергияси таъминотини яхшилаш мақсадида <strong>4 206 км</strong> масофада электр узатиш тармоқлари ҳамда 1720 дона трансформатор пункти янгидан қурилиши биринчи галдаги вазифа сифатида белгилаб олинди. </big></p>\r\n\r\n<p style=\"text-align: justify;\"><big><img alt=\"\" src=\"http://het.uz/uploads/71b3247c-074b-2945-ec67-90ac784367db_media_.jpg\" /></big></p>\r\n\r\n<p style=\"text-align: justify;\"><big>Видеоселектор йиғилишида инвестиция, маҳаллийлаштириш, кооперация алоқаларини кенгайтириш, ахборот технологиялари, шунингдек, давлат дастурларини амалга ошириш ва капитал қурилиш йўналишида олиб борилаётган саъй-ҳаракатлар,&nbsp; &ldquo;Электр энергиясини ҳисобга олишни автоматлаштириш маркази&rdquo; фаолияти, аҳолидан электр энергияси таъминотига оид келиб тушаётган мурожаатлар бўйича ҳисоботлар эшитилиб, келгуси режаларга алоҳида тўхталиб ўтилди. Таъкидланганидек,&nbsp; жорий йилда амалга ошириладиган ишлар туманлар, шаҳарлар ва улардаги маҳаллалар кесимида ташкил этилиши шарт.</big></p>\r\n\r\n<p style=\"text-align: justify;\"><big>Таҳлил натижаларига кўра, <strong>2020 йилда</strong> жисмоний ва юридик шахслардан жами <strong>83 127 та</strong> мурожаат келиб тушган бўлиб, улардан <strong>55 528 та (68 фоиз)</strong> қаноатлантирилган, <strong>27 599 та (32,0 фоиз) </strong>тушунтиришлар берилган. Мурожаатларнинг аксарияти Сурхондарё, Самарқанд, Қашқадарё, Жиззах, Андижон ва Тошкент вилоятларидан йўлланган. Шулардан келиб чиқилиб, истеъмолчилар мурожаатлари билан ишлаш борасида раҳбарлар ва ижрочиларнинг шахсий масъулиятини ошириш устувор вазифалардан бири бўлиб қолишига йиғилганлар эътибори қаратилди.</big></p>\r\n\r\n<p style=\"text-align: justify;\"><big><img alt=\"\" src=\"http://het.uz/uploads/23003560-6e20-3bd7-2727-ef927a4970d3_media_.jpg\" /></big></p>\r\n\r\n<p style=\"text-align: justify;\"><big>Тадбирда сўзга чиққанлар Давлат дастурини ҳаётга жорий этишда фаол иштирокчига айланиш ҳар бир соҳа ходимининг бурчи эканлиги, зеро унда белгилаб берилган вазифалар халқимиз манфаатларига қаратилгани ва унга бефарқ бўлишга ҳеч кимнинг ҳаққи йўқлигига алоҳида тўхталиб ўтдилар.</big></p>\r\n\r\n<p style=\"text-align: justify;\"><big>Йиғилиш сўнгида тизимда фаолият юритаётган ёшларни ҳар томонлама қўллаб-қувватлаш, уларнинг билим олиш ва малакасини янада ошириш, саломатлигини мустаҳамлашга қаратилган чора-тадбирларни самарали ташкил этишга муҳим аҳамият қаратиш зарурлиги қайд этилди. </big></p>\r\n\r\n<p style=\"text-align: right;\"><strong><big>&ldquo;Ҳудудий электр тармоқлари&rdquo; АЖ Матбуот хизмати.</big></strong></p>\r\n', 'f67744b4-470f-bd87-c729-39eaf4a81e3f_lists_.jpg', '35e75fc3-0edc-e96e-b61c-aa3c06087bfc_lists_.jpg', 2132, 1, 5, NULL, 1613128228, 1760751889, ''),
(1312, 904, 'oz', 'ОЛМАЗОР ТУМАНИНИНГ АЙРИМ ҲУДУДЛАРИДА ЭЛЕКТР ЭНЕРГИЯСИ ТАЪМИНОТИДА УЗИЛИШЛАР КУЗАТИЛДИ', 'Бугун, 18 февраль куни Тошкент шаҳрининг Олмазор туманидаги қуввати 110/35/10 кВ бўлган юқори кучланишли «Сағбон» подстанциясида қисқа туташув натижасида авария ҳолатида ўчишлар кузатилди. ', '<p style=\"text-align: center;\"><big><strong>ОЛМАЗОР ТУМАНИНИНГ АЙРИМ ҲУДУДЛАРИДА ЭЛЕКТР ЭНЕРГИЯСИ ТАЪМИНОТИДА УЗИЛИШЛАР КУЗАТИЛДИ</strong></big></p>\r\n\r\n<p style=\"text-align: justify;\"><big>Бугун, 18 февраль куни Тошкент шаҳрининг Олмазор туманидаги қуввати 110/35/10 кВ бўлган юқори кучланишли &laquo;Сағбон&raquo; подстанциясида қисқа туташув натижасида авария ҳолатида ўчишлар кузатилди. </big></p>\r\n\r\n<p style=\"text-align: justify;\"><big>Натижада, электр энергия етказиб бериш жараёнида режадан ташқари ўчишлар юзага келиб, хусусан Қорақамиш даҳасининг 1/2, 2/1, 2/3, 2/4, 2/5-мавзелари, Келес йўли, &laquo;Аҳил&raquo; МФЙ, &laquo;Пахта&raquo; МФЙ, &laquo;Г. Ғофуров&raquo; МФЙ, &laquo;Бойқўрғон&raquo; МФЙ, &laquo;Бешқўрғон&raquo; МФЙ, &laquo;Олимпия&raquo; МФЙ, &laquo;Шодиёна&raquo; МФЙ, &laquo;Бўстонобод&raquo; МФЙларидаги уйларнинг аҳоли яшаш хонадонларида ҳамда тадбиркорлик субъектларида электр энергияси таъминоти вақтинчалик ўчирилди.</big></p>\r\n\r\n<p style=\"text-align: justify;\"><big>Айни вақтда, &laquo;Toshkent shahar ЕТК&raquo; AJнинг юқори кучланишли аварияларни тиклаш тезкор ишчи-бригада ходимлари томонидан носозликларни бартараф этиш бўйича таъмирлаш ишлари олиб борилмоқда.</big></p>\r\n\r\n<p style=\"text-align: justify;\"><big>Таъмирлаш ишлари туфайли электр энергияси таъминотидаги вақтинча узилишлар сабабли етказилаётган ноқулайликлар учун истеъмолчилардан узр сўраймиз.</big></p>\r\n\r\n<p style=\"text-align: right;\"><big><strong>&laquo;Toshkent shahar ЕТК&raquo; AJ матбуот хизмати</strong></big></p>\r\n', '945f98d4-78cc-5203-abab-f4e1488432fd_lists_.jpg', 'ffdff9dd-bb92-92f0-4c22-b9a88b0c401e_lists_.jpg', 1887, 1, 5, NULL, 1613625253, 1760678509, ''),
(1313, 905, 'oz', 'ЭЛЕКТР ЭНЕРГЕТИКАСИ ТИЗИМИДА ДАВЛАТ ВА ШАРТНОМАВИЙ ХИЗМАТЛАРНИ РИВОЖЛАНТИРИШ АСОСИЙ ВАЗИФАЛАРДАН БИРИДИР', '\"Хоразм ҳудудий электр тармоқлари\"АЖ нинг барча шаҳар ва туман раҳбарлари, масъул бўлим бошлиқлари иштирокида давлат ва шартномавий хизматларни ривожлантиришга бағишланган ўқув-семинар ташкил этилди. ', '<p style=\"text-align: center;\"><big><strong>ЭЛЕКТР ЭНЕРГЕТИКАСИ ТИЗИМИДА ДАВЛАТ ВА ШАРТНОМАВИЙ ХИЗМАТЛАРНИ РИВОЖЛАНТИРИШ АСОСИЙ ВАЗИФАЛАРДАН БИРИДИР</strong></big></p>\r\n\r\n<p><big>Маълумки, &quot;Ҳудудий электр тармоқлари&quot; АЖ томонидан шартномавий хизматларни ривожлантириш ва улгуржи истеъмолчиларга электр энергияси учун&nbsp;сифатли техник хизмат кўрсатиш мақсадида барча вилоятлар кесимида қатор режа дастурлар ишлаб чиқилган.&nbsp;</big></p>\r\n\r\n<p><big>Шу мақсадда, &quot;Хоразм ҳудудий электр тармоқлари&quot; АЖнинг асосий биносида&nbsp;&quot;Ҳудудий электр тармоқлари&quot;АЖ давлат ва шартномавий&nbsp;хизматларни ривожлантириш бошқарма бошлиғи Н. Мейлиев ва бошқарма мутахассиси М. Абдуллаев иштирокида жамиятнинг барча шаҳар ва туман раҳбарлари, масъул бўлим бошлиқларига ўқув семинар ташкил этилди.&nbsp;</big></p>\r\n\r\n<p><big><img alt=\"\" src=\"http://het.uz/uploads/6f8f8309-1ab8-6d6e-8dab-a3d27d82b283_media_.jpg\" /></big><br />\r\n<big>Семинарда таъкидланганидек, тадбиркорлар билан тўғри ва холис алоқани йўлга қўйиш, тезкор электр ҳужжатлар тизимини жорий қилиш, аҳоли томонидан&nbsp;келиб тушаётган маблағларни тўғри тақсимлашни ташкил этиш муҳим аҳамият касб этади.&nbsp;</big></p>\r\n\r\n<p><big><img alt=\"\" src=\"http://het.uz/uploads/f0fb181a-d34f-7ba6-d19b-8d5557ea9745_media_.jpg\" /></big></p>\r\n\r\n<p><big>Ўз навбатида, шартномавий режалардан келиб тушган маблағлар&nbsp;жамият биносини таъмирлаш, туман ва шаҳарларда электр таъминоти корхоналари&nbsp;эскирган биноларини қайта қуриш, шунингдек,&nbsp;ходимларни рағбатлантиришга қаратилади.&nbsp;</big></p>\r\n\r\n<p><big><img alt=\"\" src=\"http://het.uz/uploads/81356e27-1948-08c2-be56-b611bd79315b_media_.jpg\" /></big></p>\r\n\r\n<p><big>Бундан ташқари семинар давомида истеъмолчилардан келиб тушаётган мурожаатларга ҳам алоҳида тўхталиб, ҳар бир мурожаат ортида инсон борлиги ва уни муаммосини тезкорлик билан ҳал қилиш лозимлиги таъкидлаб ўтилди.&nbsp;</big></p>\r\n\r\n<p><big>Йиғилганлар ўзларини қизиқтирган саволларига жавоблар олиб, ўз билим ва кўникмаларини янада оширдилар.&nbsp;</big></p>\r\n\r\n<p style=\"text-align: right;\"><strong><big>&quot;Хоразм ҲЭТК&quot; АЖ матбуот хизмати.</big></strong></p>\r\n', '5335ca8f-a9a0-c7f4-d451-583d299ddaa7_lists_.jpg', 'fdd88bcf-0aa3-69c2-f136-e154136956db_lists_.jpg', 1496, 1, 5, NULL, 1614059351, 1760751320, '');
INSERT INTO `lists_lang` (`id`, `main_id`, `lang`, `title`, `anons`, `body`, `anonsImage`, `bodyImage`, `views`, `enabled`, `creator_id`, `modifier_id`, `created_at`, `updated_at`, `pdf`) VALUES
(1314, 906, 'oz', 'НАВОИЙ ШЭТК: ЭЛЕКТР ЭНЕРГИЯ ТАЪМИНОТИ СИФАТИ ЯХШИЛАНМОҚДА', 'Навоий шаҳар электр таъминоти корхонаси ишчи-ходимлари томонидан аҳолини сифатли ва узлуксиз электр энергияси билан таъминлаш борасида олиб борилаётган амалий ишлар таҳсинга лойиқ.', '<p style=\"text-align: center;\"><strong><big>НАВОИЙ ШЭТК: ЭЛЕКТР ЭНЕРГИЯ ТАЪМИНОТИ СИФАТИ ЯХШИЛАНМОҚДА</big></strong></p>\r\n\r\n<p style=\"text-align: justify;\"><big>Маълумки, электр энергиясига бўлган эҳтиёж аҳоли сони ўсиши ва саноат корхоналари ривожланиши билан ортиб боради. Ҳар қадамда қад кўтарилаётган бинолар, иншоотлар, айниқса замонаий кўриниш касб этаётган кўп қаватли уйлар фикримизнинг ёрқин исботидир. </big></p>\r\n\r\n<p style=\"text-align: justify;\"><big>Шу маънода, Навоий шаҳар электр таъминоти корхонаси ишчи-ходимлари томонидан аҳолини сифатли ва узлуксиз электр энергияси билан таъминлаш борасида олиб борилаётган амалий ишлар ҳам таҳсинга лойиқ.</big></p>\r\n\r\n<p style=\"text-align: justify;\"><big><img alt=\"\" src=\"http://het.uz/uploads/753bcc0e-6d62-df69-fdf9-c9ef80b3fbde_media_.jpg\" /></big></p>\r\n\r\n<p style=\"text-align: justify;\"><big>Ўзбекистон Республикаси Президентининг 2016 йил 23 ноябрдаги &ldquo;2017-2021 йиллар даврида паст кучланишли электр тармоқларини модернизация қилиш ва янгилаш чора-тадбирлари тўғрисида&rdquo;ги ПҚ-2661 сонли қарорига асосан 17,5 км электр узатиш тармоқлари ва 9 дона трансформатор пунктларини модернизация ва янгидан қуриш ишлари бажарилиши натижасида маҳаллий истеъмолчиларга электр энергияси етказиб бериш &nbsp;сифати янада ошди.</big></p>\r\n\r\n<p style=\"text-align: justify;\"><big>Шу билан бирга, 2021 йилда истеъмолчиларга сифатли ва барқарор электр энергияси етказиб бериш, электр узатиш тармоқларини янгилаш ва янги трансформаторлар ўрнатишга қаратилган амалий ишлар давом эттирилмоқда. Хусусан, Навоий шаҳрида 10 га яқин аҳоли яшаш пунктида 29 км электр узатиш тармоқлари ва 4 дона трансформатор пунктини модернизация ва янгидан қуриш ишлари режалаштирилган.</big></p>\r\n\r\n<p style=\"text-align: justify;\"><big><img alt=\"\" src=\"http://het.uz/uploads/cb52d079-e84c-6fc5-cadd-5e3a4a4982d2_media_.jpg\" /></big></p>\r\n\r\n<p style=\"text-align: justify;\"><big>Бундан ташқари, вилоят марказининг саноат корхоналари ва аҳолисини электр энергияси билан таъминлайдиган &quot;БСИ&quot; 110/10/6 нимстанциясида эскирган 6 кВ тақсимловчи ташқи электр узатиш мосламасини (КРУН) 10 кВга алмаштириш ишлари бажарилмоқда. 18 кичик туманни ва &ldquo;Ёшлик&rdquo; маҳалласини узлуксиз электр энергияси билан таъминлаш мақсадида 110/10 кВли &ldquo;Ёшлик&rdquo; нимстациясини қуриш ишлари бошланган.</big></p>\r\n\r\n<p style=\"text-align: justify;\"><big>Таъкидлаш жоизки, &ldquo;Навоий ҲЭТК&rdquo; АЖ ишчи-ходимлари томонидан ижтимоий-иқтисодий соҳа объектлари ва корхоналарни мустаҳкам электр энергияси билан таъминлаш ва тизимдаги нуқсонларни бартараф этиш чоралари давом эттирилмоқда.</big></p>\r\n\r\n<p style=\"text-align: right;\"><strong><big>&quot;Навоий ҲЭТК&quot; АЖ матбуот хизмати.</big></strong></p>\r\n', 'f3231d14-2f16-2ed5-ef86-52d56c80b14d_lists_.jpg', 'dea59089-377e-def7-c037-286918f76b58_lists_.jpg', 1932, 1, 5, NULL, 1614081801, 1760909814, ''),
(1315, 907, 'oz', 'ПОЙТАХТ ЭНЕРГЕТИКЛАРИ ТАБИАТ ИНЖИҚЛИКЛАРИГА ҚАРАМАСДАН ЎЗ ФАОЛИЯТЛАРИНИ КУЧАЙТИРИЛГАН ТАРТИБДА ОЛИБ БОРМОҚДАЛАР', 'Аҳоли, иқтисодиёт тармоқлари ва ижтимоий соҳа объектларини республикамиз ҳудудига кириб келган совуқ ҳаво оқимига қарамай, барқарор электр энергияси билан таъминлаш мақсадида, «Toshkent shahar elektr tarmoqlari korxonasi» AJ ҳамда унинг тасарруфидаги барча туман электр таъминоти корхоналари махсус тезкор ишчи-гуруҳи томонидан тегишли чора-тадбирлар асосида ишлар жадал суръатларда давом эттирилмоқда. ', '<p style=\"text-align: center;\"><strong><big>ПОЙТАХТ ЭНЕРГЕТИКЛАРИ ТАБИАТ ИНЖИҚЛИКЛАРИГА ҚАРАМАСДАН ЎЗ ФАОЛИЯТЛАРИНИ КУЧАЙТИРИЛГАН ТАРТИБДА ОЛИБ БОРМОҚДАЛАР</big></strong></p>\r\n\r\n<p style=\"text-align: justify;\"><big>Аҳоли, иқтисодиёт тармоқлари ва ижтимоий соҳа объектларини республикамиз ҳудудига кириб келган совуқ ҳаво оқимига қарамай, барқарор электр энергияси билан таъминлаш мақсадида, &laquo;Toshkent shahar elektr tarmoqlari korxonasi&raquo; AJ ҳамда унинг тасарруфидаги барча туман электр таъминоти корхоналари махсус тезкор ишчи-гуруҳи томонидан чора-тадбирлар асосида ишлар жадал суръатларда давом эттирилмоқда. </big></p>\r\n\r\n<p style=\"text-align: justify;\"><big><img alt=\"\" src=\"http://het.uz/uploads/c2bb4650-3149-a1a0-114e-bfb37b5c36d5_media_.jpg\" /></big></p>\r\n\r\n<p style=\"text-align: justify;\"><big>Айни вақтда, Олмазор тумани &laquo;Алон&raquo; МФЙ ҳудудида жойлашган 4199-сонли трансформатор подстанциясидан таъминланувчи 0,4 кВли паст кучланишли ҳаво электр узатиш тармоқларидаги эски ёғоч устунлар олиб ташланиб, ўрнига янги темир-бетон таянчлар ўрнатилиб, ҳар қандай об-ҳаво шароитида барқарор электр энергиясини таъминлай оладиган янги СИП русумидаги кабель тармоқлари тортиб берилмоқда.</big></p>\r\n\r\n<p style=\"text-align: justify;\"><big>Таъкидлаш жоизки, ҳудудлардаги турли қувватдаги трансформатор подстанцияларида режадагидек мукаммал ва жорий таъмирлаш ишлари, ҳаво электр узатиш тармоқларидаги эски ёғоч устунлар ўрнига янги темир-бетон таянчлар ҳамда ҳар қандай об-ҳаво шароитида барқарор&nbsp; электр таъминотини таъминлай оладиган янги СИП русумидаги кабель тармоқлари тортиш ишлари бажарилмоқда. </big></p>\r\n\r\n<p style=\"text-align: justify;\"><big><img alt=\"\" src=\"http://het.uz/uploads/7db1496f-cad4-de84-0068-3616594688e8_media_.jpg\" /></big></p>\r\n\r\n<p style=\"text-align: justify;\"><big>Шунингдек, зўриқиб ишлаётган мавжуд электр энергиясини тақсимлаш, яъни трансформатор пунктлари юкламасини камайтириш, маҳаллалар, туманлардаги истеъмолчилар электр&nbsp; таъминотини яхшилаш учун қуввати 6-10 кВ бўлган юқори кучланишли 61 тадан ортиқ трансформатор подстанциялари реконструкция ва модернизация қилиниб, маънан ҳамда жисмонан эскирган 0,4-6-10-35 кВли 506,4 км дан ортиқ кабель тармоқлари янгисига алмаштирилди.</big></p>\r\n\r\n<p style=\"text-align: justify;\"><big><img alt=\"\" src=\"http://het.uz/uploads/d5253488-b4a9-9fe7-2ed8-4d0a8a9a9afc_media_.jpg\" /></big></p>\r\n\r\n<p style=\"text-align: justify;\"><big>Бундан ташқари, совуқ иқлим даврида электр тармоқларида юзага келиши мумкин бўлган фавқулодда аварияли узилишларнинг олдини олиш, уларни қисқа вақт ичида бартараф қилиш мақсадида, &laquo;Toshkent shahar elektr tarmoqlari korxonasi&raquo; AJ томонидан барча туман электр таъминоти корхоналарида туну кун тезкор навбатчилик гуруҳлари ташкил этилиб, мазкур гуруҳлар зарур техник материаллари ва автотранспорт воситалари билан таъминланди.</big></p>\r\n\r\n<p style=\"text-align: justify;\"><big><img alt=\"\" src=\"http://het.uz/uploads/895e3439-25a7-97d8-a64b-2f3ed1c49595_media_.jpg\" /></big></p>\r\n\r\n<p style=\"text-align: right;\"><strong><big>&laquo;Toshkent shahar ЕТК&raquo; AJ матбуот хизмати.</big></strong></p>\r\n', '0efb46ed-596f-63b1-2ede-e6f02f372498_lists_.jpg', 'ee5e44c2-9248-211a-d394-f24311421868_lists_.jpg', 1631, 1, 5, NULL, 1614163239, 1760927212, ''),
(1316, 908, 'ru', 'Контакты пресс-службы', 'Контакты пресс-службы:  Тел.: (78) 150-75-63, Эл.почта: info@het.uz', '<p><big><strong>Контакты пресс-службы:</strong> &nbsp;<strong>Тел.: </strong>(78) 150-75-63,&nbsp;<strong>Эл.почта:</strong> info@het.uz</big></p>\r\n', NULL, NULL, 1049, 1, 5, NULL, 1614339053, 1760932460, ''),
