(2444, 1977, 'oz', 'Aholi murojaatlarini bartaraf etish bo‘yicha bir qator ishlar amalga oshirilmoqda', '', '', NULL, NULL, 466, 1, 6, NULL, 1711601302, 1760899522, ''),
(2445, 1978, 'oz', 'Namanganda Prezidentimiz ishtirokida qurilishga start berilgan energetika sohasida yangi loyihalar', '', '', NULL, NULL, 432, 1, 6, NULL, 1711601345, 1760806687, ''),
(2446, 1979, 'oz', 'O’quv darslari tashkil qilindi.', '', '', NULL, NULL, 422, 1, 6, NULL, 1711601450, 1760806689, '');
INSERT INTO `lists_lang` (`id`, `main_id`, `lang`, `title`, `anons`, `body`, `anonsImage`, `bodyImage`, `views`, `enabled`, `creator_id`, `modifier_id`, `created_at`, `updated_at`, `pdf`) VALUES
(2450, 1983, 'oz', 'Davlat idoralarining korrupsiyaga qarshi kurashishdagi faoliyati samaradorligi reyting baholandi', '', '<p><strong>Davlat idoralarining korrupsiyaga qarshi kurashishdagi faoliyati samaradorligi reyting baholandi</strong></p>\r\n\r\n<p><img alt=\"\" src=\"http://het.uz/uploads/2d8f68b2-fab3-173a-7216-82f4784d3af0_media_.jpg\" /></p>\r\n\r\n<p>Korrupsiyaga qarshi kurashish ishlarining samaradorligini reyting baholash tizimi bo&lsquo;yicha&nbsp;&nbsp;davlat organlari va tashkilotlari, shu jumladan, mahalliy ijro etuvchi hokimiyat organlarining 2023-yil davomidagi faoliyatida korrupsiyaga qarshi kurashish mexanizmlar qay darajada samarali amalga oshirilgani baholandi.</p>\r\n\r\n<p><img alt=\"\" src=\"http://het.uz/uploads/b788c8de-33d0-e7de-b92c-85438b08057f_media_.jpg\" /></p>\r\n\r\n<p><strong>Reyting natijalariga ko&lsquo;ra &quot;Hududiy elektr tarmoqlari &quot; AJning ko&lsquo;rsatgichlari &quot;yaxshi&quot;ga baholandi.</strong></p>\r\n', '6e3e50a5-81ba-c929-6eaa-0ada0c4f5482_lists_.jpg', '470f6119-be94-97fa-afd7-a43bcfeee1fe_lists_.jpg', 1289, 1, 4, NULL, 1711627860, 1760905245, ''),
(2451, 1984, 'oz', '“Hududiy elektr tarmoqlari” AJ Surxondaryo hududiy filiali tomonidan iste’molchilarni barqaror elektr energiyasi bilan ta’minlash maqsadida bir qator ishlar olib borilmoqda.', '“Hududiy elektr tarmoqlari” AJ Surxondaryo hududiy filiali tomonidan iste’molchilarni barqaror elektr energiyasi bilan ta’minlash maqsadida bir qator ishlar olib borilmoqda.', '<p>&ldquo;Hududiy elektr tarmoqlari&rdquo; AJ Surxondaryo hududiy filiali tomonidan iste&rsquo;molchilarni barqaror elektr energiyasi bilan ta&rsquo;minlash maqsadida bir qator ishlar olib borilmoqda.</p>\r\n\r\n<p><img alt=\"\" src=\"http://het.uz/uploads/9527359d-c433-1dc8-da5c-9e9376bc97da_media_.jpg\" /><img alt=\"\" src=\"http://het.uz/uploads/95cfae46-4e84-a25b-e081-c34a0d57f276_media_.jpg\" /></p>\r\n\r\n<p>Ayni vaqtda Termiz tuman eletr ta&rsquo;minoti tasarrufidagi 35/10 kV li &ldquo;Taraqqiyot&rdquo;podstansiyasidagi quvvati 4 000 kVA bo&rsquo;lgan kuch transformatori o&rsquo;rniga quvvati 6 300 kVA bo&rsquo;lgan transformatorni almashtirish ishlari amalga oshirilmoqda.</p>\r\n\r\n<p><img alt=\"\" src=\"http://het.uz/uploads/fe2eb8d4-26c9-c9ba-56fe-e7dc838a8732_media_.jpg\" /><img alt=\"\" src=\"http://het.uz/uploads/82991793-efe9-7ec9-605f-34f2ff351947_media_.jpg\" /></p>\r\n\r\n<p>Bu orqali tumandagi 6 ta mahalladagi iste&rsquo;molchilarni elektr energiya ta&rsquo;minoti yaxshilanishiga erishiladi.</p>\r\n', '79e4f099-7b0a-4f82-43f2-30a5d58c5c31_lists_.jpg', '611524e3-8703-9cf9-282b-bed2f041d2c5_lists_.jpg', 1927, 1, 4, NULL, 1712117695, 1760972326, ''),
(2452, 1985, 'oz', 'NAMANGAN VILOYATI ISTE’MOLCHILARINING ELEKTR TA’MINOTINI YANADA YAXSHILASH MAQSADIDA 40 MING KVALI 5 TA KUCH TRANSFORMATORI OLIB KELINDI', 'NAMANGAN VILOYATI ISTE’MOLCHILARINING ELEKTR TA’MINOTINI YANADA YAXSHILASH MAQSADIDA 40 MING KVALI 5 TA KUCH TRANSFORMATORI OLIB KELINDI', '<p>NAMANGAN VILOYATI ISTE&rsquo;MOLCHILARINING ELEKTR TA&rsquo;MINOTINI YANADA YAXSHILASH MAQSADIDA 40 MING KVALI 5 TA KUCH TRANSFORMATORI OLIB KELINDI</p>\r\n\r\n<p><img alt=\"\" src=\"http://het.uz/uploads/b3e087a5-ab01-4c7b-bd61-db691acf7903_media_.jpg\" /></p>\r\n\r\n<p>Namangan viloyatidagi aholi xonadonlari, ijtimoiy soha obyektlari va tadbirkorlik subyektlarining elektr taʼminotini yanada yaxshilash maqsadida har birining quvvati 40 000 kVA bo&lsquo;lgan 5 ta kuch transformatori olib kelindi.</p>\r\n\r\n<p><img alt=\"\" src=\"http://het.uz/uploads/2b3f306d-1d58-9391-a58e-0bdd450e624b_media_.jpg\" /></p>\r\n\r\n<p>Shuningdek, yaqin kunlarda viloyatga yana 1 ta 40 000 kVAli &nbsp;hamda 63 000 kVAli 2 ta kuch transformatori olib kelinishi rejalashtirilgan.</p>\r\n\r\n<p><img alt=\"\" src=\"http://het.uz/uploads/1764fb22-5c86-a984-a7ff-897e94287fe2_media_.jpg\" /></p>\r\n\r\n<p>&ldquo;Hududiy elektr tarmoqlari&rdquo; AJ Namangan hududiy filialiga yetkazib berilayotgan mazkur transformatorlar Kosonsoy, Davlatobod, Chortoq hamda Chust tumanlaridagi podstansiyalarga o&rsquo;rnatiladi va montaj qilinadi.</p>\r\n\r\n<p><img alt=\"\" src=\"http://het.uz/uploads/50753488-add6-50d6-bc52-dcadc265bc99_media_.jpg\" /></p>\r\n\r\n<p>Buning natijasida viloyat iste&rsquo;molchilarining elektr ta&rsquo;minotini yanada yaxshilashga erishiladi.</p>\r\n', '3dedb998-5525-ce2e-a2e8-6b7c3f0e4607_lists_.jpg', '9b97632d-22c3-ead9-472b-34e5cb36f170_lists_.jpg', 1373, 1, 4, NULL, 1712217887, 1760971519, ''),
(2453, 1986, 'oz', 'AMIR TEMUR AVLODLARIMIZ. ', 'AMIR TEMUR AVLODLARIMIZ. ', '<p>AMIR TEMUR AVLODLARIMIZ</p>\r\n\r\n<p><img alt=\"\" src=\"http://het.uz/uploads/2ad27424-7e44-4dcf-c15b-d364770d6e3b_media_.jpg\" /><img alt=\"\" src=\"http://het.uz/uploads/4876140a-3661-ecb2-2328-efb9f45aed49_media_.jpg\" /></p>\r\n\r\n<p>Hududiy elektr tarmoqlari aksiyadorlik jamiyati Namangan hududiy filialida an&#39;anaviy tarzda o&lsquo;tkazilib kelinayotgan &quot;Ma&#39;naviyat soat&quot;lari filialidagi xodimlar uchun doimiy yangiliklarga boy va muhim sanalarga bag&lsquo;ishlangaligi bilan e&#39;tiborlidir.&nbsp;</p>\r\n\r\n<p><img alt=\"\" src=\"http://het.uz/uploads/8c8d934b-91b0-1042-72eb-9790f45dafe0_media_.jpg\" /><img alt=\"\" src=\"http://het.uz/uploads/f0169e10-4ade-1c7d-263f-241f3c7507d1_media_.jpg\" /></p>\r\n\r\n<p>Navbatdagi ma&#39;naviyat soatining mavzusi sifatida, bizning buyuk ajdodlarimizdan biri, sarkarda, davlat arbobi, o&lsquo;z saltanatidagi boshqaruv san&#39;ati bilan butun olamga xaligacha doston bo&lsquo;lib kelinayotgan Amir Temur bobomizning hayot yo&lsquo;llari va bizgacha qoldirgan saboqlari haqida bo&lsquo;ldi.&nbsp;</p>\r\n\r\n<p><img alt=\"\" src=\"http://het.uz/uploads/0d37252a-47b0-6c6b-6e89-a8965e822295_media_.jpg\" /></p>\r\n\r\n<p>Barcha yig&lsquo;ilganlar, o&lsquo;zlari uchun kerakli tushuncha va bilimlarni olishdi.</p>\r\n\r\n<p><img alt=\"\" src=\"http://het.uz/uploads/e267e34c-f4a2-66f2-eebb-ebd066adf3e6_media_.jpg\" /><img alt=\"\" src=\"http://het.uz/uploads/fb0d573b-66e3-dbfe-f94f-a847d134982b_media_.jpg\" /></p>\r\n\r\n<p>&quot;Hududiy elektr tarmoqlari&quot; AJ Namangan hududiy filiali matbuot xizmati</p>\r\n', '8bc33dff-1d41-2d95-90e2-3cc09b457fc5_lists_.jpg', '1023bc42-2d40-379d-e498-3376b05fd18e_lists_.jpg', 1441, 1, 4, NULL, 1712985755, 1760883603, ''),
(2454, 1987, 'oz', '\"Hududiy elektr tarmoqlari\" AJ jamoasi  barchangizni mehr-oqibat, ezgulik va saxovat ayyomi — Ramazon hayiti bilan samimiy muborakbod etadi!', '\"Hududiy elektr tarmoqlari\" AJ jamoasi  barchangizni mehr-oqibat, ezgulik va saxovat ayyomi — Ramazon hayiti bilan samimiy muborakbod etadi!', '<p><strong>AZIZ VATANDOSHLAR!</strong></p>\r\n\r\n<p><strong>&quot;Hududiy elektr tarmoqlari&quot; AJ jamoasi &nbsp;barchangizni mehr-oqibat, ezgulik va saxovat ayyomi &mdash; Ramazon hayiti bilan samimiy muborakbod etadi!</strong></p>\r\n\r\n<p>Ushbu ulug&lsquo; kunda Sizlarga sihat-salomatlik, baxt-saodat, xonadonlaringizga fayzu baraka tilaymiz. Mohi Ramazonda qilingan barcha ezgu niyat va duolar ijobat bo&lsquo;lsin!&nbsp;</p>\r\n\r\n<p>Yurtimiz tinch va osmonimiz musaffo bo&lsquo;lsin, jonajon O&lsquo;zbekistonimiz gullab-yashnasin!</p>\r\n\r\n<p><strong>Ramazon hayiti muborak bo&lsquo;lsin!</strong></p>\r\n\r\n<p>***</p>\r\n\r\n<p><strong>ДОРОГИЕ СООТЕЧЕСТВЕННИКИ!</strong></p>\r\n\r\n<p><strong>Коллектив АО &laquo;Региональные электрические сети&raquo; поздравляет всех наших соотечественников со священным и светлым праздником &mdash; Рамазан хайит!</strong></p>\r\n\r\n<p>В этот священный день желаем Вам здоровья, благополучия, счастья и достатка вашим семьям. Пусть сбудутся все добрые пожелания и молитвы совершенные в дни священного Рамазана!&nbsp;</p>\r\n\r\n<p>Пусть всегда в нашей стране царит мир, будет чистым небо над нашей Родиной!&nbsp;</p>\r\n\r\n<p><strong>С праздником Рамазан хайит!</strong></p>\r\n', 'a4968ad4-0de5-b03e-42f4-c503a6a00c35_lists_.jpg', 'f473ee7d-b322-c0ea-c8c5-9cf00002803f_lists_.jpg', 1443, 1, 4, NULL, 1712986037, 1760959621, ''),
(2455, 1988, 'oz', '2024 YIL 1 MAYDAN  ELEKR ENERGIYASI UCHUN TA’RIFLAR', '', '<p><big>O&lsquo;zbekiston Respublikasi Vazirlar Mahkamasining 2024 yil 16 apreldagi &ldquo;Yoqilg&lsquo;i-energetika sohasida bozor mexanizmlarini joriy etishning qo&lsquo;shimcha chora-tadbirlari to&lsquo;g&lsquo;risida&rdquo; 204 sonli qaroriga asosan, &ldquo;Hududiy elektr tarmoqlari&rdquo; AJ 2024 yil 1 maydan boshlab elektr energiyasining narxlari oshishini ma&rsquo;lum qiladi.</big></p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<table class=\"table table-bordered table-striped\">\r\n	<tbody>\r\n		<tr>\r\n			<td>\r\n			<p style=\"text-align: center;\"><big>T/r</big></p>\r\n			</td>\r\n			<td>\r\n			<p style=\"text-align: center;\"><big>Iste&rsquo;molchilar nomi</big></p>\r\n			</td>\r\n			<td>\r\n			<p style=\"text-align: center;\"><big>O&lsquo;lchov birligi</big></p>\r\n			</td>\r\n			<td>\r\n			<p style=\"text-align: center;\"><big>O&lsquo;lchov birligi uchun narxlar<br />\r\n			(QQS hisobga olingan holda,so&lsquo;m)</big></p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td>\r\n			<p style=\"text-align: center;\"><big>I.</big></p>\r\n			</td>\r\n			<td>\r\n			<p><big>Iste&rsquo;molchilarning I&nbsp;&mdash;&nbsp;IV guruhlari uchun elektr energiyasi</big></p>\r\n			</td>\r\n			<td>\r\n			<p><big>&nbsp;</big></p>\r\n			</td>\r\n			<td>\r\n			<p style=\"text-align: center;\"><big>&nbsp;</big></p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td>\r\n			<p style=\"text-align: center;\"><big>1.1.</big></p>\r\n			</td>\r\n			<td>\r\n			<p><big>Iste&rsquo;molchilarning I va II guruhlari:</big></p>\r\n\r\n			<p><big>a)&nbsp;&ldquo;Olmaliq kon-metallurgiya kombinati&rdquo; AJ, &ldquo;Navoiy kon-metallurgiya kombinati&rdquo; AJ, &ldquo;O&lsquo;zbekiston metallurgiya kombinati&rdquo; AJ va uning tarkibiga kiruvchi ishlab chiqaruvchi korxonalar,&nbsp;byudjet&nbsp;tashkilotlari, shuningdek, nasos stansiyalari iste&rsquo;mol qiladigan elektr energiyasining davlat byudjetidan moliyalashtiriladigan qismi uchun;</big></p>\r\n\r\n			<p><big>b)&nbsp;qolgan iste&rsquo;molchilar uchun</big></p>\r\n			</td>\r\n			<td rowspan=\"5\">\r\n			<p>&nbsp;</p>\r\n\r\n			<p>&nbsp;</p>\r\n\r\n			<p>&nbsp;</p>\r\n\r\n			<p>&nbsp;</p>\r\n\r\n			<p>&nbsp;</p>\r\n\r\n			<p>&nbsp;</p>\r\n\r\n			<p>&nbsp;</p>\r\n\r\n			<p>&nbsp;</p>\r\n\r\n			<p>&nbsp;</p>\r\n\r\n			<p>&nbsp;</p>\r\n\r\n			<p>&nbsp;</p>\r\n\r\n			<p>&nbsp;</p>\r\n\r\n			<p>&nbsp;</p>\r\n\r\n			<p>&nbsp;</p>\r\n\r\n			<p>&nbsp;</p>\r\n\r\n			<p style=\"text-align: center;\"><big>kVt soat</big></p>\r\n			</td>\r\n			<td>\r\n			<p style=\"text-align: center;\"><big>&nbsp;</big></p>\r\n\r\n			<p style=\"text-align: center;\"><big>1&nbsp;000</big></p>\r\n\r\n			<p style=\"text-align: center;\"><big>&nbsp; &nbsp;</big></p>\r\n\r\n			<p style=\"text-align: center;\">&nbsp;</p>\r\n\r\n			<p style=\"text-align: center;\">&nbsp;</p>\r\n\r\n			<p style=\"text-align: center;\">&nbsp;</p>\r\n\r\n			<p style=\"text-align: center;\">&nbsp;</p>\r\n\r\n			<p style=\"text-align: center;\">&nbsp;</p>\r\n\r\n			<p style=\"text-align: center;\"><big>&nbsp;900</big></p>\r\n\r\n			<p style=\"text-align: center;\">&nbsp;</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td>\r\n			<p style=\"text-align: center;\"><big>1.2.</big></p>\r\n			</td>\r\n			<td>\r\n			<p><big>Iste&rsquo;molchilarning III guruhi, shu jumladan aholi:</big></p>\r\n			</td>\r\n			<td>\r\n			<p style=\"text-align: center;\"><big>&nbsp;</big></p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td>\r\n			<p style=\"text-align: center;\"><big>1.2.1.</big></p>\r\n			</td>\r\n			<td>\r\n			<p><big>Ovqat tayyorlash uchun markazlashgan holda elektr plitalari bilan jihozlangan ko&lsquo;p kvartirali uy-joylar va yotoqxonalarda yashaydigan maishiy iste&rsquo;molchilar uchun bir oydagi iste&rsquo;moldan kelib chiqib:</big></p>\r\n\r\n			<p>&nbsp;</p>\r\n\r\n			<p><big>- oyiga 200 kVt&middot;soatgacha;</big></p>\r\n\r\n			<p><big>- oyiga 201 kVt&middot;soatdan 1 000 kVt&middot;soatgacha;</big></p>\r\n\r\n			<p><big>- oyiga 1 001 kVt&middot;soatdan 5 000 kVt&middot;soatgacha;</big></p>\r\n\r\n			<p><big>- oyiga 5 001 kVt&middot;soatdan 10 000 kVt&middot;soatgacha;</big></p>\r\n\r\n			<p><big>- oyiga 10&nbsp;000 kVt&middot;soat va undan yuqori.</big></p>\r\n			</td>\r\n			<td>\r\n			<p style=\"text-align: center;\">&nbsp;</p>\r\n\r\n			<p style=\"text-align: center;\">&nbsp;</p>\r\n\r\n			<p style=\"text-align: center;\">&nbsp;</p>\r\n\r\n			<p style=\"text-align: center;\">&nbsp;</p>\r\n\r\n			<p style=\"text-align: center;\">&nbsp;</p>\r\n\r\n			<p style=\"text-align: center;\"><big><small>225</small></big></p>\r\n\r\n			<p style=\"text-align: center;\"><big><small>450</small></big></p>\r\n\r\n			<p style=\"text-align: center;\"><big><small>675 </small></big></p>\r\n\r\n			<p style=\"text-align: center;\"><big><small>787,5</small></big></p>\r\n\r\n			<p style=\"text-align: center;\"><big><small>900</small></big></p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td>\r\n			<p style=\"text-align: center;\"><big>1.2.2.</big></p>\r\n			</td>\r\n			<td>\r\n			<p><big>Qolgan iste&rsquo;molchilar uchun bir oydagi iste&rsquo;moldan kelib chiqib:</big></p>\r\n\r\n			<p><big>- oyiga 200 kVt&middot;soatgacha;</big></p>\r\n\r\n			<p><big>- oyiga 201 kVt&middot;soatdan 1 000 kVt&middot;soatgacha;</big></p>\r\n\r\n			<p><big>- oyiga 1 001 kVt&middot;soatdan 5 000 kVt&middot;soatgacha;</big></p>\r\n\r\n			<p><big>- oyiga 5 001 kVt&middot;soatdan 10 000 kVt&middot;soatgacha;</big></p>\r\n\r\n			<p><big>- oyiga 10&nbsp;000 kVt&middot;soat va undan yuqori.</big></p>\r\n			</td>\r\n			<td>\r\n			<p style=\"text-align: center;\">&nbsp;</p>\r\n\r\n			<p style=\"text-align: center;\">&nbsp;</p>\r\n\r\n			<p style=\"text-align: center;\"><big>450 </big></p>\r\n\r\n			<p style=\"text-align: center;\"><big>900 </big></p>\r\n\r\n			<p style=\"text-align: center;\"><big>1 350 </big></p>\r\n\r\n			<p style=\"text-align: center;\"><big>1 575 </big></p>\r\n\r\n			<p style=\"text-align: center;\"><big>1 800</big></p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td>\r\n			<p style=\"text-align: center;\"><big>1.3.</big></p>\r\n			</td>\r\n			<td>\r\n			<p><big>Iste&rsquo;molchilarning IV guruhi:</big></p>\r\n			</td>\r\n			<td>\r\n			<p style=\"text-align: center;\"><big>900</big></p>\r\n			</td>\r\n		</tr>\r\n	</tbody>\r\n</table>\r\n', NULL, NULL, 62467, 1, 4, NULL, 1713356344, 1760974275, ''),
(2456, 1989, 'oz', 'Ommaviy axborot vositalari xodimlari va blogerlarga yangi qaror mazmun-mohiyati tushuntirildi.', 'Ommaviy axborot vositalari xodimlari va blogerlarga yangi qaror mazmun-mohiyati tushuntirildi.', '<p><strong>Ommaviy axborot vositalari xodimlari va blogerlarga yangi qaror mazmun-mohiyati tushuntirildi.</strong></p>\r\n\r\n<p><img alt=\"\" src=\"http://het.uz/uploads/175079f4-69d5-9b58-bef5-048e03453ac5_media_.jpg\" /><img alt=\"\" src=\"http://het.uz/uploads/32c21462-39ce-30e4-7f4f-780106a875ed_media_.jpg\" /></p>\r\n\r\n<p>Bugun Oʼzbekiston Respublikasi Energetika vazirligi hamda &quot;Hududiy elektr tarmoqlari&quot; АJ&nbsp;&nbsp;hamkorligida &quot;Elektr energiyasi sotishni avtomatlashtirish Markazi&quot; filialida OAV xodimlari, jurnalist va blogerlar uchun press-tur tashkil etildi.&nbsp;</p>\r\n\r\n<p><img alt=\"\" src=\"http://het.uz/uploads/1a51e362-58b4-78c9-9757-944fc7d90367_media_.jpg\" /><img alt=\"\" src=\"http://het.uz/uploads/82c04abd-38b6-3c4f-93c6-cc90b3d6830c_media_.jpg\" /></p>\r\n\r\n<p>Tadbir davomida Markaz rahbariyati va mutaxassislari tomonidan Vazirlar Mahkamasining 2024-yil 16-aprelda &ldquo;Yoqilg&lsquo;i-energetika sohasida bozor mexanizmlarini joriy etishning qo&lsquo;shimcha chora-tadbirlari to&lsquo;g&lsquo;risida&rdquo;gi 204-sonli qarori mazmun-mohiyati va kelgusida erishiladigan natijalar haqida&nbsp;&nbsp;press-tur ishtirokchilariga ma&#39;lumotlar berildi.</p>\r\n\r\n<p><img alt=\"\" src=\"http://het.uz/uploads/095879c4-3502-8670-14fc-a4a74c012f84_media_.jpg\" /><img alt=\"\" src=\"http://het.uz/uploads/30cc4a53-b150-8370-267a-6a45a32cdf42_media_.jpg\" /></p>\r\n\r\n<p>Xususan, joriy yilning&nbsp;&nbsp;1-may kunidan aholi istemolchilari uchun amaliyotga tatbiq etilayotgan&nbsp;&nbsp;yangi tariflarning elektr energiyasini hisobga olish va nazorat qilishning avtomatlashtirilgan tizimi (EEHO va NQAT) orqali hisoblanishi haqida batafsil to&#39;xtalib o&lsquo;tildi.</p>\r\n', '06d865d9-8f1e-c633-aac1-3c6bd2bd93a9_lists_.jpg', 'c8c49264-1d3e-9aa6-979e-049248700bbc_lists_.jpg', 2137, 1, 4, NULL, 1713772592, 1760970949, ''),
(2457, 1990, 'oz', '“Hududiy elektr tarmoqlari”AJ Qoraqolpag‘iston hududiy filiali tomonidan  OAV xodimlari, jurnalist va blogerlar ishtirok press tur bo‘lib o‘tdi.', '“Hududiy elektr tarmoqlari”AJ Qoraqolpag‘iston hududiy filiali tomonidan  OAV xodimlari, jurnalist va blogerlar ishtirok press tur bo‘lib o‘tdi', '<p><big><strong>&ldquo;Hududiy elektr tarmoqlari&rdquo;AJ Qoraqolpag&lsquo;iston hududiy filiali tomonidan &nbsp;OAV xodimlari, jurnalist va blogerlar ishtirok press tur bo&lsquo;lib o&lsquo;tdi</strong></big></p>\r\n\r\n<p><img alt=\"\" src=\"http://het.uz/uploads/a3a773d1-f4b9-c135-0363-e22a1659c03b_media_.jpg\" /><img alt=\"\" src=\"http://het.uz/uploads/a7580a85-8cf2-a3b7-b1fb-be1f9ce12a13_media_.jpg\" /></p>\r\n\r\n<p><strong>Tadbir davomida &quot;Hududiy elektr tarmoqlari&quot; AJ Qoraqolpag&lsquo;iston hududiy filiali rahbar va mutaxassislari tomonidan Vazirlar Mahkamasining 2024-yil 16 aprelda &ldquo;Yoqilg&lsquo;i-energetika sohasida bozor mexanizmlarini joriy etishning qo&lsquo;shimcha chora-tadbirlari to&lsquo;g&lsquo;risida&rdquo;gi 204-sonli qarorini mazmun mohiyati va kelgusida erishiladigan natijalar xaqida &nbsp;OAV xodimlari, jurnalist va blogerlarga ma&#39;lumotlar berildi.</strong></p>\r\n\r\n<p><img alt=\"\" src=\"http://het.uz/uploads/bce57fb5-f7f1-190f-201f-77e983fcf2ee_media_.jpg\" /><img alt=\"\" src=\"http://het.uz/uploads/b5c5a045-1fa2-0893-5abd-c5c9abd20d9c_media_.jpg\" /></p>\r\n\r\n<p><strong>Shundan sо&lsquo;ng mutaxassislar tomonidan ishtirokchilarga joriy yilning &nbsp;1 may kunidan amaliyotga tadbiq etilayotgan aholi iste&rsquo;molchilari uchun yangi tariflarning elektr energiyasini hisobga olish va nazorat qilishning avtomatlashtirilgan tizimi (EEHO va NQAT) orqali hisoblanishi haqida tanishtirib o&lsquo;tildi.</strong></p>\r\n\r\n<p><img alt=\"\" src=\"http://het.uz/uploads/5a3be51f-cccf-4a95-d5af-bf65ec5ac656_media_.jpg\" /><img alt=\"\" src=\"http://het.uz/uploads/0c998556-4d51-0a74-9df5-8ac27dacd2e5_media_.jpg\" /></p>\r\n\r\n<p><strong>Matbuot anjumani davomida jurnalist va blogerlar o&lsquo;zlarini qiziqtirgan savollariga javob oldilar.</strong></p>\r\n', '028a7154-9a59-bc9e-3635-9f018747e971_lists_.jpg', 'ed3d81c5-44cd-e095-65f2-269657e233c7_lists_.jpg', 1488, 1, 4, NULL, 1713772988, 1760968893, ''),
(2458, 1988, 'ru', 'ТАРИФЫ ЗА ЭЛЕКТРИЧЕСКУЮ ЭНЕРГИЮ С 1 МАЯ 2024 ГОДА', '', '<p><strong><big>В соответствии с Постановлением Кабинета Министров Республики Узбекистан ПКМ-№ 204 &nbsp;от 16.04.2024 г. &laquo;О дополнительных мерах по внедрению рыночных механизмов в топливно-энергетическую сферу&raquo; АО &laquo;Региональные электрические сети&raquo; сообщает о повышении тарифов за электроэнергию &nbsp;с 1 мая 2024 года.</big></strong></p>\r\n', NULL, NULL, 27807, 1, 4, NULL, 1713938491, 1760968908, ''),
(2459, 1991, 'oz', 'HURMATLI ELEKTR ENERGIYASI ISTE’MOLCHILARI!', '“Hududiy elektr tarmoqlari” AJ jamiyat tomonidan kibertahdid va axborot resurslarining kiberhujumlarga qarshi zaifliklarining oldini olish, shuningdek, iste’molchilar ma’lumotlari xavfsizligini kompleks ta’minlash bo‘yicha tashkiliy-texnik ishlar olib borilayotganini ma’lum qiladi.', '<p style=\"text-align: center;\"><strong><big>HURMATLI ELEKTR ENERGIYASI ISTE&rsquo;MOLCHILARI!</big></strong></p>\r\n\r\n<p><big>&ldquo;Hududiy elektr tarmoqlari&rdquo; AJ jamiyat tomonidan kibertahdid va axborot resurslarining kiberhujumlarga qarshi zaifliklarining oldini olish, shuningdek, iste&rsquo;molchilar ma&rsquo;lumotlari xavfsizligini kompleks ta&rsquo;minlash bo&lsquo;yicha tashkiliy-texnik ishlar olib borilayotganini ma&rsquo;lum qiladi.</big></p>\r\n\r\n<p><big>Shu munosabat bilan jismoniy va yuridik shaxslarning shaxsiy kabinetlariga xorijiy IP manzillardan kirish vaqtinchalik cheklanishini ma&rsquo;lum qilamiz.</big></p>\r\n', 'b90b3495-1e1f-149c-8b8a-85747620a44f_lists_.jpg', '89b12bbd-f32c-8496-5e07-64a888a7853b_lists_.jpg', 34357, 1, 4, NULL, 1714133036, 1760844107, ''),
(2460, 1991, 'ru', 'УВАЖАЕМЫЕ ПОТРЕБИТЕЛИ ЭЛЕКТРОЭНЕРГИИ!', 'АО \"Региональные электрические сети\" уведомляет о том, что со стороны Общества ведутся организационные и технические работы по предотвращению уязвимости к киберугрозам и кибератакам информационных ресурсов, а также комплексному обеспечению безопасности цифровых данных потребителей. ', '<p style=\"text-align: center;\"><strong><big>УВАЖАЕМЫЕ ПОТРЕБИТЕЛИ ЭЛЕКТРОЭНЕРГИИ!</big></strong></p>\r\n\r\n<p><big>АО &quot;Региональные электрические сети&quot; уведомляет о том, что со стороны Общества ведутся организационные и технические работы по предотвращению уязвимости к киберугрозам и кибератакам информационных ресурсов, а также комплексному обеспечению безопасности цифровых данных потребителей.&nbsp;</big></p>\r\n\r\n<p><big>&nbsp;В связи с этим, &nbsp;доступ &nbsp;в личный кабинет физических и юридических лиц с иностранных IP-адресов &nbsp;временно будет ограничен.</big></p>\r\n', 'e078fd40-5e87-eac3-6478-25e6839d1b72_lists_2460.jpg', 'bfa50e98-239d-502d-6fed-178a7200ba72_lists_2460.jpg', 19740, 1, 4, NULL, 1714133120, 1760950293, ''),
(2461, 1992, 'oz', 'OZARBAYJONLIK MUTASADDILAR ASKUE TIZIMINI JORIY ETISH BO‘YICHA O‘ZBEKISTON TAJRIBASI BILAN TANISHDILAR', 'OZARBAYJONLIK MUTASADDILAR ASKUE TIZIMINI JORIY ETISH BO‘YICHA O‘ZBEKISTON TAJRIBASI BILAN TANISHDILAR', '<p><strong>OZARBAYJONLIK MUTASADDILAR ASKUE TIZIMINI JORIY ETISH BO&lsquo;YICHA O&lsquo;ZBEKISTON TAJRIBASI BILAN TANISHDILAR</strong></p>\r\n\r\n<p><strong><img alt=\"\" src=\"http://het.uz/uploads/3b8e5cae-0cf5-e7d5-c430-953ff0be7a75_media_.jpg\" /></strong></p>\r\n\r\n<p><strong>Uchinchi Toshkent xalqaro investitsiya forumida ishtirok etish uchun mamlakatimizga tashrif buyurgan Ozarbayjon Respublikasi &laquo;Azerishig&raquo; aksiyadorlik jamiyati mutasaddilaridan iborat delegatsiya a&rsquo;zolari &ldquo;Hududiy elektr tarmoqlari&rdquo; Ajning &ldquo;Elektr energiyasi sotishni avtomatlashtirish markazi&rdquo; filialida respublikamiz bo&lsquo;ylab joriy etilgan elektr energiyasini hisobga olishni avtomatlashtirish tizimi bilan yaqindan tanishdilar.&nbsp;</strong></p>\r\n\r\n<p><img alt=\"\" src=\"http://het.uz/uploads/85c9a278-97db-007b-376a-f4679fd60086_media_.jpg\" /><img alt=\"\" src=\"http://het.uz/uploads/c8a609da-0e16-0be7-a9c1-ac37c0b2803e_media_.jpg\" /><img alt=\"\" src=\"http://het.uz/uploads/14280f55-fbff-2831-009a-5a71b45a4dfd_media_.jpg\" /></p>\r\n\r\n<p><strong>Markaz rahbari о&lsquo;rinbosari Diyor Nishonov mehmonlarga tizim imkoniyatlari haqida gapirarkan, bu yerda dunyoning yetakchi davlatlarida ishlab chiqarilgan server qurilmalari o&lsquo;rnatilgani, ulardagi dasturiy ta&rsquo;minot orqali qariyb 20,0 mln. iste&rsquo;molchiga xizmat ko&lsquo;rsatish imkoniyati mavjudligi haqida atroflicha ma&rsquo;lumot berib o&lsquo;tdi.<img alt=\"\" src=\"http://het.uz/uploads/ce40e71a-a86f-ecaa-4a21-041c82d4e2f3_media_.jpg\" /></strong></p>\r\n\r\n<p><strong>Tanishuv doirasida, shuningdek, delegatsiya a&rsquo;zolari uchun Jamiyat tomonidan elektr energiyasini hisobga olish va nazarot qilishning avtomatlashtirilgan tizimi (ASKUE)ni joriy etish hamda orttirilgan tajriba va natijalar xususida taqdimotlar o&lsquo;tkazildi.<img alt=\"\" src=\"http://het.uz/uploads/470d49ec-3a49-bf76-1b09-38b80661e4cc_media_.jpg\" /></strong></p>\r\n\r\n<p><br />\r\n<strong>Xususan, respublika, viloyat, tuman (shahar) va mahallalar kesimida elektr energiyasi iste&rsquo;molchilarining ma&rsquo;lumotlari saqlanishi, maxsus dasturiy ta&rsquo;minot orqali elektr energiyasining soatlik, sutkalik, oylik va yillik balanslarini shaklllantirish, ko&lsquo;p tariflik tizimida hisob-kitoblarni amalga oshirish imkoni mavjudligi amaliyotda kо&lsquo;rsatib о&lsquo;tildi.&nbsp;&nbsp;</strong></p>\r\n\r\n<p><strong>Tashrif sо&lsquo;ngida mehmonlar markaz hovlisida о&lsquo;rnatilgan avtomobillarni elektr energiyasi bilan quvvatlashga mо&lsquo;ljallangan quyosh elektr stansiyasi imkoniyatlari bilan tanishtirildi.<img alt=\"\" src=\"http://het.uz/uploads/94395d2a-f837-8c16-6828-dfa9c5a8b021_media_.jpg\" /></strong></p>\r\n\r\n<p><strong>Shuningdek, tadbir davomida mehmonlar &ldquo;Elektron xisoblagich&rdquo; MCHJ QKda bо&lsquo;lib, hisoblagichlarning ishlab chiqarish jarayonlari bilan ham yaqindan tanishdilar.<img alt=\"\" src=\"http://het.uz/uploads/200c4a73-a473-4d14-909e-f9277191a8ee_media_.jpg\" /><img alt=\"\" src=\"http://het.uz/uploads/edee2045-c445-4de6-faad-2c9bf0172421_media_.jpg\" /></strong></p>\r\n', 'e8eb0559-efff-79ee-a755-b7b690fb2e88_lists_2461.jpg', '', 1556, 1, 4, NULL, 1714653426, 1760969399, ''),
(2462, 1993, 'oz', '“CHINOBOD” PODSTANSIYASINING QUVVATI OSHIRILDI', '“CHINOBOD” PODSTANSIYASINING QUVVATI OSHIRILDI\r\n\r\n', '<p><big><strong>&ldquo;CHINOBOD&rdquo; PODSTANSIYASINING QUVVATI OSHIRILDI</strong></big></p>\r\n\r\n<p><big><strong><img alt=\"\" src=\"http://het.uz/uploads/5e299160-27de-ec22-475c-878b1ba5f76f_media_.jpg\" /></strong></big></p>\r\n\r\n<p><big>Andijon viloyati aholisini sizfatli elektr energiyasi bilan ta&rsquo;minlash maqsadida &ldquo;Hududiy elektr tarmoqlari&rdquo; AJ Andijon hududiy filiali tomonidan hududlarda podstansiyalarning quvvatini oshirish ishlari bosqichma bosqich amalga oshirilmoqda.</big></p>\r\n\r\n<p><big><img alt=\"\" src=\"http://het.uz/uploads/618fb679-1bb4-1d3e-fcd0-e364e6da2241_media_.jpg\" /><img alt=\"\" src=\"http://het.uz/uploads/a8efbe39-4ad1-7c9b-e0f4-0037f23c8abe_media_.jpg\" /></big></p>\r\n\r\n<p><big>Xususan, Baliqchi tumanida joylashgan &ldquo;Chinobod&rdquo; 110/35/10 kV podstansiyasidagi mavjud T-1 quvvati 16000 kVA bo&rsquo;lgan kuch transformatori quvvati 25000 kVA bo&rsquo;lgan kuch transformatoriga almashtirildi. Buning natijasida ushbu podstansiyaning quvvati 9 000 kVA ga oshirilib, tumandagi 10 mingdan ortiq aholi xonadonlarining elektr energiyasi sifati yaxshilanishiga erishildi.</big></p>\r\n\r\n<p><big><img alt=\"\" src=\"http://het.uz/uploads/0c07ae01-f274-252e-f194-a5467836e580_media_.jpg\" /><img alt=\"\" src=\"http://het.uz/uploads/6c3af30f-7540-71a2-1486-3f3cd466e391_media_.jpg\" /></big></p>\r\n', '4ef9b89f-61df-de4b-5a02-0cd011e74878_lists_.jpg', 'fc5e6105-8090-8c51-f2ca-a5ed28569a36_lists_.jpg', 1499, 1, 4, NULL, 1715078864, 1760902725, ''),
(2463, 1994, 'oz', 'gender_siyosati', NULL, '<div>\r\n<div style=\"background: rgb(238, 238, 238); border: 1px solid rgb(204, 204, 204); padding: 5px 10px; text-align: center;\"><a href=\"http://het.uz/uploads/bb524e8d-5376-b4f2-bf3b-ebce56609b59_media_.pdf\"><big>&quot;Hududiy elektr tarmoqlari&quot; AJning Gender masalalari bo yicha 2025 yil uchun<br />\r\n<strong>HARAKATLAR REJASI</strong></big></a></div>\r\n</div>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<div style=\"background: rgb(238, 238, 238); border: 1px solid rgb(204, 204, 204); padding: 5px 10px; text-align: center;\"><a href=\"http://het.uz/uploads/fcfcf8b7-6842-8635-e455-b80aa8de1410_media_.docx\"><big>&laquo;Hududiy elektr tarmoqlari&raquo; AJda xotin-qizlar va erkaklar uchun teng huquq hamda imkoniyatlarni ta&rsquo;minlash bо&lsquo;yichamaslahat kengashi faoliyatini tashkil etish bо&lsquo;yicha<br />\r\n<strong>NIZOM</strong></big></a></div>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<div style=\"background: rgb(238, 238, 238); border: 1px solid rgb(204, 204, 204); padding: 5px 10px; text-align: center;\"><big><a href=\"http://het.uz/uploads/c0aef251-ccf9-bcfc-6c16-eb802b6d74ef_media_.pdf\">2025-YILDA JAMIYATDA AMALGA OSHIRILGAN ISHLAR</a></big></div>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<div style=\"background: rgb(238, 238, 238); border: 1px solid rgb(204, 204, 204); padding: 5px 10px; text-align: center;\"><a href=\"http://het.uz/uploads/37b0ef32-3575-5921-6530-b43a33baef54_media_.pdf\"><big>&ldquo;Hududiy elektr tarmoqlari&rdquo; aksiyadorlik jamiyatining<br />\r\ngender jihatlarini hisobga olgan holda<br />\r\n<strong>KADRLAR SIYOSATI</strong></big></a></div>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<div style=\"background: rgb(238, 238, 238); border: 1px solid rgb(204, 204, 204); padding: 5px 10px; text-align: center;\"><big><a href=\"http://het.uz/uploads/c71bd6c9-3ce3-d3b8-c69a-ccf881da2bd4_media_.pdf\">Gender tenglik bo&lsquo;yicha 2024-yilda&nbsp;o&lsquo;tkazilgan mahalliy va xalqaro anjumanlar&nbsp;</a></big></div>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<div style=\"background: rgb(238, 238, 238); border: 1px solid rgb(204, 204, 204); padding: 5px 10px; text-align: center;\"><a href=\"http://het.uz/uploads/e2e9f666-428b-ee65-4b72-301f84bd3a15_media_.pdf\"><big>2024-yilda jamiyatda amalga oshirilgan ishlar&nbsp;</big></a></div>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<div>\r\n<div style=\"background: rgb(238, 238, 238); border: 1px solid rgb(204, 204, 204); padding: 5px 10px; text-align: center;\"><a href=\"http://het.uz/uploads/d9da2a40-a31c-4ae3-25a2-bf951ed5c878_media_.pdf\"><big>Xodimlarning kasbiy maxoratlarini oshirish uchun o&#39;tkazilgan tadbir&nbsp;</big></a></div>\r\n\r\n<p>&nbsp;</p>\r\n</div>\r\n\r\n<p><a href=\"https://youtu.be/eptNzo_pRDs\" target=\"_blank\"><img alt=\"\" src=\"http://het.uz/uploads/1b9f116c-cc41-304c-5784-d59124251b32_media_.jpg\" style=\"width: 300px; height: 168px; float: left; border-width: 10px; border-style: solid;\" /></a></p>\r\n\r\n<p><big><a href=\"https://www.youtube.com/watch?v=eptNzo_pRDs\" target=\"_blank\">Mazkur rolikda mashaqqatli va sharafli bo&lsquo;lgan energetika sohasida fidokorona mehnat qilib, yelkama-yelka faoliyat yuritayotgan &ldquo;Hududiy elektr tarmoqlari&rdquo; AJ xotin-qizlarining faoliyati haqida so&lsquo;z boradi.</a></big></p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><a href=\"https://www.youtube.com/watch?v=JOo0CK9Lg8Q\" target=\"_blank\"><img alt=\"Malika Rasulova — “Hududiy elektr tarmoqlari” AJda fidokorona mehnat qilayotgan tajribali rahbarlardan biri. U o‘z ishiga mas’uliyat bilan yondashishi hamda tirishqoqligi bilan hamkasblariga o‘rnak bo‘lib keladi. Mehnatsevarligi va hayotiy pozitsiyasi uni nafaqat jamoasi, balki keng jamoatchilik uchun ham ibratli shaxsga aylantirmoqda.  Malika Rasulova faoliyati, hayot falsafasi va muvaffaqiyat sirlari haqida batafsil O‘zbekiston telekanalining “Ayol borki..” ko‘rsatuvida tomosha qilishingiz mumkin.\" src=\"http://het.uz/uploads/8785bea0-0f72-36ef-9213-fc19825adf3e_media_.jpg\" style=\"width: 300px; height: 153px; float: left; border-width: 10px; border-style: solid;\" /></a></p>\r\n\r\n<p><big><a href=\"https://www.youtube.com/watch?v=JOo0CK9Lg8Q\" target=\"_blank\">&ldquo;О&lsquo;zbekiston&rdquo; telekanalining &ldquo;Ayol borki...&rdquo; kо&lsquo;rsatuvining navbatdagi qahramoni &ldquo;Hududiy elektr tarmoqlari&rdquo; AJ Ma&rsquo;lumotlarni qayta ishlash va dasturiy tizimlarini takomillashtirish departamenti bо&lsquo;lim boshlig&lsquo;i Malika Rasulova.</a></big></p>\r\n\r\n<p>&nbsp;</p>\r\n', NULL, 'ce5053ca-0b05-e5d1-f961-900d7b11482e_pages_2463.png', 7908, 1, 4, NULL, 1715577625, 1760975080, ''),
(2464, 1994, 'ru', 'гендерная политика', NULL, '', NULL, '2dc9ec2e-06af-4dba-bea3-44b50f5e6bc0_pages_2464.png', 4271, 1, 4, NULL, 1715577713, 1760966171, ''),
(2465, 1995, 'oz', 'KORRUPSIYA ILLATIGA QARSHI BIRGALIKDA KURASHAMIZ', 'Kuni kecha “Buxoro hududiy elektr tarmoqlari korxonasi”AJ da korrupsiyaga qarshi kurashish faoliyatini samarali tashkil etish, odob-ahloq qoidalariga rioya etilishi va kuz-qish mavsumiga tayyorgarlik ko’rish masalalari to’g’risida “Hududiy elektr tarmoqlari” AJ rahbariyati ishtirokida kengaytirilgan yig’ilish bo’lib o’tdi. ', '<p style=\"text-align: center;\"><strong><big>KORRUPSIYA ILLATIGA QARSHI BIRGALIKDA KURASHAMIZ</big></strong></p>\r\n\r\n<p><big>Kuni kecha &ldquo;Buxoro hududiy elektr tarmoqlari korxonasi&rdquo;AJ da korrupsiyaga qarshi kurashish faoliyatini samarali tashkil etish, odob-ahloq qoidalariga rioya etilishi va kuz-qish mavsumiga tayyorgarlik ko&rsquo;rish masalalari to&rsquo;g&rsquo;risida &ldquo;Hududiy elektr tarmoqlari&rdquo; AJ rahbariyati ishtirokida kengaytirilgan yig&rsquo;ilish bo&rsquo;lib o&rsquo;tdi.&nbsp;</big></p>\r\n\r\n<p><img alt=\"\" src=\"http://het.uz/uploads/2ae769fa-f7f0-08c8-1374-b5155861e8be_media_.jpg\" /></p>\r\n\r\n<p><big>&ldquo;Hududiy elektr tarmoqlari&rdquo; AJ boshqaruv raisi o&lsquo;rinbosari, Buxoro viloyati prokuraturasi mas&rsquo;ullari hamda viloyat huquqni muhofaza qiluvchi organlar vakillari qatnashgan tadbirda viloyatda iste&rsquo;molchilarni barqaror elektr energiyasi bilan ta&rsquo;minlash &nbsp;borasida olib borilayotgan ishlar va mavjud muammolar to&lsquo;g&lsquo;risida to&lsquo;xtalib o&lsquo;tildi.&nbsp;</big></p>\r\n\r\n<p><img alt=\"\" src=\"http://het.uz/uploads/55be7ae0-4f80-8d58-24f4-99681d986a91_media_.jpg\" /></p>\r\n\r\n<p><big>Uchrashuv davomida tizimda olib borilayotgan nazorat tadbirlari va amaliy harakatlarga qaramasdan tizimda korrupsion holatlarning uchrab turganligi tanqid qilinib, soha xodimlari ogohlikka chaqirildi.</big></p>\r\n\r\n<p><img alt=\"\" src=\"http://het.uz/uploads/812c8935-4788-93f2-8dcd-5cd88d0712ef_media_.jpg\" /></p>\r\n\r\n<p><big>&nbsp;Yig&rsquo;ilish davomida, &ldquo;Hududiy elektr tarmoqlari korxonasi&rdquo; AJ Korrupsiyaga qarshi kurashish va komplayens nazorat xizmati boshlig&rsquo;i joriy yilning o&rsquo;tgan davri mobaynida tizimsa sodir bo&rsquo;lgan holatlar haqida to&rsquo;xtalib o&rsquo;tib, bu borada olib borilishi lozim bo&lsquo;lgan masalalar yuzasidan to&lsquo;xtalib o&lsquo;tdi.</big></p>\r\n\r\n<p><img alt=\"\" src=\"http://het.uz/uploads/1fca93fc-6e59-10cb-1191-8e95102bb48b_media_.jpg\" /></p>\r\n\r\n<p><big>Yig&lsquo;ilishda, shuningdek, davlat organlari va tashkilotlarining faoliyati ochiqligini ta&rsquo;minlash, korxonada korrupsiyaviy omillarni yo&lsquo;qotish va bunda jamoatchilik ishtirokini kengaytirish, mansabdor shaxslarning o&lsquo;z mansab vakolatlarini suiiste&rsquo;mol qilmaslik masalalari keng muhokama qilindi.</big></p>\r\n\r\n<p><img alt=\"\" src=\"http://het.uz/uploads/ba08e675-11a5-f63f-d14c-bf9d7fff253c_media_.jpg\" /></p>\r\n\r\n<p><big>Yakunda belgilangan kun tartibidagi barcha masalalar yuzasidan bo&rsquo;lim va xizmat boshliqlarining fikri eshitilib, atroflicha muhokama qilindi va &nbsp;yig&rsquo;ilish qarori qabul &nbsp;qilindi.</big></p>\r\n\r\n<p><big><img alt=\"\" src=\"http://het.uz/uploads/b1f4e586-8c81-d3e9-8b97-f30949c60b4a_media_.jpg\" /></big></p>\r\n', '00618bd9-a650-e22f-d802-01081a11e279_lists_.jpg', '6f28a9be-2d2c-e491-62f3-0cc85b69cbb4_lists_.jpg', 1156, 1, 4, NULL, 1715688624, 1760883485, ''),
(2468, 1998, 'oz', 'Korrupsiyaning oldini olishda qonuniylik va adolatlilik prinsiplarini ta’minlash muhim masala ', 'Kecha “Hududiy elektr tarmoqlari” AJ Navoiy hududiy filialining katta majlislar zalida o‘tkazilgan korrupsiyaga qarshi kurashish faoliyatini samarali tashkil etish, odob-ahloq qoidalariga rioya etilishi, kuz-qish mavsumiga tayyorgarlik hamda hududlarda Davlat dasturlarining bajarilishi bo’yicha navbatdagi kengaytirilgan yig’ilishda iste’molchilarni barqaror elektr energiyasi bilan ta’minlash  borasida olib borilayotgan ishlar va mavjud muammolarning mohiyatiga alohida urg‘u berildi.', '<p style=\"text-align: center;\"><strong><big>Korrupsiyaning oldini olishda qonuniylik va adolatlilik prinsiplarini ta&rsquo;minlash muhim masala&nbsp;</big></strong></p>\r\n\r\n<p><big>Kecha &ldquo;Hududiy elektr tarmoqlari&rdquo; AJ Navoiy hududiy filialining katta majlislar zalida o&lsquo;tkazilgan korrupsiyaga qarshi kurashish faoliyatini samarali tashkil etish, odob-ahloq qoidalariga rioya etilishi, kuz-qish mavsumiga tayyorgarlik hamda hududlarda Davlat dasturlarining bajarilishi bo&rsquo;yicha navbatdagi kengaytirilgan yig&rsquo;ilishda iste&rsquo;molchilarni barqaror elektr energiyasi bilan ta&rsquo;minlash &nbsp;borasida olib borilayotgan ishlar va mavjud muammolarning mohiyatiga alohida urg&lsquo;u berildi.</big></p>\r\n\r\n<p><big><img alt=\"\" src=\"http://het.uz/uploads/e60a8d34-2ca6-55cd-a299-7eb1313f96c4_media_.jpg\" /></big></p>\r\n\r\n<p><big><img alt=\"\" src=\"http://het.uz/uploads/2c67f799-764b-282b-df02-957ffaead253_media_.jpg\" /></big></p>\r\n\r\n<p><big>Tadbirda ishtirok etgan &ldquo;Hududiy elektr tarmoqlari&rdquo; AJ boshqaruv raisi o&lsquo;rinbosari, viloyati prokuraturasi mas&rsquo;ullari hamda &nbsp;huquqni muhofaza qiluvchi organlar vakillari tomonidan korrupsiyaga qarshi murosasiz munosabatda bo&lsquo;lish muhitini yaratish, mehnat jamoasida korrupsiyaviy omillarni keskin kamaytirish va odob-ahloq qoidalariga rioya etilishi va manfaatlar to&lsquo;qnashuvining oldi olinishini ta&rsquo;minlash kabi jihatlarga to&lsquo;xtalib o&lsquo;tildi. Shuningdek, nazorat tadbirlari va amaliy harakatlarga qaramasdan tizimda korrupsion holatlarning uchrab turganligi tanqid qilinib, soha xodimlari ogohlikka chaqirildi.</big></p>\r\n\r\n<p><big><img alt=\"\" src=\"http://het.uz/uploads/e4e86b53-e13a-8279-4581-afd8fadc1467_media_.jpg\" /></big></p>\r\n\r\n<p><big><img alt=\"\" src=\"http://het.uz/uploads/343b09f6-e74e-cf5b-5fc2-e2690a7976d5_media_.jpg\" /></big></p>\r\n\r\n<p><big>Yig&rsquo;ilish yakunida kun tartibida baelgilangan barcha masalalar yuzasidan bo&rsquo;lim va xizmat boshliqlarining fikri eshitilib, atroflicha muhokama qilindi va &nbsp;yig&rsquo;ilish qarori qabul &nbsp;qilindi.</big></p>\r\n\r\n<p><big><img alt=\"\" src=\"http://het.uz/uploads/f38149f6-6cf3-da81-8a8c-d71c9656c1fb_media_.jpg\" /></big></p>\r\n', '482e1b7c-79bf-34c8-dfc2-6c2bad61bb81_lists_.jpg', 'f2eb2d72-7da2-4507-a3bc-7db8e3e39a7a_lists_.jpg', 1237, 1, 4, NULL, 1715777670, 1760923091, ''),
(2469, 1999, 'oz', '“Ayollarning energetika sohasidagi o‘rni: zamonaviy tendensiyalar” mavzuida an’anaviy forum o‘z ishini boshladi', '“Ayollarning energetika sohasidagi o‘rni: zamonaviy tendensiyalar” mavzuida an’anaviy forum o‘z ishini boshladi\r\nBugun 17 may kuni “Hududiy elektr tarmoqlari“ AJda Oila va xotin-qizlar qo‘mitasi hamda Osiyo tarraqiyot banki hamkorligida “Ayollarning energetika sohasidagi o‘rni: zamonaviy tendensiyalar” mavzuida an’anaviy forum o‘z ishini boshladi.', '<p style=\"text-align: center;\"><big><strong>&ldquo;Ayollarning energetika sohasidagi o&lsquo;rni: zamonaviy tendensiyalar&rdquo; mavzuida an&rsquo;anaviy forum o&lsquo;z ishini boshladi</strong></big></p>\r\n\r\n<p style=\"text-align: justify;\"><big>Bugun 17 may kuni &ldquo;Hududiy elektr tarmoqlari&ldquo; AJda Oila va xotin-qizlar qo&lsquo;mitasi hamda Osiyo tarraqiyot banki hamkorligida &ldquo;Ayollarning energetika sohasidagi o&lsquo;rni: zamonaviy tendensiyalar&rdquo; mavzuida an&rsquo;anaviy forum o&lsquo;z ishini boshladi.</big></p>\r\n\r\n<p style=\"text-align: justify;\"><big><img alt=\"\" src=\"http://het.uz/uploads/99034a3d-2286-3ee5-4828-ce80812e1f16_media_.jpg\" /><br />\r\nTadbirda Osiyo tarraqiyot banki, O&lsquo;zbekiston Respublikasi Oila va xotin-qizlar Qo&lsquo;mitasi, O&lsquo;zbekiston Respublikasi Energetika vazirligi, neft-gaz va geologiya xodimlari kasaba uyushmasi Respublika Kengashi vakillari, shuningdek, &ldquo;Hududiy elektr tarmoqlari&rdquo; AJ ijro apparati xodimalari va filliallardagi xotin-qizlar masalalari bo&lsquo;yicha boshlang&lsquo;ich tashkiloti raislari/gender masalalari bo&lsquo;yicha Maslahat kengashi raisi o&lsquo;rinbosarlari ishtirok etishdi.</big></p>\r\n\r\n<p style=\"text-align: justify;\"><big><img alt=\"\" src=\"http://het.uz/uploads/cbe6e4bb-538a-75d8-9ef6-7a0162bb286b_media_.jpg\" /><br />\r\nO&lsquo;zbekiston Respublikasining 2019 yil 2 sentyabrdagi &ldquo;Xotin-qizlar va erkaklar uchun teng huquq hamda imkoniyatlar kafolatlari to&lsquo;g&lsquo;risida&rdquo;gi Qonuni tasdiqangan bo&lsquo;lib, mazkur qonunning 13-moddasi hamda O&lsquo;zbekiston Respublikasi Oila va xotin-qizlar davlat qo&lsquo;mitasining tavsiyasiga ko&lsquo;ra, &ldquo;Hududiy elektr tarmoqlari&rdquo; AJ va uning tarkibiy korxonalarida Xotin-qizlar va erkaklar uchun teng huquqlar hamda imkoniyatlarni ta&rsquo;minlash masalalari bo&lsquo;yicha maslahat kengashlari tuzildi. Uning asosiy vazifalari etib huquq va erkinlikning barcha jabhasida xotin-qizlar va erkaklar o&lsquo;rtasida tenglik imkoniyatlarini yaratish, xotin-qizlar manfaatlarini ta&rsquo;minlash ishlarini nazorat qilish, mavjud muammolarni bartaraf etish yuzasidan tegishli chora-tadbirlarni ishlab chiqib, ularni amalga oshirish bo&lsquo;yicha ishlarni muvofiqlashtirish masalalari belgilangan.</big></p>\r\n\r\n<p style=\"text-align: justify;\"><big><img alt=\"\" src=\"http://het.uz/uploads/3dfde51f-7899-915c-7748-29c2fb35bf1c_media_.jpg\" /><br />\r\n&ldquo;Hududiy elektr tarmoqlari&rdquo; AJda bugungi kunda Jamiyat va uning tarkibidagi 15 ta hududiy filial hamda 2 ta hududiy korxonalarida jami 26 157 xodim faoliyat yuritmoqda. Shulardan 2 650 nafarini ayollar tashkil qiladi.<br />\r\n2023 yil davomida &ldquo;Hududiy elektr tarmoqlari&rdquo; AJ hamda uning tarkibiy korxonalaridagi xotin-qizlar masalalari bo&lsquo;yicha maslahat kengashlari tomonidan gender muvozanatni ta&rsquo;minlash, tizim ayollarini har tomonlama qo&lsquo;llab-quvvatlash, jamoada hamjihatlik muhitini shakllantirish, yetakchi ayollar safini kengaytirish bo&lsquo;yicha samarali ishlar amalga oshirildi. Shular bilan birga, Jamiyat kasaba uyushmasi hamkorligida ijtimoiy himoya, sport-sog&lsquo;lomlashtirish va madaniy-ma&rsquo;rifiy yo&lsquo;nalishlarga ham alohida e&rsquo;tibor qaratildi.</big></p>\r\n\r\n<p style=\"text-align: justify;\"><big><img alt=\"\" src=\"http://het.uz/uploads/73e52f05-25c9-d017-516f-a0c6628f4af1_media_.jpg\" /><br />\r\nShu bilan qatorda &ldquo;Zo&lsquo;ravonlikka qarshi 16 kun&rdquo; mavzuidagi o&lsquo;quv seminarlar, &ldquo;Huquqiy bilimlarni oshirish kuni&rdquo; loyihasi doirasida adliya boshqarmalari vakillari xamkorligida uchrashuvlar tashkil etildi. Bundan tashqari, jamoada xotin-qizlarning jismoniy foalligini oshirish, sog&lsquo;lom turmush tarzini keng tatbiq etish, sportga bo&lsquo;lgan qiziqishlarini yanada mustahkamlash maqsadida ayol ishchi-xodimlar o&lsquo;rtasida sportning voleybol, shashka, shaxmat, stol-tennisi kabi turlari bo&lsquo;yicha musobaqalar o&lsquo;tkazildi.</big></p>\r\n\r\n<p style=\"text-align: justify;\"><big><img alt=\"\" src=\"http://het.uz/uploads/57cc69f6-73e8-2094-1eac-376c4f6b2e16_media_.jpg\" /><br />\r\nXotin-qizlar salomatligini asrash, onalik va bolalikni muhofaza qilish, milliy genofondni yaxshilash maqsadida, tarkibiy korxonalar ayol xodimlarini tibbiy ko&lsquo;rikdan o&lsquo;tkazish bo&lsquo;yicha amaliy ishlar olib borildi.</big></p>\r\n\r\n<p style=\"text-align: justify;\"><big><img alt=\"\" src=\"http://het.uz/uploads/aea9caf2-6067-814b-6a95-1f4a983eedfa_media_.jpg\" /><br />\r\nBundan tashqari, Qo&lsquo;mitaning respublika bo&lsquo;yicha &ldquo;Xon atlas&rdquo; festivalini o&lsquo;tkazish bo&lsquo;yicha tashabbusi &ldquo;Hududiy elektr tarmoqlari&rdquo; AJ xotin-qizlari tomonidan qo&lsquo;llab-quvvatlanib, ushbu tadbir ko&lsquo;tarinki kayfiyatda qarshi olindi.</big></p>\r\n\r\n<p style=\"text-align: justify;\"><big><img alt=\"\" src=\"http://het.uz/uploads/7f96bc7d-2610-ced9-d18f-b7927d60d83f_media_.jpg\" /><br />\r\nShuningdek, ayol xodimlarning ishdan bo&lsquo;sh vaqtlarini maroqli o&lsquo;tkazishlari hamda sog&lsquo;lom turmush tarzini targ&lsquo;ib qilish maqsadida dam olish maskanlari, yurtimizning qadimiy shaharlari va ziyoratgohlariga sayohatlar tashkil etildi.</big></p>\r\n\r\n<p style=\"text-align: justify;\"><big><img alt=\"\" src=\"http://het.uz/uploads/4677e8ba-e78d-4c2e-5855-b5220bf41fc5_media_.jpg\" /></big></p>\r\n\r\n<p style=\"text-align: justify;\"><big>Bunday sayohatlarda bir dasturxon atrofida hamma bir jamoa bo&lsquo;lib, ahil-inoq dam olib kelishi jamiyat xodimlari o&lsquo;rtasida sog&lsquo;lom muhitning yanada mustahkamlanishiga xizmat qiladi, albatta.</big></p>\r\n\r\n<p style=\"text-align: justify;\"><big><img alt=\"\" src=\"http://het.uz/uploads/87da3b14-7cfb-9877-ab80-571d1b836c68_media_.jpg\" /><br />\r\nJamiyatda xotin-qizlar ta&rsquo;limini qo&lsquo;llab-quvvatlash bo&lsquo;yicha ham samarali ishlar tashkil etilgan. Rahbariyat tavsiyasiga ko&lsquo;ra, jami 100 ga yaqin xodim, shulardan 40 nafari ayollar oliy ta&rsquo;lim muassasalariga o&lsquo;qishga qabul qilindilar.</big></p>\r\n', '2635a397-6cb1-e866-54c3-73f98e0d9472_lists_.jpg', 'fa37894b-8c6c-c2f3-749f-e4593c36e2f5_lists_.jpg', 1466, 1, 4, NULL, 1715932557, 1760843215, ''),
(2470, 2000, 'oz', 'Joriy yil 21-24 may kunlari Rossiya Federatsiyasining Samara shahrida an’anaviy ilmiy-amaliy konferensiya о‘tkazilmoqda', 'Joriy yil kunlari Rossiya Federatsiyasining Samara shahrida an’anaviy ilmiy-amaliy konferensiya о‘tkazilmoqda', '<p style=\"text-align: center;\"><strong><big>Joriy yil 21-24 may kunlari Rossiya Federatsiyasining Samara shahrida &quot;Rossiya va О&lsquo;zbekiston energetik kompleksi uchun Elektroshit Samara tomonidan ishlab chiqarilayotgan uskunalarning ishonchliligini oshirish&quot; mavzuida an&rsquo;anaviy ilmiy-amaliy konferensiya о&lsquo;tkazilishi rejalashtirilgan.</big>&nbsp;</strong></p>\r\n\r\n<p style=\"text-align: center;\"><strong><img alt=\"\" src=\"http://het.uz/uploads/cd27c820-24ca-ce8a-3072-da8b9c55bbaa_media_.jpg\" /></strong></p>\r\n\r\n<p><strong>Ayni paytda, &quot;Hududiy elektr tarmoqlari&quot; AJ boshqaruv raisi o&lsquo;rinbosari D. Nosirov, &quot;Farg&lsquo;ona hududiy elektr tarmoqlari korxonasi&quot; AJ bosh direktori A. Saydaliyev hamda Energetika vazirligi tasarrufidagi qator korxonalar rahbarlaridan tashkil topgan delegatsiya a&rsquo;zolari &quot;Elektr taqsimlash tarmoqlarini rivojlantirish va ishonchliligini oshirish&quot; mavzuida boshlangan konferensiyada ishtirok etmoqdalar. Bu yerda energetika sohasidagi modernizatsiya jarayonlarida bugungi kundagi eng ilg&lsquo;or, sifatli va albatta yuqori samaradorlikka ega elektr qurilmalarini joriy etish hamda foydalanish kabi mavzular muhokama etilishi kutilmoqda.&nbsp;</strong></p>\r\n\r\n<p><img alt=\"\" src=\"http://het.uz/uploads/ac28c07b-a6a0-1d00-8ac4-06463807bcce_media_.jpg\" /><img alt=\"\" src=\"http://het.uz/uploads/48e24b64-3c4a-5f9a-0690-929a8b989c64_media_.jpg\" /><img alt=\"\" src=\"http://het.uz/uploads/d6e657d8-15bb-966f-16d1-37e807198b55_media_.jpg\" /><img alt=\"\" src=\"http://het.uz/uploads/2d0cbf03-bb7b-2f68-9517-c548ebb47e0f_media_.jpg\" /><img alt=\"\" src=\"http://het.uz/uploads/bf3b5ea4-27be-1d21-ab81-7338eaf5ce02_media_.jpg\" /><img alt=\"\" src=\"http://het.uz/uploads/0d82e5bc-9e37-a29c-b3c5-238426a38ecd_media_.jpg\" /><img alt=\"\" src=\"http://het.uz/uploads/94301fce-2b71-8362-26b9-55e445f0bf2f_media_.jpg\" /></p>\r\n\r\n<p><strong>Ta&rsquo;kidlash joizki, mazkur konferensiyada 50 dan ortiq Rossiya Federatsiyasining yetakchi kompaniyalari hamda 300 nafardan ortiq ekspertlar qatnashmoqda.</strong></p>\r\n', '35167d70-ead0-64dd-1f3a-c62539787b96_lists_.jpg', '26b3a2da-1654-cb1d-37cd-da4e0bc5fb5c_lists_.jpg', 1030, 1, 4, NULL, 1716469429, 1760938169, ''),
(2471, 2001, 'oz', 'Aholi uchun Elektr energiyasining namunaviy shartnomasi', 'Shartnoma', '<div style=\"background:#eeeeee;border:1px solid #cccccc;padding:5px 10px;\"><big><a href=\"http://het.uz/uploads/3faed377-7ce8-a9b5-df22-371f7da6e842_media_.pdf\"><strong>Aholi uchun Elektr energiyasining namunaviy shartnomasi</strong></a></big></div>\r\n\r\n<p>&nbsp;</p>\r\n', '', '', 1363, 1, 4, NULL, 1716470339, 1760942217, 'http://het.uz/uploads/3faed377-7ce8-a9b5-df22-371f7da6e842_media_.pdf'),
(2472, 2002, 'oz', '“Hududiy elektr tarmoqlari” AJ Surxondaryo hududiy filiali tomonidan viloyat iste’molchilarini barqaror elektr energiyasi bilan ta’minlash  maqsadida  quvvati 10 000 kVA bo’lgan kuch transformatori yetkazib berildi', '“Hududiy elektr tarmoqlari” AJ Surxondaryo hududiy filiali tomonidan viloyat iste’molchilarini barqaror elektr energiyasi bilan ta’minlash  maqsadida  quvvati 10 000 kVA bo’lgan kuch transformatori yetkazib berildi', '<p style=\"text-align: center;\"><big><strong>&ldquo;Hududiy elektr tarmoqlari&rdquo; AJ Surxondaryo hududiy filiali tomonidan viloyat iste&rsquo;molchilarini barqaror elektr energiyasi bilan ta&rsquo;minlash &nbsp;maqsadida &nbsp;quvvati 10 000 kVA bo&rsquo;lgan kuch transformatori yetkazib berilib, mazkur quvvatdagi kuch transformatorini Qumqo&rsquo;rg&rsquo;on tuman elektr ta&rsquo;minoti tasarrufidagi 35/10 kV li &ldquo;Irmoq&rdquo; podstansiyasida o&rsquo;rnatilishi belgilangan.&nbsp;</strong></big></p>\r\n\r\n<p><big><strong><img alt=\"\" src=\"http://het.uz/uploads/4101f126-2d95-7c88-d1f0-d9eae4e4afc7_media_.jpg\" /><img alt=\"\" src=\"http://het.uz/uploads/973ed8ab-bab0-63e0-9f5f-d55b592a319c_media_.jpg\" /></strong></big></p>\r\n\r\n<p><big><strong><img alt=\"\" src=\"http://het.uz/uploads/1bc50257-084e-a74d-ec1c-6a04fa9a3eda_media_.jpg\" /></strong></big></p>\r\n\r\n<p><strong>Modernizatsiya va yangilash ishlari doirasida podstansiyadagi 6 300 kVA bo&rsquo;lgan kuch transformatori olib kelingan yangi 10 000 kVAli transformatorga almashtirilmoqda.&nbsp;</strong></p>\r\n\r\n<p><strong><img alt=\"\" src=\"http://het.uz/uploads/7d106e6b-1adb-b40f-4740-3abef560ef09_media_.jpg\" /></strong></p>\r\n\r\n<p><strong><img alt=\"\" src=\"http://het.uz/uploads/d3d1e18f-11f1-8b8c-0e14-a2ee1dd7054e_media_.jpg\" /></strong></p>\r\n\r\n<p><strong>&ldquo;Hududiy elektr tarmoqlari&rdquo; AJ Surxondaryo hududiy filiali matbuot xizmati</strong></p>\r\n', '21b3833d-4565-7889-13df-ea9aef5f97f4_lists_.jpg', '9bc9cd73-47c1-dab4-3e1e-913969e6e644_lists_.jpg', 1388, 1, 4, NULL, 1716809820, 1760970184, '');
INSERT INTO `lists_lang` (`id`, `main_id`, `lang`, `title`, `anons`, `body`, `anonsImage`, `bodyImage`, `views`, `enabled`, `creator_id`, `modifier_id`, `created_at`, `updated_at`, `pdf`) VALUES
(2473, 2003, 'oz', '“HAMDO’STLIK” MAHALLASIGA YANGI TRANSFORMATOR PUNKTLARI O’RNATILDI', '“HAMDO’STLIK” MAHALLASIGA YANGI TRANSFORMATOR PUNKTLARI O’RNATILDI\r\n', '<p style=\"text-align: center;\"><big><strong>&ldquo;HAMDO&rsquo;STLIK&rdquo; MAHALLASIGA YANGI TRANSFORMATOR PUNKTLARI O&rsquo;RNATILDI</strong></big></p>\r\n\r\n<p><strong>Andijon shahrida joylashgan bir nechta mahallani elektr energiyasi sifatini yaxshilash maqsadida hozirda &ldquo;Hududiy elektr tarmoqlari&rdquo; AJ Andijon hududiy filiali &nbsp;xodimlari tomonidan manzilli dasturlar doirasida tizimli ishlar amalga oshirilmoqda.&nbsp;</strong></p>\r\n\r\n<p><strong><img alt=\"\" src=\"http://het.uz/uploads/39562a19-25a7-dbc5-ecde-7dd7c4903c44_media_.jpg\" /><img alt=\"\" src=\"http://het.uz/uploads/db4ee4ca-1818-7b36-1d95-e0541e94f543_media_.jpg\" /></strong></p>\r\n\r\n<p><strong>Hozirda shahar markaziy mahallalaridan biri xisoblangan &nbsp; &ldquo;Hamdo&#39;stlik&rdquo; MFY hududida 2 dona quvvati 400 kVAdan bo&#39;lgan transformator punkti o&#39;rnatilib, ishga tushirilmoqda.&nbsp;</strong></p>\r\n\r\n<p><strong><img alt=\"\" src=\"http://het.uz/uploads/223a910b-9af7-df57-f36b-19580bb8bb3a_media_.jpg\" /></strong></p>\r\n\r\n<p><strong>Shuningdek, ushbu hududga yangi temir- beton tayanchlar o&rsquo;rnatilib 4. 5 km uzunlikdagi 10/0.4 kV havo elektr uzatish tarmoqlari tortildi.&nbsp;</strong></p>\r\n\r\n<p><strong><img alt=\"\" src=\"http://het.uz/uploads/b4595909-8d4e-2b1c-6052-b256a339d574_media_.jpg\" /></strong></p>\r\n\r\n<p><strong>Ushbu rekonstruksiya va modernizatsiya ishlari yakunlangach 600 dan ortiq aholi - xonadonlarining elektr ta&#39;minoti yaxshilanishiga erishiladi.</strong></p>\r\n\r\n<p><br />\r\n<strong>&ldquo;Hududiy elektr tarmoqlari&rdquo; AJ Andijon hududiy filiali matbuot xizmati</strong></p>\r\n', '0d54a4e7-4a38-b0ff-2439-1a7272b371fc_lists_.jpg', 'f8811bc0-8a60-86e6-add7-fbf0baf9c6f7_lists_.jpg', 1064, 1, 4, NULL, 1717061927, 1760898832, ''),
(2474, 2004, 'oz', 'BEKTEMIRDA REYD TADBIRLARI DAVOM ETMOQDA', '   ', '<p style=\"text-align: justify;\"><em><strong>&nbsp; Bugungi kunda, &laquo;Toshkent shahar elektr tarmoqlari&raquo; MCHJ tasarrufidagi barcha tuman elektr ta&rsquo;minoti korxonalari tomonidan joylarda kripto-aktivlar aylanmasi sohasidagi &laquo;Mayning&raquo; ferma faoliyati bilan shug`ullanuvchi sub`yektlar hamda ulgurji iste`molchilar tomonidan elektr energiyasidan noqonuniy foydalanish holatlarini barvaqt aniqlash va oldini olish maqsadida, hududlarda reyd tadbirlari bo&rsquo;lib o&rsquo;tmoqda.</strong></em></p>\r\n\r\n<p><em><strong><img alt=\"\" src=\"http://het.uz/uploads/a034c9b2-812e-94f9-4db5-24912441111a_media_.jpg\" /></strong></em></p>\r\n\r\n<p style=\"text-align: justify;\"><em><strong>&nbsp; &nbsp;Jumladan, Jamiyat Bosh direktori o`rinbosari A.Ashrafxanov, Korrupsiyaga qarshi kurashish va kompleans nazorat bo`limi boshlig`i O.Yaxshiyev hamda Bektemir tuman elektr ta&rsquo;minoti korxonasi mas`ullari tomonidan tumanning &laquo;Abay&raquo; mahalla fuqarolar yig&rsquo;ini hududlaridagi iste`molchilarning elektr hisoblagichlari nazoratdan o`tkazildi.&nbsp;</strong></em></p>\r\n\r\n<p><em><strong><img alt=\"\" src=\"http://het.uz/uploads/9cbb82c6-86f8-6c3e-8e41-f4c465e8ddfa_media_.jpg\" /></strong></em></p>\r\n\r\n<p style=\"text-align: justify;\"><em><strong>&nbsp; &nbsp;Mazkur tadbir davomida elektr energiyasidan noqonuniy foydalangan iste`molchilarga nisbatan mutaxassislar tomonidan aniqlangan qoidabuzarlik holatlari yuzasidan tegishli tartibda dalolatnomalar rasmiylashtirilib, qat&rsquo;iy choralar ko&lsquo;rilishi haqida tushuntirish ishlari olib borildi.</strong></em></p>\r\n\r\n<p><em><strong><img alt=\"\" src=\"http://het.uz/uploads/2c3ce039-5f6f-852f-af51-dcb0f1073999_media_.jpg\" /></strong></em></p>\r\n\r\n<p style=\"text-align: justify;\"><strong>&nbsp;<ins>Hurmatli elektr energiyasi iste`molchilari,</ins> elektr va gaz tarmoqlariga tijorat maqsadlarida oʻzboshimchalik bilan ulanish yoxud hisobga olish asboblariga tashqaridan aralashish yoʻli bilan talon-toroj qilish holatlari uchun qonunchilikda belgilangan qatʼiy choralar koʻrilishini unutmang!</strong></p>\r\n\r\n<p style=\"text-align: justify;\"><br />\r\n<strong><big>&nbsp;&laquo;Toshkent shahar elektr tarmoqlari&raquo; MCHJ&nbsp;</big></strong></p>\r\n', 'e452f801-1638-19fd-201c-ce2e477204a6_lists_.jpg', '8e52cf24-028f-add5-ef7c-c9bb593b1f23_lists_.jpg', 1108, 1, 4, NULL, 1717063695, 1760882919, ''),
(2475, 2005, 'oz', 'Buxoro viloyatiga yana ikki dona yuqori quvvatdagi kuch transformatorlari olib kelindi', '  Buxoro viloyati aholisi hamda tadbirkorlarni barqaror elektr energiyasi bilan ta’minlash maqsadida Davlat dasturlari asosida qator loyihalar amalga oshirilib kelinmoqda.\r\n\r\n', '<p style=\"text-align: justify;\"><big>Buxoro viloyati aholisi hamda tadbirkorlarni barqaror elektr energiyasi bilan ta&rsquo;minlash maqsadida Davlat dasturlari asosida qator loyihalar amalga oshirilib kelinmoqda</big></p>\r\n\r\n<p><img alt=\"\" src=\"http://het.uz/uploads/5d92923b-c8b3-5c25-9886-5637e2a23fb1_media_.jpg\" /></p>\r\n\r\n<p><img alt=\"\" src=\"http://het.uz/uploads/a9479500-1b17-ad7c-a754-73da2e248e95_media_.jpg\" /></p>\r\n\r\n<p style=\"text-align: justify;\"><big>Past kuchlanishli elektr uzatish tarmoqlarini yangilash va modernizatsiya qilish bilan bir qatorda hududlardagi podstansiyalarning quvvatini oshirish ishlari ham bosqichma-bosqich olib borilmoqda.</big></p>\r\n\r\n<p><strong><img alt=\"\" src=\"http://het.uz/uploads/f2d48c36-fffc-3d22-96aa-a9bfd0b7bbf7_media_.jpg\" /></strong></p>\r\n\r\n<p style=\"text-align: justify;\"><big>Anashunday yangilanishlardan yana biri viloyatning G&rsquo;ijduvon tumanida amalga oshirilmoqda. Loyiha asosida yuqori kuchlanishdagi &ldquo;G&rsquo;ijduvon&rdquo; 110/35/10 podstansiyasining quvvatini oshirish uchun 2 dona 40&nbsp;000 kVAli kuch transformatorlari olib kelindi.</big></p>\r\n\r\n<p><strong><img alt=\"\" src=\"http://het.uz/uploads/4f48e736-ff24-dd8e-2157-420c33ff6635_media_.jpg\" /></strong></p>\r\n\r\n<p style=\"text-align: justify;\"><big>Mazkur quvvatdagi transformatorlar o&rsquo;rnatilishi G&rsquo;ijduvon tumanidagi 50&nbsp;000ga yaqin elektr energiyasi iste&rsquo;molchilarining elektr energiyasi ta&rsquo;minotini yanada yaxshilash imkonini beradi.</big></p>\r\n\r\n<p><strong><img alt=\"\" src=\"http://het.uz/uploads/0897db6d-962f-8f0d-ae91-d0cc4f6031c1_media_.jpg\" /></strong></p>\r\n\r\n<p style=\"text-align: justify;\"><big>Ushbu kuch transformatorlarining ishga tushurilishi natijasida podstansiyaning quvvati 3 barobarga ortadi. Shu bilan bir qatorda qo&rsquo;shimcha quvvat ham yaratiladi.</big><br />\r\n&nbsp;</p>\r\n\r\n<p style=\"text-align: right;\"><strong><big>&ldquo;Buxoro HETK&rdquo; AJ Matbuot xizmati</big></strong></p>\r\n\r\n<p>&nbsp;</p>\r\n', '38582398-0d1f-f02d-2927-0696eef142f7_lists_.jpg', '27105a2b-3176-d285-06bc-a453d578322d_lists_.jpg', 1189, 1, 4, NULL, 1717069907, 1760927255, ''),
(2476, 2006, 'oz', 'KORRUPSIYANING OLDINI OLISH VA UNGA QARSHI KURASHISH ', 'Kuni kecha \"Hududiy elektr tarmoqlari” AJ Qoraqalpog‘iston hududiy filiali va uning tarkibiga kiruvchi tuman (shahar) korxonalar xodimlari ishtirokida “Korrupsiyaga qarshi kurashish faoliyatini samarali tashkil etish, odob-ahloq qoidalariga rioya etilishi va kuz-qish mavsumiga tayyorgarlik ko‘rish masalalari to‘g‘risida”  kengaytirilgan yig’ilish bo’lib o’tdi.', '<p style=\"text-align: center;\"><big><img alt=\"\" src=\"http://het.uz/uploads/7b277b94-ff31-6f15-a967-c4052da9f148_media_.jpg\" /></big></p>\r\n\r\n<p style=\"text-align: justify;\"><big>Kuni kecha &quot;Hududiy elektr tarmoqlari&rdquo; AJ Qoraqalpog&lsquo;iston hududiy filiali va uning tarkibiga kiruvchi tuman (shahar) korxonalar xodimlari ishtirokida &ldquo;Korrupsiyaga qarshi kurashish faoliyatini samarali tashkil etish, odob-ahloq qoidalariga rioya etilishi va kuz-qish mavsumiga tayyorgarlik ko&lsquo;rish masalalari to&lsquo;g&lsquo;risida&rdquo;&nbsp; kengaytirilgan yig&rsquo;ilish bo&rsquo;lib o&rsquo;tdi.</big></p>\r\n\r\n<p style=\"text-align: justify;\"><big><img alt=\"\" src=\"http://het.uz/uploads/36848534-a0a9-8c4d-1d19-56c99e2d6a84_media_.jpg\" /></big></p>\r\n\r\n<p style=\"text-align: justify;\"><img alt=\"\" src=\"http://het.uz/uploads/599e04f9-10b7-f264-a1f6-38cdb5616a08_media_.jpg\" /></p>\r\n\r\n<p style=\"text-align: justify;\"><big>&laquo;Hududiy elektr tarmoqlari&raquo; AJ boshqaruv raisi o&lsquo;rinbosari O. Alimardonov, viloyat huquqni muhofaza qiluvchi organlar mas&#39;ulllari qatnashgan tadbirda yurtimizda korrupsiyaga qarshi kurashish borasida olib borilayotgan ishlar, mazkur illatni bartaraf etishning qonuniy asoslariga batafsil to&lsquo;xtalib o&lsquo;tildi.</big></p>\r\n\r\n<p style=\"text-align: justify;\"><big><img alt=\"\" src=\"http://het.uz/uploads/9e9aa95e-45da-b569-fa45-d707e991497f_media_.jpg\" /></big></p>\r\n\r\n<p style=\"text-align: justify;\"><big><img alt=\"\" src=\"http://het.uz/uploads/054fd9a9-ff8e-5ffc-ae66-c840d69a7ebb_media_.jpg\" /></big></p>\r\n\r\n<p style=\"text-align: justify;\"><big>Yig&rsquo;ilish davomida, &ldquo;Hududiy elektr tarmoqlari korxonasi&rdquo; AJ Korrupsiyaga qarshi kurashish va komplayens nazorat xizmati boshlig&rsquo;i joriy yilning o&rsquo;tgan davri mobaynida tizimsa sodir bo&rsquo;lgan holatlar haqida to&rsquo;xtalib o&rsquo;tib, korrupsiya holatlarini oldini olish, korrupsion havf-xatarlarni qisqartirish hamda hodimlar о&lsquo;rtasida korrupsiyaga qarshi murossiz kurashish, odob-axloq qoidaliriga va ichki mehnat tartibiga amal qilish yuzasidan to&lsquo;xtalib o&lsquo;tdi.</big></p>\r\n\r\n<p style=\"text-align: justify;\"><big><img alt=\"\" src=\"http://het.uz/uploads/9c50cebc-6e53-4c27-444a-1d8ecb3e6204_media_.jpg\" /></big></p>\r\n\r\n<p style=\"text-align: justify;\"><img alt=\"\" src=\"http://het.uz/uploads/81253729-e86f-411a-bebb-cfe79e6e9859_media_.jpg\" /></p>\r\n\r\n<p style=\"text-align: justify;\">&nbsp;</p>\r\n', '11e5a40b-55d9-4a52-e00f-eb11bb220688_lists_.jpg', '45405261-8b11-f046-b612-23af677740f5_lists_.jpg', 1187, 1, 4, NULL, 1717138427, 1760915501, ''),
(2477, 2007, 'oz', 'TOSHKENT VILOYATIDAGI  PODSTANSIYALARNING QUVVATI OSHIRILMOQDA', 'Toshkent viloyati aholisini sizfatli elektr energiyasi bilan ta’minlash maqsadida “Hududiy elektr tarmoqlari” AJ Toshkent hududiy filiali tomonidan hududlarda podstansiyalarning quvvatini oshirish ishlari bosqichma-bosqich amalga oshirilmoqda.', '<p style=\"text-align: justify;\"><big>Toshkent viloyati aholisini sizfatli elektr energiyasi bilan ta&rsquo;minlash maqsadida &ldquo;Hududiy elektr tarmoqlari&rdquo; AJ Toshkent hududiy filiali tomonidan hududlarda podstansiyalarning quvvatini oshirish ishlari bosqichma-bosqich amalga oshirilmoqda.</big></p>\r\n\r\n<p style=\"text-align: justify;\"><big><img alt=\"\" src=\"http://het.uz/uploads/0f718704-af5e-663d-273e-d8c8ef18fae3_media_.jpg\" /></big></p>\r\n\r\n<p style=\"text-align: justify;\"><big>Xususan, Zangiota tumanida joylashgan &ldquo;Go&rsquo;sht kombinati&rdquo; 110/35/6 kV podstansiyasidagi mavjud quvvati 25000 kVA bo&rsquo;lgan ikkita kuch transformatorining har biri quvvati 40000 kVA bo&rsquo;lgan kuch transformatoriga almashtirildi.</big></p>\r\n\r\n<p style=\"text-align: justify;\"><big><img alt=\"\" src=\"http://het.uz/uploads/04b559f1-6423-a9c0-f14d-fe2f53dcaee6_media_.jpg\" /></big></p>\r\n\r\n<p style=\"text-align: justify;\"><big><img alt=\"\" src=\"http://het.uz/uploads/bdeaf4a6-f77a-20b7-ca91-f697b9fd5d4d_media_.jpg\" /></big></p>\r\n\r\n<p style=\"text-align: justify;\"><big>Natijada ushbu podstansiyaning quvvati 30 000 kVA ga oshirilib, tumandagi&nbsp; 6 mingdan ortiq aholi xonadonlari hamda 350 ga yaqin yuridik iste&rsquo;molchining elektr energiyasi ta&#39;minoti sifati yaxshilanishiga erishildi.</big></p>\r\n\r\n<p style=\"text-align: justify;\"><big><img alt=\"\" src=\"http://het.uz/uploads/25649f8b-ab28-bc77-21f1-4c2259abd951_media_.jpg\" /></big></p>\r\n\r\n<p style=\"text-align: justify;\"><big>Xuddi shu kabi ishlar Toshkent tumanida joylashgan &ldquo;Kensoy&rdquo; 110/35/10 kV podstansiyasida ham&nbsp; olib borilganini qayd etish joiz. Shu orqali mazkur hududdagi 15 mingdan ortiq aholi xonadoni hamda 150 ga yaqin yuridik iste&rsquo;molchining elektr energiyasi barqarorligi ta&#39;minlandi.</big></p>\r\n\r\n<p style=\"text-align: justify;\"><big><img alt=\"\" src=\"http://het.uz/uploads/ef3be86e-27f2-1efb-c0f2-33c93f92be7b_media_.jpg\" /></big></p>\r\n\r\n<p style=\"text-align: justify;\"><big><img alt=\"\" src=\"http://het.uz/uploads/ce4dff0e-b8c6-5a0d-1973-2b5dd054cae2_media_.jpg\" /></big></p>\r\n\r\n<p style=\"text-align: justify;\"><big>Jami amalga oshirilgan ishlar natijasida 50000 kV∙soat qo&#39;shimcha quvvat oshishiga erishildi.</big></p>\r\n\r\n<p style=\"text-align: justify;\"><big><img alt=\"\" src=\"http://het.uz/uploads/e06f8dea-7ded-b22f-f78d-5199de46491f_media_.jpg\" /></big></p>\r\n\r\n<p style=\"text-align: justify;\"><big>Ayni kunda, Toshkent viloyati Bo&rsquo;stonliq tumani hududlarini elektr energiyasi bilan ta`minlovchi 110/35/6 kVli &laquo;Chorvoq&raquo; podstansiyasida mavjud 16000 kVAli kuch transformatorini 40000 kVA bo&#39;lgan yuqori quvvatlisiga almashtirish ishlari o&lsquo;z yakuniga etkazlmoqda.</big></p>\r\n\r\n<p style=\"text-align: justify;\"><big><img alt=\"\" src=\"http://het.uz/uploads/88410cfe-0f78-be55-e33f-42fdc03d1074_media_.jpg\" /></big></p>\r\n\r\n<p style=\"text-align: justify;\"><big>Mazkur jarayon murakkabligi hamda ma&#39;lum vaqt olishini hisobga olgan holda, ishchi-xodimlar tomonidan belgilangan vazifalar izchillik bilan olib borilmoqda.</big></p>\r\n\r\n<p style=\"text-align: justify;\"><big><img alt=\"\" src=\"http://het.uz/uploads/7f8bd91e-cfcf-6f90-26af-a3d6b17f4339_media_.jpg\" /></big></p>\r\n', '667525b3-a029-8f2a-f02a-5d0448725b50_lists_.jpg', '16fed887-3bd4-7fd8-d37f-e6364345c723_lists_.jpg', 1123, 1, 4, NULL, 1717561698, 1760949068, ''),
(2478, 2008, 'oz', '“ENERGETIK” YOZGI BOLALAR OROMGOHIGA BOLAJONLAR KUZATILDI', 'Bolalar uchun yozgi ta’tilni maroqli, mazmunli tashkil etish muhim ahamiyatga ega.', '<p style=\"text-align: justify;\"><img alt=\"\" src=\"http://het.uz/uploads/a54a5702-94b4-896f-2da2-14a52238c48c_media_.jpg\" /></p>\r\n\r\n<p style=\"text-align: justify;\"><big>Bolalar uchun yozgi ta&rsquo;tilni maroqli, mazmunli tashkil etish muhim ahamiyatga ega.</big></p>\r\n\r\n<p style=\"text-align: justify;\"><big><img alt=\"\" src=\"http://het.uz/uploads/c54c7f86-4ac1-1232-cd89-afc4161ef769_media_.jpg\" /></big></p>\r\n\r\n<p style=\"text-align: justify;\"><big><img alt=\"\" src=\"http://het.uz/uploads/7dabe261-15e4-775d-ef3a-d7dfeab5645b_media_.jpg\" /></big></p>\r\n\r\n<p style=\"text-align: justify;\"><big>Zero, yozgi ta&rsquo;til maktab mashg&lsquo;ulotidan charchagan o&lsquo;quvchi to&lsquo;liq dam olishi, kuch to&lsquo;plashi va sog&lsquo;lig&lsquo;ini yaxshilashi mumkin bo&lsquo;lgan vaqt hisoblanadi.</big></p>\r\n\r\n<p style=\"text-align: justify;\"><big><img alt=\"\" src=\"http://het.uz/uploads/b114701a-4049-f93b-7dcc-d6752fd1dc9e_media_.jpg\" /></big></p>\r\n\r\n<p style=\"text-align: justify;\"><img alt=\"\" src=\"http://het.uz/uploads/e703c4cf-2dd1-4a60-2d11-995e46f7457e_media_.jpg\" /></p>\r\n\r\n<p style=\"text-align: justify;\"><big>&ldquo;Hududiy elektr tarmoqlari&rdquo; AJ Andijon hududiy filialida faoliyat yuritayotgan ishchi-xodimlarning farzandlari Buloqboshi tumanida joylashgan &ldquo;Energetik&rdquo; yozgi bolalar oromgohiga kuzatildilar.</big></p>\r\n\r\n<p style=\"text-align: justify;\"><big><img alt=\"\" src=\"http://het.uz/uploads/aac9eb9c-610c-d4db-b07c-51b8e138c57a_media_.jpg\" /></big></p>\r\n\r\n<p style=\"text-align: justify;\"><img alt=\"\" src=\"http://het.uz/uploads/ebd65c38-f5f7-c324-da9f-6054add647e3_media_.jpg\" /></p>\r\n\r\n<p style=\"text-align: justify;\"><big>Oromgoh bir necha kunlik tayyorgarlikdan so&rsquo;ng o&rsquo;z ishini boshladi. Ikki hafta davomida so&lsquo;lim tabiat bag&lsquo;rida dam oladigan o&lsquo;g&lsquo;il-qizlar guruhlarga bo&lsquo;linib, yotoqxonalarga joylashtirildi va ularga kundalik tartiblar tushintirildi.</big></p>\r\n\r\n<p style=\"text-align: justify;\"><big><img alt=\"\" src=\"http://het.uz/uploads/8d49fd08-1413-b506-4c57-cd455faf5fe9_media_.jpg\" /></big></p>\r\n\r\n<p style=\"text-align: justify;\"><big><img alt=\"\" src=\"http://het.uz/uploads/8e34624e-939a-e5d0-0d1d-01a2c4f8ed57_media_.jpg\" /></big></p>\r\n\r\n<p style=\"text-align: right;\"><strong><big>&ldquo;Hududiy elektr tarmoqlari&rdquo; AJ Andijon hududiy filiali matbuot xizmati</big></strong></p>\r\n', '5d61e7d2-515e-1817-e548-397f3e0bed4c_lists_.jpg', 'be954877-cebe-c950-524d-e029de8aca27_lists_.jpg', 1448, 1, 4, NULL, 1717572201, 1760906589, ''),
(2479, 2009, 'oz', '“HUDUDIY ELEKTR TARMOQLARI” AJ ANDIJON HUDUDIY FILIALI  “MA’NAVIYAT VA MA’RIFAT” MASALALARIDA ENG NAMUNALI TASHKILOT SIFATIDA TANLAB OLINDI', 'Ma’naviyatli insonlar ko‘paygan jamiyatda aql, sog‘lom fikr, yaxshi xulq, insof va adolat tantana qilib, turli salbiy illatlar barham topadi. Natijada jamiyat a’zolarining kelajakka ishonchi ortib, ular o‘z faoliyatlarini Vatan va xalq ravnaqi yo‘lida safarbar etadi. ', '<p style=\"text-align: justify;\"><img alt=\"\" src=\"http://het.uz/uploads/4c6adbe4-df26-a90b-5409-6488a7f94cba_media_.jpg\" /></p>\r\n\r\n<p style=\"text-align: justify;\"><big>Ma&rsquo;naviyatli insonlar ko&lsquo;paygan jamiyatda aql, sog&lsquo;lom fikr, yaxshi xulq, insof va adolat tantana qilib, turli salbiy illatlar barham topadi. Natijada jamiyat a&rsquo;zolarining kelajakka ishonchi ortib, ular o&lsquo;z faoliyatlarini Vatan va xalq ravnaqi yo&lsquo;lida safarbar etadi.</big></p>\r\n\r\n<p style=\"text-align: justify;\"><big><img alt=\"\" src=\"http://het.uz/uploads/a08a85fc-11cd-6593-a5ad-fca80b32522c_media_.jpg\" /></big></p>\r\n\r\n<p style=\"text-align: justify;\"><big><img alt=\"\" src=\"http://het.uz/uploads/a36f0734-aa94-b302-d627-1fc755ece2a0_media_.jpg\" /></big></p>\r\n\r\n<p style=\"text-align: justify;\"><big>Respublika Maʼnaviyat va maʼrifat markazi Аndijon viloyat boʼlimi, &quot;Ma&#39;rifat&quot; targ&lsquo;ibotchilar jamiyati va boshqa hamkor tashkilotlar bilan birgalikda Markazning tuman va shahar boʼlinmalari rahbarlari, mutaxassislari uchun &quot;Maʼnaviy-maʼrifiy ishlar: Muammo,&nbsp; tahlil,&nbsp; yechim&quot;mavzusida viloyat oʼquv amaliy seminari tashkil etildi.</big></p>\r\n\r\n<p style=\"text-align: justify;\"><img alt=\"\" src=\"http://het.uz/uploads/e5e1e173-cff7-ef0d-4f9a-d214ff233f94_media_.jpg\" /></p>\r\n\r\n<p style=\"text-align: justify;\"><img alt=\"\" src=\"http://het.uz/uploads/a3897cb2-e59e-a301-a8ac-4e71cdc3ccf9_media_.jpg\" /></p>\r\n\r\n<p style=\"text-align: justify;\"><big>Markaz tomonidan viloyatda Ma&rsquo;naviyat va ma&rsquo;rifat masalalarida eng namunali tashkilot sifatida &ldquo;Hududiy elektr tarmoqlari&rdquo; AJ Andijon hududiy filiali tanlab olinib, seminar ishtirokchilariga filialning targ&rsquo;ibot ishlari namuna qilib ko&rsquo;rsatildi.</big></p>\r\n\r\n<p style=\"text-align: justify;\"><img alt=\"\" src=\"http://het.uz/uploads/b90c89d2-6ab2-bf1e-ac5e-2fc82f1589b8_media_.jpg\" /></p>\r\n\r\n<p style=\"text-align: justify;\"><img alt=\"\" src=\"http://het.uz/uploads/dbe262f9-3ff9-1ae5-df32-04332f27ef12_media_.jpg\" /></p>\r\n\r\n<p style=\"text-align: justify;\"><big>Ishtirokchilar filialda tashkil etilgan ma&rsquo;naviyat burchagi, kutubxona hamda ma&rsquo;naviyat xonalari bilan yaqindan tanishdilar.&nbsp; Tadbir so&rsquo;ngida Respublika Maʼnaviyat va maʼrifat markazi Аndijon viloyat boʼlimi rahbari A.Nurmatov tomonidan Andijon hududiy filiali direktori X. Yuldashevga Tashakkurnoma hamda Ma&rsquo;naviyatning eng sara adabiyotlari taqdim etildi.</big></p>\r\n\r\n<p style=\"text-align: justify;\"><img alt=\"\" src=\"http://het.uz/uploads/5e571f5d-5bd2-8dfe-d09d-933ca0abbf80_media_.jpg\" /></p>\r\n\r\n<p style=\"text-align: justify;\"><img alt=\"\" src=\"http://het.uz/uploads/02390217-c5bb-70a7-11a0-91cfdda07cf0_media_.jpg\" /></p>\r\n\r\n<p style=\"text-align: right;\"><big><strong>&ldquo;Hududiy elektr tarmoqlari&rdquo; AJ Andijon hududiy filiali matbuot xizmati</strong></big></p>\r\n', 'e0d2c3bc-4885-06b5-465b-53ea3e20ae38_lists_.jpg', '39227640-da58-8aa8-5012-806abb0af484_lists_.jpg', 1965, 1, 4, NULL, 1717647653, 1760950413, ''),
(2480, 2010, 'oz', '\"HUDUDIY ELEKTR TARMOQLARI\" AJ JAMOASI KASB MAHORATI TANLOVIDA QATNASHIB, G’OLIBLIKNI QO’LGA KIRITDI', '2024-yil 3-iyundan 8-iyunga qadar Turkiy xalglar davlatlari o’rtasida taqsimlash elektr tarmoqlariga xizmat ko’rsatuvchi elektromotyorlarning navbatdagi kasb mahorati musobaqasi Tatariston Respublikasi Tetyushi shahrida o’tkazilayotgan bo’lib, O‘zbekiston nomidan \"Hududiy elektr tarmoqlari\" AJ jamoasi ham faol ishtirok etmoqda.', '<p style=\"text-align: justify;\"><img alt=\"\" src=\"http://het.uz/uploads/2de72a6a-4ff6-9c36-de51-12bcc8801793_media_.jpg\" /></p>\r\n\r\n<p style=\"text-align: justify;\"><big>2024-yil 3-iyundan 8-iyunga qadar turkiy xalglar davlatlari o&rsquo;rtasida taqsimlash elektr tarmoqlariga xizmat ko&rsquo;rsatuvchi elektromotyorlarning navbatdagi kasb mahorati musobaqasi Tatariston Respublikasi Tetyushi shahrida o&rsquo;tkazilayotgan bo&rsquo;lib, O&lsquo;zbekiston nomidan &quot;Hududiy elektr tarmoqlari&quot; AJ jamoasi ham faol ishtirok etmoqda.</big></p>\r\n\r\n<p style=\"text-align: justify;\"><big><img alt=\"\" src=\"http://het.uz/uploads/7a8a39e7-a659-6e1e-5dd2-4cd5bb3f6fe1_media_.jpg\" /></big></p>\r\n\r\n<p style=\"text-align: justify;\"><big><img alt=\"\" src=\"http://het.uz/uploads/3804e0aa-56fb-32d2-0927-caaee7dcdc95_media_.jpg\" /></big></p>\r\n\r\n<p style=\"text-align: justify;\"><big>Ayni paytda, turkiy tilda so&lsquo;zlashuvchi davlatlar energetiklari o&lsquo;rtasida о&lsquo;tkazilayotgan musobaqada jamoalar texnik tayyorgarlik va avariyaviy holatlarni bartaraf etish yuzasidan о&lsquo;zaro bahs sinashdilar va ushbu musobaqada barcha shartlarda yuqori natijalarni ko&#39;rsatgan &quot;Hududiy elektr tarmoqlari&quot;&nbsp; AJ jamoasi 1-о&lsquo;rinni egalab, g&#39;olib deb topildi.</big></p>\r\n\r\n<p style=\"text-align: justify;\"><big><img alt=\"\" src=\"http://het.uz/uploads/612a5165-83bd-5a8c-6536-bd470bef8da7_media_.jpg\" /></big></p>\r\n\r\n<p style=\"text-align: justify;\"><img alt=\"\" src=\"http://het.uz/uploads/688bc3f7-ea75-824b-1430-a81a5653aed8_media_.jpg\" /></p>\r\n\r\n<p style=\"text-align: justify;\"><big>Mazkur musobaqaning natijalariga ko&rsquo;ra, turkiy xalglar davlatlari o&rsquo;rtasida taqsimlash elektr tarmoqlariga xizmat ko&rsquo;rsatuvchi elektromotyorlarning navbatdagi musobaqasi O&rsquo;zbekiston Respublikasida o&#39;tkaziladigan bo&#39;ldi.</big></p>\r\n\r\n<p style=\"text-align: justify;\"><big><img alt=\"\" src=\"http://het.uz/uploads/826c7f2a-897c-5ba8-1751-eaad4270a80c_media_.jpg\" /></big></p>\r\n\r\n<p style=\"text-align: right;\"><big>&quot;Hududiy elektr tarmoqlari&quot; AJ Matbuot xizmati</big></p>\r\n\r\n<p style=\"text-align: right;\">&nbsp;</p>\r\n\r\n<blockquote>\r\n<p style=\"text-align: justify;\"><em><big>&laquo;Очень важно, что все электромонтеры понимают друг друга, даже общаясь на родном для себя языке&raquo;, - говорит Мурад Эгамкулов &ndash; начальник службы надежности техники безопасности АО &laquo;Региональные электрические сети&raquo;. Сегодня возглавляемая им команда из Узбекистана прошла через два этапа &ndash; выступила в роли &laquo;огнеборцев&raquo; и спасла имитирующий человека манекен. Перед ребятами&nbsp; были поставлены&nbsp; задачи по выбору алгоритма действий: моментально среагировать и выбрать&nbsp; необходимые на данных этапах&nbsp; инструменты и действия.<br />\r\nЭнергетики из Узбекистана цепки и наблюдательны: применяемые коллегами из Татарстана новые технологии встречают с одобрением и планируют учитывать эти новшества и в своей работе. А также планируют общаться с родственными не только по профессии коллегами &ndash; такой бесценный опыт раскрывает для всех&nbsp; новые возможности!</big></em></p>\r\n\r\n<p style=\"text-align: right;\"><em><big>АО &laquo;Сетевая компания&raquo; Республики Татарстан</big></em></p>\r\n</blockquote>\r\n\r\n<p style=\"text-align: justify;\"><img alt=\"\" src=\"http://het.uz/uploads/5f4f8549-d40f-2d54-1c16-54b782ccfc4f_media_.jpg\" /></p>\r\n\r\n<p style=\"text-align: right;\">&nbsp;</p>\r\n', 'babb9edc-4bed-4483-0c2b-36e2e415f200_lists_.jpg', 'a525ee22-68db-9d57-0a13-6567f78d6c93_lists_.jpg', 1835, 1, 4, NULL, 1717687015, 1760954606, ''),
(2481, 2011, 'oz', 'ESG', NULL, '<p><strong><big>О&lsquo;zbekiston Respublikasi Prezidentining 2024-yil 21-fevraldagi PF-37-son Farmoni va bu boradagi &quot;Hududiy elektr tarmoqlari&quot; AJ boshqaruv raisining 2024-yil 26-fevraldagi 27-son buyrug&lsquo;iga binoan, davlat ishtirokidagi korxonalar faoliyatida ochiqlik darajasini keskin oshirish va korporativ boshqaruvni yanada takomillashtirish maqsadida 2024-yil 1-iyuldan boshlab korporativ ijtimoiy mas&#39;uliyat (CSR) hamda ekologik, ijtimoiy va korporativ boshqaruv (ESG) holati to&lsquo;g&lsquo;risidagi hisobotni har yilning 1-iyuliga qadar jamoatchilikga oshkor etish amaliyotini&nbsp; joriy etish bo&lsquo;yicha topshiriqlar berilgan.&nbsp;</big></strong></p>\r\n\r\n<p><big><strong>Shunga ko</strong></big><strong><big>&lsquo;ra, korporativ ijtimoiy mas&#39;uliyat (CSR) hamda ekoloik, ijtimoiy va korporativ boshqaruv (ESG) holati&nbsp;to&lsquo;g&lsquo;risidagi 2024-yilgi hisobotni ishlab chiqildi.</big></strong></p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<div style=\"background:#eeeeee;border:1px solid #cccccc;padding:5px 10px;\"><strong><big><a href=\"https://het.uz/ru/pages/view/ESG\">&quot;Hududiy elektr tarmoqlari&quot; AJning 2024-yil uchun barqaror rivojlanish hisoboti&nbsp;saytning rus tilidagi versiyasida joylashtirilgan</a></big></strong></div>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<div style=\"background:#eeeeee;border:1px solid #cccccc;padding:5px 10px;\"><a href=\"https://www.het.uz/ru/pages/view/ESG\"><strong><big>&quot;Hududiy elektr tarmoqlari&quot; AJning korporativ ijtimoiy mas&rsquo;uliyat (CSR) hamda ekologik, ijtimoiy va korporativ boshqaruv (ESG) holati tо&lsquo;g&lsquo;risidagi 2023-yilgi hisobot saytning rus tilidagi versiyasida joylashtirilgan</big></strong></a></div>\r\n', NULL, NULL, 7729, 1, 4, NULL, 1718004198, 1760965739, ''),
(2482, 2011, 'ru', 'ESG', NULL, '<p><strong><big>В соответствии с Указом Президента Республики Узбекистан от 21 февраля 2024 года № ПФ-37 и Приказом Председателя Правления АО &laquo;Региональные электрические сети&raquo; от 26 февраля 2024 года № 27 в целях кардинального повышения уровня прозрачности деятельности государственных предприятий и дальнейшего совершенствования корпоративного управления даны поручения по внедрению практики раскрытия общественности отчетов о корпоративной социальной ответственности (CSR) и экологическом, социальном и корпоративном управлении (ESG) до 1 июля каждого года.&nbsp;</big></strong></p>\r\n\r\n<p><strong><big>Соответственно разработан Отчет о корпоративной социальной ответственности (CSR) и экологическом, социальном и корпоративном управлении (ESG) за 2024 год.&raquo;.</big></strong></p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<div style=\"background:#eeeeee;border:1px solid #cccccc;padding:5px 10px;\"><a href=\"http://het.uz/uploads/24a0f6d6-00eb-6b8a-ff30-c3e8c862de2f_media_.pdf\"><big><strong>Отчет об устойчивом развитии АО &laquo;Региональные электрические сети&raquo; за 2024 год</strong></big></a></div>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<div style=\"background:#eeeeee;border:1px solid #cccccc;padding:5px 10px;\"><a href=\"http://het.uz/uploads/564afb06-2850-6dc2-ff7f-a42349e3ee9d_media_.pdf\"><big><strong>Отчет о состоянии корпоративной социальной ответственности (CSR), а также экологического, социального и корпоративного управления (ESG) АО &quot;Региональные электрические сети&quot; за 2023 год</strong></big></a></div>\r\n', NULL, NULL, 6132, 1, 4, NULL, 1718004388, 1760972864, ''),
(2483, 2012, 'oz', '“NAFOSAT” MAHALLASIDA 120 DAN XONADONLARNING ELEKTR TA\'MINOTI YAXSHILANMOQDA', '  ', '<p style=\"text-align: center;\"><strong><big>&ldquo;NAFOSAT&rdquo; MAHALLASIDA 120 DAN XONADONLARNING ELEKTR TA&#39;MINOTI YAXSHILANMOQDA</big></strong></p>\r\n\r\n<p><big>Farg&lsquo;ona &nbsp;shahrining &quot;Nafosat&quot; mahallasi fuqarolar yig&rsquo;inidagi iste&rsquo;molchilarning elektr ta&rsquo;minoti yaxshilanmoqda.</big></p>\r\n\r\n<p><big><img alt=\"\" src=\"http://het.uz/uploads/c1837727-de1c-2669-2067-e48eeff34652_media_.jpg\" /><img alt=\"\" src=\"http://het.uz/uploads/16aee6c0-dabb-8fd6-6a42-ddc16472709b_media_.jpg\" /></big></p>\r\n\r\n<p><big>&nbsp;Loyiha asosida shu kunga qadar mahallaga 245 dona yangi temir-beton hududga olib kelib o&rsquo;rnatildi. Mutaxassislar tomonidan 5,9 km uzunlikda 0,4-6 kVli yangi elektr uzatish tarmog&rsquo;ini qurish ishlari yakuniga yetkazilmoqda.&nbsp;</big></p>\r\n\r\n<p><big><img alt=\"\" src=\"http://het.uz/uploads/59d1e2be-be02-5d31-0dcf-7c910fdc2045_media_.jpg\" /></big></p>\r\n\r\n<p><big>Bundan tashqari, mahalla hududidagi transformator punkti yukini yengillatish maqsadida qo&lsquo;shimcha bir dona yangi transformator punkti o&lsquo;rnatildi.</big></p>\r\n\r\n<p><big>Buning natijasida mahalladagi 120 dan xonadonlarning elektr ta&#39;minoti yaxshilanmoqda.</big></p>\r\n\r\n<p><big><img alt=\"\" src=\"http://het.uz/uploads/abf849af-5a2b-b153-de51-88638ad5dae6_media_.jpg\" /><img alt=\"\" src=\"http://het.uz/uploads/7e287cd0-2cb2-6502-76f6-cdf98115bd9b_media_.jpg\" /></big></p>\r\n\r\n<p><big>Hududlarda bu kabi amaliy ishlar davom etmoqda.</big></p>\r\n', '0e436b69-c4bf-dfcd-99b8-1a8160080836_lists_.jpg', 'a74177cf-8c6d-5d2b-0c1c-7c6120646960_lists_.jpg', 1397, 1, 4, NULL, 1718366187, 1760844106, ''),
(2484, 2013, 'oz', 'PODSTANSIYANING QUVVATI OSHIRILMOQDA', 'PODSTANSIYANING QUVVATI OSHIRILMOQDA\r\n', '<p style=\"text-align: center;\"><big><strong>PODSTANSIYANING QUVVATI OSHIRILMOQDA</strong></big></p>\r\n\r\n<p style=\"text-align: center;\"><big><strong><img alt=\"\" src=\"http://het.uz/uploads/535b6c6e-067c-ed8c-0f0c-68f842eda6a0_media_.jpg\" /></strong></big></p>\r\n\r\n<p><strong>Buxoro viloyati aholisi va tadbirkorlarni barqaror elektr energiyasi bilan ta&rsquo;minlash hamda kuz-qish mavsumiga puxta tayyorgarlik kо&lsquo;rish maqsadida &ldquo;Buxoro hududiy elektr tarmoqlari korxonasi&rdquo; AJ qator loyihalar amalga oshirilmoqda.</strong></p>\r\n\r\n<p><strong><img alt=\"\" src=\"http://het.uz/uploads/4ad1c82a-4cd3-da8c-c221-66c8e59ec243_media_.jpg\" /></strong></p>\r\n\r\n<p><strong>Xususan, viloyat hududlarida joylashgan yuqori kuchlanishdagi podstansiyalarda modernizatsiya, yangilash ishlari bajarilmoqda.</strong></p>\r\n\r\n<p><strong><img alt=\"\" src=\"http://het.uz/uploads/3f39c0cc-53af-4492-852b-d6a78258d0e8_media_.jpg\" /></strong></p>\r\n\r\n<p><strong>Ayni paytda loyiha asosida &nbsp;110/35/10 &ldquo;Vobkent&rdquo; podstansiyasining quvvatini oshirish uchun 2 dona 40 000 kVAli kuch transformatorlari olib kelindi. Hozirgi kunda mazkur transformatorlarni o&rsquo;rnatish jarayonlari olib borilmoqda.&nbsp;</strong></p>\r\n\r\n<p><strong><img alt=\"\" src=\"http://het.uz/uploads/73bb8c8a-ada3-3cd9-7333-50acb34b5605_media_.jpg\" /></strong></p>\r\n\r\n<p><strong>Ta&rsquo;kidlash joizki, umumiy qiymati 19 mlrd. so&rsquo;mdan ortiq bo&rsquo;lgan ushbu kuch transformatorlarining ishga tushurilishi Vobkent tumani hamda unga yondosh hududlardagi 30 000ga yaqin iste&rsquo;molchilar elektr energiyasi ta&rsquo;minotini &nbsp;yanada yaxshilash imkonini beradi.</strong></p>\r\n', 'cbb3c6c4-d527-3153-cd1d-7ca0e9cb35ee_lists_.jpg', '3f5b225c-b729-5d12-0364-a9cf198d72a7_lists_.jpg', 1275, 1, 4, NULL, 1719575790, 1760927450, ''),
(2485, 2014, 'oz', 'HURMATLI ISTE’MOLCHILAR!', ' ', '<p style=\"text-align: center;\"><big><strong>HURMATLI ISTE&rsquo;MOLCHILAR!</strong></big></p>\r\n\r\n<p style=\"text-align: center;\"><big><strong>О&lsquo;zbekiston Respublikasi Vazirlar Mahkamasining 2018 yil 26 dekabrdagi 1050-son qaroriga asosan Muhofaza zonalarida elektr tarmog&lsquo;i xо&lsquo;jaligi obyektlarining xavfsiz ishlashining buzilishi, shuningdek ekologik zarar va yong&lsquo;in keltirib chiqarishi mumkin bо&lsquo;lgan biron-bir harakatni sodir etish, jumladan:</strong></big></p>\r\n\r\n<p><big><strong>a) elektr uzatish havo liniyalari simlariga va tayanchlariga begona predmetlarni tashlash, shuningdek, elektr uzatish havo liniyalari tayanchlariga kо&lsquo;tarilish;</strong></big></p>\r\n\r\n<p><big><strong><img alt=\"\" src=\"http://het.uz/uploads/b1d29e50-5def-a0ca-8a14-ba6a00691857_media_.jpg\" /></strong></big></p>\r\n\r\n<p><big><strong>b) ... elektr tarmog&lsquo;i xо&lsquo;jaligi obyektlariga yurib о&lsquo;tish va transport vositasida о&lsquo;tish joylariga har qanday obyektlarni, predmetlarni joylashtirish;</strong></big></p>\r\n\r\n<p><big><strong><img alt=\"\" src=\"http://het.uz/uploads/f80a45ec-f131-3866-e9d0-71ca53f36ad8_media_.jpg\" /></strong></big></p>\r\n\r\n<p><big><strong>v) &hellip; elektr uzatish havo liniyalari muhofaza zonasi doirasida, shuningdek, elektr uzatish kabel liniyalarining muhofaza zonalarida olov yoqish;</strong></big></p>\r\n\r\n<p><big><strong><img alt=\"\" src=\"http://het.uz/uploads/23c6bcb3-3d45-6c08-2bff-2e659a4cc09f_media_.jpg\" /></strong></big></p>\r\n\r\n<p><big><strong>g) ... kо&lsquo;plab odamlar yig&lsquo;ilishi bilan bog&lsquo;liq bо&lsquo;lgan har qanday tadbirlarni о&lsquo;tkazish;</strong></big></p>\r\n\r\n<p><big><strong><img alt=\"\" src=\"http://het.uz/uploads/60414b26-4ee0-2fca-921e-e604dfe6713e_media_.jpg\" /></strong></big></p>\r\n\r\n<p><big><strong>d) axlatxonalarni joylashtirish;</strong></big></p>\r\n\r\n<p><big><strong><img alt=\"\" src=\"http://het.uz/uploads/d12281eb-390c-1783-5b8c-bf3c330bbb9e_media_.jpg\" /></strong></big></p>\r\n\r\n<p><big><strong>ye) ... yoqilg&lsquo;i-moylash materiallarini tashlash va quyish (muhofaza zonasida) taqiqlanadi.</strong></big><br />\r\n&nbsp;</p>\r\n', 'f4f88b7c-6c23-8b2a-5abe-fdca456722a6_lists_.jpg', '751cdad2-8e53-da99-3d72-fc44ef16e125_lists_.jpg', 36823, 1, 4, NULL, 1719808645, 1760906986, ''),
(2486, 2015, 'oz', 'CHIMYONDA YANGI PODSTANSIYA QURISH ISHLARI OLIB BORILMOQDA', ' ', '<p style=\"text-align: center;\"><strong><big>CHIMYONDA YANGI PODSTANSIYA QURISH ISHLARI OLIB BORILMOQDA</big></strong></p>\r\n\r\n<p style=\"text-align: center;\"><strong><big><img alt=\"\" src=\"http://het.uz/uploads/11730608-0de5-197c-8612-b3532565dd23_media_.jpg\" /><img alt=\"\" src=\"http://het.uz/uploads/ef0b83dc-77e8-933f-11b9-cde715936a33_media_.jpg\" /></big></strong></p>\r\n\r\n<p><big>О&lsquo;zbekiston Respublikasi Prezidentining &ldquo;Chimyon xalqaro umummavsumiy kurorti qurilishini jadallashtirish chora-tadbirlari&rdquo; tо&lsquo;g&lsquo;risida qaroriga (https://lex.uz/docs/6561892) asosan Toshkent viloyati Bо&lsquo;stonliq tumanida &ldquo;Chimyon&rdquo; xalqaro umummavsumiy kurortini elektr energiyasi bilan ta&rsquo;minlash maqsadida &ldquo;Hududiy elektr tarmoqlari&rdquo; AJ &quot;Hududiy qurilish-montaj direksiyasi&quot; tomonidan yangi 110/35/10 kV kuchlanishli yangi podstansiya qurish ishlari olib borilmoqda.</big></p>\r\n\r\n<p><big><img alt=\"\" src=\"http://het.uz/uploads/cdb20068-4a3c-06dc-3811-1aee32f72694_media_.jpg\" /><img alt=\"\" src=\"http://het.uz/uploads/0143f0d6-02b5-b729-9fe1-bc42c7e1f7e9_media_.jpg\" /></big><img alt=\"\" src=\"http://het.uz/uploads/c9295618-e2f7-6135-75f5-95ae894bf00f_media_.jpg\" /></p>\r\n\r\n<p><big>Ayni paytda podstansiya uchun ajratilgan hududda yer ishlari olib borilmoqda. Qurilishni о&lsquo;z vaqtida va mukammal tugatish maqasadida zarur texnika va xodimlar tunu kun faoliyat yuritishmoqda.</big></p>\r\n', '3ab29138-a3e4-e140-e7d3-8af8fd2c154f_lists_.jpg', '3ece5db7-4722-2f9b-5362-5b2eea6ef150_lists_.jpg', 1438, 1, 4, NULL, 1719983456, 1760844073, ''),
(2487, 2016, 'oz', 'Boshqarma boshliqlari ishtirokida Davlat boshqaruv Akademiyasida о‘quv-amaliy seminar tashkil etildi.', ' ', '<p><big><strong>&nbsp;Energetik xavfsizlikni ta&rsquo;minlash sohasida nazoratni&nbsp;tashkil etish, energiya resurslaridan foydalanish samaradorligini oshirish hamda ijtimoiy soha obyektlari va kо&lsquo;p kvartirali uy-joy fondini kuz-qish mavsumiga tayyorlash maqsadida Qoraqalpog&lsquo;iston Respublikasi, viloyatlar va Toshkent shahar prokurorlarining sohaviy о&lsquo;rinbosarlari, tuman&ndash;shahar prokurorlari, bо&lsquo;lim boshliqlari &ldquo;Hududiy elektr tarmoqlari&rdquo; va &ldquo;Hududgazta&rsquo;minot&rdquo; AJlarning hududiy filiallari hamda О&lsquo;zenergoinspeksiyaning hududiy boshqarmalari boshliqlari ishtirokida Davlat boshqaruv Akademiyasida о&lsquo;quv-amaliy seminar tashkil etildi.</strong></big></p>\r\n\r\n<p><img alt=\"\" src=\"http://het.uz/uploads/8b0e195c-3943-6764-fa53-097fd87fb0d2_media_.jpg\" /></p>\r\n\r\n<p><big><strong>О&lsquo;quv mashg&lsquo;ulotlarida asosiy e&rsquo;tibor, ishtirokchilarda energobalansni shakllantirish, energiya resurslarini iqtisod qilish va ulardan noqonuniy foydalanish holatlarini oldini olishda mahallabay ishlash bо&lsquo;yicha yangicha yondashuvlarga oid bilim va kо&lsquo;nikmalarni oshirishga qaratilmoqda.</strong></big></p>\r\n\r\n<p><img alt=\"\" src=\"http://het.uz/uploads/d8eaf6ff-d806-a6a0-6b19-88ba32751082_media_.jpg\" /></p>\r\n\r\n<p><big><strong>Shuningdek, yoqilg&lsquo;i-energiya resurslaridan foydalanish ustidan davlat nazoratini amalga oshirish jarayonida hamkorlik mexanizmi ishtirokchilarning e&rsquo;tiboriga yetkazildi.</strong></big></p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><img alt=\"\" src=\"http://het.uz/uploads/bca43a1d-3ea0-42d6-9179-d540b217b354_media_.jpg\" /></p>\r\n\r\n<p><big><strong>Seminarning dastlabki kunida tinglovchilarga neft, tabiiy gaz, elektr energiyasi va qayta tiklanuvchi energiya manbalariga doir nazariy bilimlar soha mutaxassislari, professor-olimlar tomonidan batafsil tushuntirildi.</strong></big></p>\r\n\r\n<p><big><strong><img alt=\"\" src=\"http://het.uz/uploads/dabc415c-a8c9-5d1b-8cf9-ecef45d20007_media_.jpg\" /></strong></big></p>\r\n', '26eb2976-06d3-d36b-b977-3293e37bd985_lists_.jpg', '62a946b8-6925-234f-8bf4-ce42e352a1a7_lists_.jpg', 1604, 1, 4, NULL, 1720154233, 1760953840, ''),
(2488, 2017, 'oz', 'HUDUDLARDA ISHCHI GURUH TOMONIDAN AHOLI O’RTASIDA TUSHINTIRISH ISHLARI OLIB BORILMOQDA', ' ', '<p style=\"text-align: center;\"><big><strong>HUDUDLARDA ISHCHI GURUH TOMONIDAN AHOLI O&rsquo;RTASIDA TUSHINTIRISH ISHLARI OLIB BORILMOQDA</strong></big></p>\r\n\r\n<p><img alt=\"\" src=\"http://het.uz/uploads/0fbea124-1a8c-68b0-adab-d841a9d208cf_media_.jpg\" /></p>\r\n\r\n<p><img alt=\"\" src=\"http://het.uz/uploads/09ed6458-ebb5-f3b5-7b4f-746b84b94902_media_.jpg\" /></p>\r\n\r\n<p><img alt=\"\" src=\"http://het.uz/uploads/b9c08000-a093-e87c-c18d-3609d2219cc6_media_.jpg\" /></p>\r\n\r\n<p><big><strong>Vazirlar Mahkamasining 2024-yil 16-aprelda &ldquo;Yoqilg&lsquo;i-energetika sohasida bozor mexanizmlarini joriy etishning qo&lsquo;shimcha chora-tadbirlari to&lsquo;g&lsquo;risida&rdquo;gi 204-sonli qaroriga (https://lex.uz/uz/docs/6884060) muvofiq &ldquo;Hududiy elektr tarmoqlari&rdquo; AJ tomonidan ishchi guruhi tuzilib, Andijon viloyatining bir nechta hududlarida aholi o&rsquo;rtasida to&rsquo;lov intizomiga &nbsp;rioya qilish bo&rsquo;yicha Mahalla yettiligi bilan birgalikda tushintirish ishlari olib bormoqdalar.</strong></big></p>\r\n\r\n<p><img alt=\"\" src=\"http://het.uz/uploads/e69f7d88-e5e4-9b06-e519-1570fd59fe3c_media_.jpg\" /></p>\r\n\r\n<p><img alt=\"\" src=\"http://het.uz/uploads/98738f99-908a-84f7-819f-221bc1723741_media_.jpg\" /></p>\r\n\r\n<p><big><strong>Ayni vaqtda Andijon shahrining &ldquo;Sarvontepa&rdquo; MFY hududida yashovchi aholi uchun targ&rsquo;ibot ishlari olib borilib, aholi o&rsquo;rtasida tarif bo&rsquo;yicha qiynab kelayotgan savollarga javob berildi.</strong></big></p>\r\n\r\n<p><big><strong><img alt=\"\" src=\"http://het.uz/uploads/c8285f62-f3f4-2d85-d942-89d42ff57aa2_media_.jpg\" /></strong></big></p>\r\n\r\n<p><big><strong><img alt=\"\" src=\"http://het.uz/uploads/b068a3f8-146f-4ae1-9760-dfbd67cf0052_media_.jpg\" /></strong></big></p>\r\n\r\n<p><big><strong>Fuqarolar tomonidan bildirilgan takliflar nazoratga olindi.</strong></big></p>\r\n', '96cb3414-58fc-a2b5-5f0e-30562de3544a_lists_.jpg', NULL, 1354, 1, 4, NULL, 1720521511, 1760911881, ''),
(2489, 2018, 'oz', 'OAV xodimlari va blogerlar uchun press-tur tashkil qilindi', '  ', '<p style=\"text-align: center;\"><big><strong>OAV xodimlari va blogerlar uchun press-tur tashkil qilindi</strong></big></p>\r\n\r\n<p style=\"text-align: center;\">&nbsp;</p>\r\n\r\n<p style=\"text-align: center;\"><big><strong><img alt=\"\" src=\"http://het.uz/uploads/a9a92191-3e6f-ed16-0b55-6545b7e912a3_media_.jpg\" /></strong></big></p>\r\n\r\n<p style=\"text-align: center;\"><big><strong><img alt=\"\" src=\"http://het.uz/uploads/4c5d1119-1a06-4720-3752-2b63233d96d7_media_.jpg\" /></strong></big></p>\r\n\r\n<p><big><strong>Bugun, 11 iyul kuni &quot;Hududiy elektr tarmoqlari&quot; AJning &quot;Elektr energiya sotishni avtomatlashtirish markazi&quot; filialiga &nbsp;ommaviy axborot vositalari vakillari, jurnalistlar va blogerlar uchun press-tur tashkil etildi.</strong></big></p>\r\n\r\n<p><big><strong><img alt=\"\" src=\"http://het.uz/uploads/ca5316f4-c9a8-4001-a737-416beb3585f5_media_.jpg\" /></strong></big></p>\r\n\r\n<p><big><strong><img alt=\"\" src=\"http://het.uz/uploads/f4776374-e181-039c-a7df-da2544b0e29b_media_.jpg\" /></strong></big></p>\r\n\r\n<p><big><strong><img alt=\"\" src=\"http://het.uz/uploads/a76c569f-1917-5ba5-3e71-a5c4077484bb_media_.jpg\" /></strong></big></p>\r\n\r\n<p><big><strong>Keyingi paytlarda iste&rsquo;molchilar tomonidan elektr energiyasi hisob-kitobiga oid yo&lsquo;llanayotgan &nbsp;murojaatlar hamda bu bo&lsquo;yicha kelib chiqayotgan tushunmovchiliklarga aniqlik kiritish maqsadida tashkil etilgan tadbirda elektr energiyasini hisobga olish va nazorat qilishning avtomatlashtirilgan tizimi (ASKUE) orqali iste&rsquo;molning sutkalik, oylik va yillik nazorati yuritilishi &nbsp;yuzasidan batafsil ma&rsquo;lumotlar berildi.</strong></big></p>\r\n\r\n<p><big><strong><img alt=\"\" src=\"http://het.uz/uploads/e15e1329-12b0-293c-90ed-609a0f3eae96_media_.jpg\" /></strong></big></p>\r\n\r\n<p><img alt=\"\" src=\"http://het.uz/uploads/feab31c1-1218-90d3-bfea-ed1fcaada988_media_.jpg\" /></p>\r\n\r\n<p><img alt=\"\" src=\"http://het.uz/uploads/69c16793-7d62-588d-f2d3-ef42e6ebf1ff_media_.jpg\" /></p>\r\n\r\n<p><img alt=\"\" src=\"http://het.uz/uploads/e4547043-b509-28e9-3e19-f081d5030562_media_.jpg\" /></p>\r\n\r\n<p><big><strong>Tadbirda qatnashgan ishtirokchilar о&lsquo;zlarining barcha qiziqtirgan savollariga atroflicha javob olishdi.</strong></big></p>\r\n', '636efd3d-31c5-79ef-6159-19f44c52d3dd_lists_.jpg', '3f7219b2-8028-79a3-167a-14108dd9f502_lists_.jpg', 1329, 1, 4, NULL, 1720704548, 1760844029, ''),
(2490, 2019, 'oz', 'Elektr tarmog‘iga o‘zboshimchalik bilan ulanganlik uchun jinoiy javobgarlik bor', 'Elektr tarmog‘iga o‘zboshimchalik bilan ulanganlik uchun jinoiy javobgarlik bor', '<p><big><strong>Elektr tarmog&lsquo;iga o&lsquo;zboshimchalik bilan ulanganlik uchun jinoiy javobgarlik bor</strong></big></p>\r\n\r\n<p><big><strong>Qonunchilikka ko&lsquo;ra, umumiy foydalanishdagi elektr tarmog&lsquo;iga tijorat maqsadlarida o&lsquo;zboshimchalik bilan ulanish yoxud elektr energiyasini hisobga olish asbobiga, shu jumladan uning plombasiga qasddan shikast yetkazish yoxud hisobga olish asbobining ko&lsquo;rsatkichini o&lsquo;zgartirish maqsadida unga tashqaridan aralashish yo&lsquo;li bilan talon-toroj qilish o&lsquo;g&lsquo;rilik hisoblanadi.</strong></big></p>\r\n\r\n<p><big><strong>&nbsp;Mazkur jinoyat uchun 5 yilgacha ozodlikdan mahrum qilish jazosi qo&lsquo;llanilishi mumkin.</strong></big></p>\r\n\r\n<p><big><strong>Qonunni bilmaslik javobgarlikdan ozod qilmaydi!</strong></big></p>\r\n', '2b8a096d-62fd-7634-dd14-ed18f2c7407c_lists_.jpg', '4247c736-8589-0748-9c07-478fd20fc596_lists_.jpg', 1065, 1, 4, NULL, 1721217182, 1760964331, ''),
(2491, 2020, 'oz', '\"NAVRO\'Z\" KICHIK SANOAT HUDUDIDAGI XODIMLAR O’RTASIDA TUSHUNTIRISH ISHLARI OLIB BORILDI', '', '<p style=\"text-align: center;\"><big><strong>&quot;NAVRO&#39;Z&quot; KICHIK SANOAT HUDUDIDAGI XODIMLAR O&rsquo;RTASIDA TUSHUNTIRISH ISHLARI OLIB BORILDI</strong></big></p>\r\n\r\n<p style=\"text-align: center;\"><big><strong><img alt=\"\" src=\"http://het.uz/uploads/72d00daa-2c34-1ae2-ea07-db1fd15867fd_media_.jpg\" /></strong></big></p>\r\n\r\n<p><big><strong>&nbsp;&ldquo;Hududiy elektr tarmoqlari&rdquo; AJ tomonidan ishchi guruhi tuzilib, Sirdaryo viloyati hududlarida aholi o&rsquo;rtasida &nbsp;Vazirlar Mahkamasining &ldquo;Yoqilg&lsquo;i-energetika sohasida bozor mexanizmlarini joriy etishning qo&lsquo;shimcha chora-tadbirlari to&lsquo;g&lsquo;risida&rdquo;gi 204-sonli qaroriga muvofiq bo&rsquo;yicha to&rsquo;lov intizomiga&nbsp;&nbsp;rioya qilish, qarorning mazmun-mohiyatini iste&#39;molchilarga to&#39;gri tushuntirish ishlari olib bormoqdalar.</strong></big></p>\r\n\r\n<p><big><strong><img alt=\"\" src=\"http://het.uz/uploads/3c03262c-6cf8-98cd-9093-1b2dfd193428_media_.jpg\" /></strong></big></p>\r\n\r\n<p><big><strong>Bugun &quot;Hududiy elektr tarmoqlari&quot; AJ MXTX boshlig&lsquo;i M. Egamqulov va Sirdaryo filiali ma&#39;sul xodimlari ishtirokida Mirzaobod tumanida joylashgan &quot;Navro&#39;z&quot; kichik sanoat hududida ishlovchi fuqarolar o&rsquo;rtasida tarif bo&rsquo;yicha savollarga javoblar berildi.</strong></big></p>\r\n\r\n<p><big><strong><img alt=\"\" src=\"http://het.uz/uploads/7666d4bb-0f28-6bca-9780-233d3ae5a1a4_media_.jpg\" /></strong></big></p>\r\n\r\n<p><big><strong><img alt=\"\" src=\"http://het.uz/uploads/7b9d98f4-472e-4db5-9576-6c0a9b3523d3_media_.jpg\" /></strong></big></p>\r\n\r\n<p><big><strong>Fuqarolar tomonidan bildirilgan takliflar nazoratga olindi. Mirzaobod tumanida targ&lsquo;ibot-tashviqot ishlari davom etmoqda.&nbsp;</strong></big></p>\r\n', '0616b9bb-8f06-a5dd-a626-1e88f3359403_lists_.jpg', '978d3c89-989a-7d45-03c5-c96b89df8266_lists_.jpg', 1095, 1, 4, NULL, 1721217378, 1760935870, ''),
(2492, 2021, 'oz', 'POYTAXTDA KUZ-QISH MAVSUMIGA TAYYORGARLIK QIZG‘IN DAVOM ETMOQDA', ' ', '<p><big><strong>POYTAXTDA KUZ-QISH MAVSUMIGA TAYYORGARLIK QIZG&lsquo;IN DAVOM ETMOQDA</strong></big></p>\r\n\r\n<p><big><strong><img alt=\"\" src=\"http://het.uz/uploads/b1089ae3-5483-0184-15ef-b10c532371f5_media_.jpg\" /></strong></big></p>\r\n\r\n<p><big><strong>&ldquo;Toshkent shahar elektr tarmoqlari&rdquo; MCHJ tomonidan poytaxtimizda 2024-2025-yillar kuz-qish mavsumiga tayyorgarlik ko&#39;rish maqsadida &nbsp;barcha tumanlarda belgilangan ishlar jadallik bilan olib borilmoqda.</strong></big></p>\r\n\r\n<p><big><strong><img alt=\"\" src=\"http://het.uz/uploads/f378bd29-6396-9a50-782a-32a997f10cc2_media_.jpg\" /></strong></big></p>\r\n\r\n<p><big><strong><img alt=\"\" src=\"http://het.uz/uploads/bdb0f103-d1fd-449a-e792-168971e7319c_media_.jpg\" /></strong></big></p>\r\n\r\n<p><big><strong>Xususan, Yashnobod &nbsp;tuman elektr ta&rsquo;minoti korxonasi tomonidan &ldquo;Yashnobod&rdquo; MFY Qorasuv ko`chasi hududidagi ko`p qavatli aholi yashash xonadonlarini elektr ta&#39;minotini yanada yaxshilash va aholining elektr energiyasi iste&#39;moliga bo&#39;lgan talabini to&#39;laqonli qondirish maqsadida, hududdagi mavjud quvvati 10 kV bo`lgan yuqori kuchlanishli TP-3060-sonli transformator punktida mukammal ta&#39;mirlash ishlari olib borilmoqda.&nbsp;</strong></big></p>\r\n\r\n<p><big><strong><img alt=\"\" src=\"http://het.uz/uploads/f95d4e4b-3527-458a-e48a-c0533861c1da_media_.jpg\" /></strong></big></p>\r\n\r\n<p><big><strong>Mavsumga tayyorgarlik ishlari butun poytaxtimiz bо&lsquo;ylab qizg&lsquo;in davom etmoqda.</strong></big></p>\r\n', '0fd3c557-305e-6376-138a-9fa05b33c2b6_lists_.jpg', '1cc7314b-3ecc-8058-1c67-18f34f554499_lists_.jpg', 1164, 1, 4, NULL, 1721305758, 1760931017, '');
